/// The single-row read behind [`Store::get_coding_session`] and its scoped
/// twin.
async fn coding_session_get_pg<'e, E>(
    exec: E,
    graph_id: Uuid,
    session_id: &str,
) -> Result<Option<CodingSession>, StoreError>
where
    E: sqlx::Executor<'e, Database = sqlx::Postgres>,
{
    let row = sqlx::query_as::<_, CodingSessionRow>(
        "SELECT id, graph_id, session_id, session_kind, project_key, title, repo_path, \
                remote_sanitized, hostname, harness_version, model, branch, \
                started_at, last_activity_at, created_at, \
                agent_name, platform, platform_detected, task, \
                parent_session_id, root_session_id, subagent_name \
         FROM coding_sessions WHERE graph_id = $1 AND session_id = $2",
    )
    .bind(graph_id)
    .bind(session_id)
    .fetch_optional(exec)
    .await?;
    Ok(row.map(CodingSession::from))
}

