    async fn list_relationship_edges_by_status_page(
        &self,
        graph_id: Uuid,
        status: EdgeStatus,
        predicate: Option<&str>,
        cursor: Option<(DateTime<Utc>, Uuid)>,
        limit: i64,
    ) -> Result<Vec<RelationshipEdge>, StoreError> {
        let (cursor_at, cursor_id) = match cursor {
            Some((at, id)) => (Some(at), Some(id)),
            None => (None, None),
        };
        let rows: Vec<RelationshipEdgeRow> = sqlx::query_as(
            r#"
            SELECT edge_id, graph_id, src_node_id, predicate, dst_node_id,
                   origin, status, confidence, provenance,
                   created_at, updated_at, version
            FROM relationship_edge
            WHERE graph_id = $1
              AND status = $2
              AND predicate <> 'co_occurs_with'
              AND ($3::text IS NULL OR predicate = $3)
              AND ($4::timestamptz IS NULL OR (created_at, edge_id) < ($4, $5))
            ORDER BY created_at DESC, edge_id DESC
            LIMIT $6
            "#,
        )
        .bind(graph_id)
        .bind(status.as_str())
        .bind(predicate)
        .bind(cursor_at)
        .bind(cursor_id)
        .bind(limit)
        .fetch_all(&self.pool)
        .await?;

        Ok(rows.into_iter().map(relationship_edge_from_row).collect())
    }

