    async fn set_relationship_edge_status(
        &self,
        edge_id: Uuid,
        status: EdgeStatus,
        reviewed_by: Option<Uuid>,
        via: &str,
    ) -> Result<(), StoreError> {
        let mut tx = self.pool.begin().await?;

        let row: Option<RelationshipEdgeRow> = sqlx::query_as(
            r#"
            UPDATE relationship_edge
               SET status     = $2,
                   -- Human decision: strip machine auto_* flags (upgrading a
                   -- machine-confirmed edge to durable, per the upsert's
                   -- sticky CASE) and stamp who resolved it, when, and via
                   -- which surface — the review-conversion metric's raw data.
                   provenance = (provenance - 'auto_confirmed' - 'auto_resolved'
                                            - 'auto_resolution' - 'auto_resolved_at' - 'lifecycle' - 'human_review_status')
                                || jsonb_build_object(
                                       'reviewed_by', $3::uuid,
                                       'reviewed_at', now(),
                                       'via', $4::text),
                   updated_at = now(),
                   version    = version + 1
             WHERE edge_id = $1
            RETURNING edge_id, graph_id, src_node_id, predicate, dst_node_id,
                      origin, status, confidence, provenance,
                      created_at, updated_at, version
            "#,
        )
        .bind(edge_id)
        .bind(status.as_str())
        .bind(reviewed_by)
        .bind(via)
        .fetch_optional(&mut *tx)
        .await?;

        if let Some(row) = row {
            let edge = relationship_edge_from_row(row);
            let op = sync::relationship_edge_op(
                Uuid::new_v4(),
                edge.edge_id,
                edge.graph_id,
                edge.src_node_id,
                &edge.predicate,
                edge.dst_node_id,
                edge.origin.as_str(),
                edge.status.as_str(),
                edge.confidence,
                &edge.provenance,
                edge.created_at,
                edge.updated_at,
                edge.version,
                self.device_id(),
            );
            append_op_tx(&mut tx, &op).await?;

            // Apply the SAME review decision to the materialized inverse edge so
            // a confirm/reject covers the whole relationship — otherwise a
            // rejected claim would leak back through its reverse direction.
            // Predicates that no longer materialize new inverses may still
            // have legacy reverse rows. Review those too; absent inverses are
            // a no-op, and this never creates a new relationship.
            if let Some(inv) = predicates::inverse(&edge.predicate) {
                let inv_row: Option<RelationshipEdgeRow> = sqlx::query_as(
                    r#"
                    UPDATE relationship_edge
                       SET status     = $5,
                           provenance = (provenance - 'auto_confirmed' - 'auto_resolved'
                                                    - 'auto_resolution' - 'auto_resolved_at' - 'lifecycle' - 'human_review_status')
                                        || jsonb_build_object(
                                               'reviewed_by', $6::uuid,
                                               'reviewed_at', now(),
                                               'via', $7::text),
                           updated_at = now(),
                           version    = version + 1
                     WHERE graph_id = $1
                       AND src_node_id = $2
                       AND predicate   = $3
                       AND dst_node_id = $4
                    RETURNING edge_id, graph_id, src_node_id, predicate, dst_node_id,
                              origin, status, confidence, provenance,
                              created_at, updated_at, version
                    "#,
                )
                .bind(edge.graph_id)
                .bind(edge.dst_node_id) // inverse src = forward dst
                .bind(inv)
                .bind(edge.src_node_id) // inverse dst = forward src
                .bind(status.as_str())
                .bind(reviewed_by)
                .bind(via)
                .fetch_optional(&mut *tx)
                .await?;
                if let Some(inv_row) = inv_row {
                    let inv_edge = relationship_edge_from_row(inv_row);
                    let inv_op = sync::relationship_edge_op(
                        Uuid::new_v4(),
                        inv_edge.edge_id,
                        inv_edge.graph_id,
                        inv_edge.src_node_id,
                        &inv_edge.predicate,
                        inv_edge.dst_node_id,
                        inv_edge.origin.as_str(),
                        inv_edge.status.as_str(),
                        inv_edge.confidence,
                        &inv_edge.provenance,
                        inv_edge.created_at,
                        inv_edge.updated_at,
                        inv_edge.version,
                        self.device_id(),
                    );
                    append_op_tx(&mut tx, &inv_op).await?;
                }
            }
        }

        tx.commit().await?;
        Ok(())
    }

    // ── Nodes (reefs) ─────────────────────────────────────────────────────────

    async fn list_nodes(
        &self,
        graph_id: Uuid,
        node_type: Option<&str>,
        page_size: i64,
        offset: i64,
    ) -> Result<Vec<Node>, StoreError> {
        type NodeRow = (
            Uuid,
            String,
            String,
            String,
            DateTime<Utc>,
            DateTime<Utc>,
            i64,
        );

        // `atom_count` is the node's readable links (permitted atoms only),
        // not `nodes.coral_count`; the statements count them from the
        // graph's permitted set in one pass (#1490).
        let rows: Vec<NodeRow> = match node_type {
            None => {
                sqlx::query_as::<_, NodeRow>(verdict::LIST_NODES_SQL)
                .bind(graph_id)
                .bind(page_size)
                .bind(offset)
                .fetch_all(&self.pool)
                .await?
            }
            Some(t) => {
                sqlx::query_as::<_, NodeRow>(verdict::LIST_NODES_OF_TYPE_SQL)
                .bind(graph_id)
                .bind(t)
                .bind(page_size)
                .bind(offset)
                .fetch_all(&self.pool)
                .await?
            }
        };

        Ok(rows
            .into_iter()
            .map(
                |(node_id, node_type, title, scope, created_at, updated_at, atom_count)| Node {
                    node_id,
                    node_type,
                    title,
                    scope,
                    created_at,
                    updated_at,
                    atom_count,
                },
            )
            .collect())
    }

