    async fn reset_meeting_summary_pending(
        &self,
        graph_id: Uuid,
        source_id: &str,
    ) -> Result<SummaryResetOutcome, StoreError> {
        // One atomic statement: the `existing` CTE snapshots whether the row is
        // present; `upd` resets it to `pending` ONLY when it isn't already
        // `running`; the final SELECT (present only when the row exists) reports
        // whether the reset fired. Reset-when-not-running + report-in-one avoids a
        // read-then-write race between two concurrent Retries.
        let row: Option<(bool,)> = sqlx::query_as(
            "WITH existing AS ( \
                 SELECT 1 FROM meeting_transcripts \
                 WHERE graph_id = $1 AND source_id = $2 \
             ), upd AS ( \
                 UPDATE meeting_transcripts \
                 SET summary_status = 'pending', summary_error = NULL, summary_updated_at = now() \
                 WHERE graph_id = $1 AND source_id = $2 \
                   AND summary_status IS DISTINCT FROM 'running' \
                 RETURNING 1 \
             ) \
             SELECT EXISTS (SELECT 1 FROM upd) AS did_reset FROM existing",
        )
        .bind(graph_id)
        .bind(source_id)
        .fetch_optional(&self.pool)
        .await?;
        Ok(match row {
            None => SummaryResetOutcome::NotFound,
            Some((true,)) => SummaryResetOutcome::Reset,
            Some((false,)) => SummaryResetOutcome::AlreadyRunning,
        })
    }

