    async fn insert_speaker_relabel(
        &self,
        graph_id: Uuid,
        source_id: &str,
        surface_form: &str,
        canonical: &str,
        occurrence: Option<i32>,
    ) -> Result<TranscriptCorrection, StoreError> {
        // A user relabel has no source chunk atom; write the nil UUID sentinel
        // (atom_id has no FK — see 0070). kind='speaker', origin='user',
        // status='applied' so it participates in the corrected_text overlay and
        // the existing revert/restore routes with no special-casing.
        type Row = (
            Uuid,
            String,
            String,
            Option<Uuid>,
            Option<f32>,
            String,
            String,
            Option<i32>,
        );
        let row: Row = sqlx::query_as(
            "INSERT INTO transcript_corrections \
                (graph_id, atom_id, source_id, surface_form, canonical, node_id, confidence, \
                 status, kind, origin, occurrence) \
             VALUES ($1, $2, $3, $4, $5, NULL, NULL, 'applied', 'speaker', 'user', $6) \
             RETURNING correction_id, surface_form, canonical, node_id, confidence, status, \
                       kind, occurrence",
        )
        .bind(graph_id)
        .bind(Uuid::nil())
        .bind(source_id)
        .bind(surface_form)
        .bind(canonical)
        .bind(occurrence)
        .fetch_one(&self.pool)
        .await?;
        Ok(TranscriptCorrection {
            correction_id: row.0,
            surface_form: row.1,
            canonical: row.2,
            node_id: row.3,
            confidence: row.4,
            status: row.5,
            kind: row.6,
            occurrence: row.7,
        })
    }

    async fn relabel_summary_owner(
        &self,
        graph_id: Uuid,
        source_id: &str,
        old_owner: &str,
        new_owner: &str,
    ) -> Result<u64, StoreError> {
        // Feature-detect PR #208's `summary` JSONB column (branch
        // cs-uxp3a-meeting-summary, migration 0067). Absent on main → no-op, so
        // this compiles and runs safely against BOTH schema states.
        let has_summary: bool = sqlx::query_scalar(
            "SELECT EXISTS (SELECT 1 FROM information_schema.columns \
             WHERE table_name = 'meeting_transcripts' AND column_name = 'summary')",
        )
        .fetch_one(&self.pool)
        .await?;
        if !has_summary {
            return Ok(0);
        }
        // Rewrite action-item owners that exactly equal the old label. Owners are
        // whole strings, so exact equality is the right match (not whole-word).
        // The SQL COALESCEs the aggregate so an empty `action_items` array can't
        // null out the whole summary column — see `RELABEL_SUMMARY_OWNER_SQL`.
        let res = sqlx::query(RELABEL_SUMMARY_OWNER_SQL)
            .bind(graph_id)
            .bind(source_id)
            .bind(old_owner)
            .bind(new_owner)
            .execute(&self.pool)
            .await?;
        Ok(res.rows_affected())
    }

