    async fn list_meeting_merges(
        &self,
        graph_id: Uuid,
        source_id: &str,
    ) -> Result<Vec<MeetingMerge>, StoreError> {
        // Link merges to this meeting via the kept reef: keep_id must be linked to
        // an atom whose source_id is one of this meeting's chunk atoms (prefix).
        type Row = (Uuid, Uuid, String, String, DateTime<Utc>);
        let rows: Vec<Row> = sqlx::query_as(&format!(
            "SELECT m.merge_id, m.keep_id, n.title, \
                    COALESCE(m.dup_snapshot->>'title', ''), m.created_at \
             FROM node_merges m \
             JOIN nodes n ON n.node_id = m.keep_id \
             WHERE m.graph_id = $1 \
               AND m.undone_at IS NULL \
               AND EXISTS ( \
                   SELECT 1 FROM node_atoms na \
                   JOIN atoms a ON a.atom_id = na.atom_id \
                   WHERE na.node_id = m.keep_id \
                     AND a.graph_id = $1 \
                     AND a.source_id LIKE $2 \
                     AND {floor} \
               ) \
             ORDER BY m.created_at ASC \
             LIMIT {cap}",
            cap = MEETING_DETAIL_CAP + 1,
            floor = crate::history_floor::admits_atom("a")
        ))
        .bind(graph_id)
        .bind(like_prefix(source_id))
        .fetch_all(&self.pool)
        .await?;
        Ok(rows
            .into_iter()
            .map(
                |(merge_id, kept_node_id, kept_title, merged_title, created_at)| MeetingMerge {
                    merge_id,
                    kept_node_id,
                    kept_title,
                    merged_title,
                    created_at,
                },
            )
            .collect())
    }

    async fn list_meeting_new_entities(
        &self,
        graph_id: Uuid,
        source_id: &str,
    ) -> Result<Vec<MeetingEntity>, StoreError> {
        // Entity reefs linked to this meeting's chunk atoms (source_id prefix),
        // created at/after the transcript so we surface only entities this meeting
        // introduced (best-effort).
        type Row = (Uuid, String, DateTime<Utc>);
        let rows: Vec<Row> = sqlx::query_as(&format!(
            "SELECT DISTINCT n.node_id, n.title, n.created_at \
             FROM nodes n \
             JOIN node_atoms na ON na.node_id = n.node_id \
             JOIN atoms a ON a.atom_id = na.atom_id \
             WHERE n.graph_id = $1 \
               AND n.type = 'entity' \
               AND a.graph_id = $1 \
               AND a.source_id LIKE $2 \
               AND {floor} \
               AND n.created_at >= COALESCE( \
                   (SELECT created_at FROM meeting_transcripts \
                    WHERE graph_id = $1 AND source_id = $3), \
                   '-infinity'::timestamptz) \
             ORDER BY n.created_at ASC \
             LIMIT {cap}",
            cap = MEETING_DETAIL_CAP + 1,
            floor = crate::history_floor::admits_atom("a")
        ))
        .bind(graph_id)
        .bind(like_prefix(source_id))
        .bind(source_id)
        .fetch_all(&self.pool)
        .await?;
        Ok(rows
            .into_iter()
            .map(|(node_id, title, created_at)| MeetingEntity {
                node_id,
                title,
                created_at,
            })
            .collect())
    }

