    // ── Coding sessions (coding-session capture, Phase 1, migration 0076) ─────

    async fn upsert_coding_session(
        &self,
        graph_id: Uuid,
        session_id: &str,
        session_kind: &str,
        project_key: Option<&str>,
        title: Option<&str>,
        repo_path: Option<&str>,
        remote_sanitized: Option<&str>,
        hostname: Option<&str>,
        harness_version: Option<&str>,
        model: Option<&str>,
        branch: Option<&str>,
        identity: &SessionIdentity,
    ) -> Result<String, StoreError> {
        let mut tx = self.pool.begin().await?;

        // ── `projects` alias-table lazy upsert (audit P1-4) — must land
        // before/alongside the first time this key is ever stamped, in the
        // SAME transaction so a crash between the two never leaves a
        // `coding_sessions.project_key` with no matching `projects` row.
        // `ON CONFLICT DO NOTHING`: first-write-wins on `display_name` so a
        // later manual rename is never clobbered by a subsequent ingest.
        if let Some(key) = project_key {
            sqlx::query(
                "INSERT INTO projects (graph_id, project_key, display_name) \
                 VALUES ($1, $2, $2) \
                 ON CONFLICT (graph_id, project_key) DO NOTHING",
            )
            .bind(graph_id)
            .bind(key)
            .execute(&mut *tx)
            .await?;
        }

        // ── The `coding_sessions` upsert itself — single statement (audit
        // P1-3), so two concurrent `/mcp` replicas racing on the SAME
        // `(graph_id, session_id)` never interleave a check-then-write gap.
        // SQL shared with the scoped twin: see `coding_session_upsert_pg`.
        let effective_kind = coding_session_upsert_pg(
            &mut *tx,
            graph_id,
            session_id,
            session_kind,
            project_key,
            title,
            repo_path,
            remote_sanitized,
            hostname,
            harness_version,
            model,
            branch,
            identity,
        )
        .await?;

        tx.commit().await?;
        Ok(effective_kind)
    }

