    async fn get_node(&self, node_id: Uuid) -> Result<Option<Node>, StoreError> {
        type NodeRow = (
            Uuid,
            String,
            String,
            String,
            DateTime<Utc>,
            DateTime<Utc>,
            i64,
        );
        // §2.2: `atom_count` reads `nodes.coral_count` directly (retiring the
        // live COUNT(*) previously recomputed on every reef-detail read).
        let row: Option<NodeRow> = sqlx::query_as(
            "SELECT n.node_id, n.type, n.title, n.scope, n.created_at, n.updated_at, \
                    n.coral_count::bigint AS atom_count \
             FROM nodes n \
             WHERE n.node_id = $1",
        )
        .bind(node_id)
        .fetch_optional(&self.pool)
        .await?;
        Ok(row.map(
            |(node_id, node_type, title, scope, created_at, updated_at, atom_count)| Node {
                node_id,
                node_type,
                title,
                scope,
                created_at,
                updated_at,
                atom_count,
            },
        ))
    }

