    async fn get_active_meeting_share_by_token(
        &self,
        token: &str,
    ) -> Result<Option<MeetingShare>, StoreError> {
        type Row = (Uuid, Uuid, String, String, Uuid, DateTime<Utc>);
        // JOIN graphs + `g.archived_at IS NULL`: a member-private ocean
        // archives on offboarding (member-private-oceans PR 7), and this
        // predicate is what makes it "unreachable to everyone" everywhere
        // else (`resolve_reachable_graphs`/`resolve_graph_reachable_by_user`,
        // migration 0091). Without it, a 'link' share minted before the
        // owner's ocean archived would stay resolvable by token FOREVER —
        // including through the purge window — even though every other
        // read path on that ocean 404s. See `ms.revoked_at IS NULL`'s own
        // comment for why this is a filter, not a scope: an archived-owner
        // share must read identically to an unknown/revoked one.
        let row: Option<Row> = sqlx::query_as(
            "SELECT ms.id, ms.graph_id, ms.source_id, ms.visibility, ms.created_by, ms.created_at \
             FROM meeting_shares ms \
             JOIN graphs g ON g.id = ms.graph_id \
             WHERE ms.token = $1 AND ms.revoked_at IS NULL AND g.archived_at IS NULL",
        )
        .bind(token)
        .fetch_optional(&self.pool)
        .await?;
        Ok(row.map(
            |(id, graph_id, source_id, visibility, created_by, created_at)| MeetingShare {
                id,
                graph_id,
                source_id,
                token: token.to_string(),
                visibility,
                created_by,
                created_at,
                revoked_at: None,
            },
        ))
    }

    async fn list_merge_dismissals(&self, graph_id: Uuid) -> Result<Vec<(Uuid, Uuid)>, StoreError> {
        // "Keep separate" partners live in each reef's body.not_same (synced via
        // the node oplog). Stored once (higher id in the lower node); read back
        // as canonical pairs.
        let rows: Vec<(Uuid, Value)> = sqlx::query_as(
            "SELECT node_id, body->'not_same' FROM nodes \
             WHERE graph_id = $1 AND body ? 'not_same'",
        )
        .bind(graph_id)
        .fetch_all(&self.pool)
        .await?;
        let mut out = Vec::new();
        for (node, arr) in rows {
            if let Some(items) = arr.as_array() {
                for p in items {
                    if let Some(partner) = p.as_str().and_then(|s| Uuid::parse_str(s).ok()) {
                        out.push(if node <= partner {
                            (node, partner)
                        } else {
                            (partner, node)
                        });
                    }
                }
            }
        }
        Ok(out)
    }

    async fn insert_merge_dismissal(
        &self,
        _graph_id: Uuid,
        a: Uuid,
        b: Uuid,
    ) -> Result<(), StoreError> {
        // Append the higher id to the lower node's body.not_same (idempotent via
        // jsonb set-union) and emit a node-upsert op so it syncs.
        let (lo, hi) = if a <= b { (a, b) } else { (b, a) };
        let mut tx = self.pool.begin().await?;
        type Row = (
            Uuid,
            String,
            String,
            Value,
            String,
            Option<Uuid>,
            DateTime<Utc>,
            DateTime<Utc>,
            i32,
        );
        let updated: Option<Row> = sqlx::query_as(
            "UPDATE nodes SET \
                 body = jsonb_set(body, '{not_same}', \
                        COALESCE(body->'not_same', '[]'::jsonb) || to_jsonb($2::text)), \
                 updated_at = now(), version = version + 1 \
             WHERE node_id = $1 \
               AND NOT (COALESCE(body->'not_same', '[]'::jsonb) ? $2::text) \
             RETURNING graph_id, type, title, body, scope, owner_id, created_at, updated_at, version",
        )
        .bind(lo)
        .bind(hi.to_string())
        .fetch_optional(&mut *tx)
        .await?;
        if let Some((graph_id, t, ti, body, sc, ow, ca, ua, ve)) = updated {
            append_op_tx(
                &mut tx,
                &sync::node_upsert_op(
                    Uuid::new_v4(),
                    lo,
                    graph_id,
                    &t,
                    &ti,
                    &body.to_string(),
                    &sc,
                    ow,
                    ca,
                    ua,
                    i64::from(ve),
                    self.device_id(),
                ),
            )
            .await?;
        }
        tx.commit().await?;
        Ok(())
    }

