    async fn account_is_personal_org(
        &self,
        account_id: Uuid,
        user_id: Uuid,
    ) -> Result<bool, StoreError> {
        let row: Option<(bool,)> = sqlx::query_as(
            "SELECT EXISTS ( \
                 SELECT 1 FROM accounts a \
                 JOIN personal_orgs po ON po.clerk_org_id = a.clerk_org_id \
                 JOIN users u ON u.clerk_user_id = po.clerk_user_id \
                 WHERE a.id = $1 AND u.id = $2 \
             )",
        )
        .bind(account_id)
        .bind(user_id)
        .fetch_optional(crate::tenancy::scope::request_read(&self.pool))
        .await?;
        Ok(row.map(|(b,)| b).unwrap_or(false))
    }

    async fn account_is_real_org(&self, account_id: Uuid, user_id: Uuid) -> Result<bool, StoreError> {
        let row: Option<(bool,)> = sqlx::query_as(
            "SELECT a.clerk_org_id IS NOT NULL \
               AND NOT EXISTS ( \
                   SELECT 1 FROM personal_orgs p \
                   JOIN users u ON u.clerk_user_id = p.clerk_user_id \
                   WHERE p.clerk_org_id = a.clerk_org_id AND u.id = $2 \
               ) \
               AND NOT EXISTS ( \
                   SELECT 1 FROM org_revocations r WHERE r.clerk_org_id = a.clerk_org_id \
               ) \
             FROM accounts a WHERE a.id = $1",
        )
        .bind(account_id)
        .bind(user_id)
        .fetch_optional(crate::tenancy::scope::request_read(&self.pool))
        .await?;
        match row {
            Some((b,)) => Ok(b),
            // Fail closed: see this method's own doc comment on the trait.
            None => Err(StoreError::NotFound),
        }
    }

