    async fn replace_conversation_oceans(
        &self,
        conversation_id: Uuid,
        graph_ids: &[Uuid],
    ) -> Result<(), StoreError> {
        let mut tx = self.pool.begin().await?;
        sqlx::query("DELETE FROM conversation_oceans WHERE conversation_id = $1")
            .bind(conversation_id)
            .execute(&mut *tx)
            .await?;
        for gid in graph_ids {
            sqlx::query(
                "INSERT INTO conversation_oceans (conversation_id, graph_id) \
                 VALUES ($1, $2) ON CONFLICT DO NOTHING",
            )
            .bind(conversation_id)
            .bind(gid)
            .execute(&mut *tx)
            .await?;
        }
        tx.commit().await?;
        Ok(())
    }

