    async fn insert_auto_supersession_edge(
        &self,
        superseded_id: Uuid,
        superseder_id: Uuid,
    ) -> Result<bool, StoreError> {
        let mut tx = self.pool.begin().await?;

        let result = sqlx::query(
            r#"
        INSERT INTO supersession_edge (superseded_id, superseder_id, source, graph_id)
        VALUES ($1, $2, 'auto', (SELECT graph_id FROM nodes WHERE node_id = $1))
        ON CONFLICT (superseded_id, superseder_id) DO NOTHING
        "#,
        )
        .bind(superseded_id)
        .bind(superseder_id)
        .execute(&mut *tx)
        .await?;
        // `ON CONFLICT DO NOTHING` reports 0 rows affected on the no-op path
        // — this is how the caller learns whether a NEW edge was actually
        // inserted (see the trait doc comment's "true == actually inserted"
        // contract).
        let inserted = result.rows_affected() > 0;

        // Conflict-triggered review (CS-069), same predicate and idempotency
        // guard as `upsert_supersession_edge_with_kind` (T4, 2026-08-08): a
        // freshly-inserted `source='auto'` edge against a `type = 'decision'`
        // reef flips it `confirmed → pending` UNCONDITIONALLY. This writer
        // has no `kind` parameter
        // of its own to consult, so — same as its `_with_kind` sibling —
        // every fresh auto edge on a confirmed decision queues it; there is
        // nothing to gate the flip on beyond "did this call insert a NEW
        // row". Gating on `inserted` (not merely on the row existing) is what
        // keeps a re-detected pair from re-flipping an already-reviewed
        // decision back into the queue.
        type FlippedRow = (
            Uuid,          // graph_id
            String,        // type
            String,        // title
            Value,         // body
            String,        // scope
            Option<Uuid>,  // owner_id
            DateTime<Utc>, // created_at
            DateTime<Utc>, // updated_at
            i32,           // version
        );
        let flipped: Option<FlippedRow> = if inserted {
            sqlx::query_as(
                r#"
            UPDATE nodes
               SET body       = jsonb_set(
                                    jsonb_set(body, '{review_status}', '"pending"'),
                                    '{pending_since}', to_jsonb(now())),
                   updated_at = now(),
                   version    = version + 1
             WHERE node_id = $1
               AND type = 'decision'
               AND body->>'review_status' = 'confirmed'
            RETURNING graph_id, type, title, body, scope, owner_id,
                      created_at, updated_at, version
            "#,
            )
            .bind(superseded_id)
            .fetch_optional(&mut *tx)
            .await?
        } else {
            None
        };

        if let Some((
            f_graph_id,
            ref f_type,
            ref f_title,
            ref f_body,
            ref f_scope,
            f_owner_id,
            f_created_at,
            f_updated_at,
            f_version,
        )) = flipped
        {
            let op = sync::node_upsert_op(
                Uuid::new_v4(),
                superseded_id,
                f_graph_id,
                f_type,
                f_title,
                &f_body.to_string(),
                f_scope,
                f_owner_id,
                f_created_at,
                f_updated_at,
                i64::from(f_version),
                self.device_id(),
            );
            append_op_tx(&mut tx, &op).await?;
        }

        // Look up graph_id from the superseder node so the op is graph-scoped.
        // If the superseder node is already gone (race) skip the op.
        let graph_id: Option<Uuid> =
            sqlx::query_scalar("SELECT graph_id FROM nodes WHERE node_id = $1")
                .bind(superseder_id)
                .fetch_optional(&mut *tx)
                .await?;

        if let Some(gid) = graph_id {
            let op = sync::supersession_op(
                Uuid::new_v4(),
                superseder_id,
                superseded_id,
                gid,
                "auto",
                OpType::Upsert,
                Utc::now(),
                self.device_id(),
            );
            append_op_tx(&mut tx, &op).await?;
        }

        tx.commit().await?;
        Ok(inserted)
    }

    // ── Retrieval ───────────────────────────────────────────────────────────────
    // Ported from the (now-deleted) retrieval/{vector,keyword,expand}.rs free
    // functions. The cosine-distance / rank semantics match the reranker's math.

    async fn vector_search(
        &self,
        graph_id: Uuid,
        embedding: &[f32],
        k: usize,
        filter: &RetrievalFilter,
    ) -> Result<Vec<(Uuid, f32)>, StoreError> {
        use sqlx::Row;

        // pgvector::Vector implements sqlx Encode/Decode for Postgres. Bound once
        // as $1 and referenced in both the SELECT and ORDER BY (Postgres allows
        // reusing a positional parameter).
        //
        // Return cosine *distance* via `<=>` (∈ [0, 2]; lower = more similar) so
        // the reranker's `similarity = 1 - distance/2` holds. The whole
        // expression is cast to ::float4 so the f32 decode matches.
        //
        // The `($n::text IS NULL OR col = $n)` always-bind pattern applies the
        // optional scope / source_type filters without dynamic SQL. The
        // source_type arm is the ARRAY form of that pattern —
        // `($n::text[] IS NULL OR source_type = ANY($n))` bound from
        // `RetrievalFilter::source_type_list()` — so one parameter carries
        // either the legacy single value (a one-element array) or the
        // GitHub-eval multi-tier list (`source_types`, §5), and a NULL array
        // still means "no restriction". Same shape at every other
        // `filter.source_type_list()` bind site in this file.
        //
        // `embed_model_next = $6` restricts matches to atoms
        // embedded by the cloud model that produced the query vector.
        // Vectors from a different embedding model don't share a coordinate
        // space, so comparing across models produces meaningless scores, not
        // just noisy ones. Atoms with `embed_model_next IS NULL` are excluded rather than
        // treated as a match. The live `embedding` / `embed_model` columns hold
        // the bge vector and are not compared here.
        let query_vec = Vector::from(embedding.to_vec());
        // Coding-session capture Phase 3 (D6): `project` is a plain equality
        // filter on `atoms.project` (migration 0072); `session_id` is
        // pre-escaped into an indexed (`idx_atoms_graph_source_id_pattern`,
        // migration 0074) `source_id LIKE 'cc:{session_id}:%'` prefix pattern
        // by `session_source_id_prefix` — the caller (`RetrievalFilter`) only
        // ever holds the RAW session id, never a SQL pattern.
        let session_pattern = filter.session_id.as_deref().map(session_source_id_prefix);

        let rows = sqlx::query(&format!(
            r#"
            SELECT atom_id, (embedding_next <=> $1)::float4 AS score
            FROM   (SELECT * FROM atoms WHERE library_atom_permitted(graph_id,atom_id)) atoms
            WHERE  graph_id = $2
              AND  embedding_next IS NOT NULL
              AND  embed_model_next = $6
              AND  ($4::text IS NULL OR scope       = $4)
              AND  ($5::text[] IS NULL OR source_type = ANY($5))
              AND  ($7::timestamptz IS NULL OR timestamp >= $7)
              AND  ($8::timestamptz IS NULL OR timestamp <= $8)
              AND  ($9::text IS NULL OR project      = $9)
              AND  ($10::text IS NULL OR source_id LIKE $10)
              {agent_filter}
            ORDER  BY embedding_next <=> $1, atom_id
            LIMIT  $3
            "#,
            agent_filter = agent_session_filter_sql(11),
        ))
        .bind(query_vec)
        .bind(graph_id)
        .bind(k as i64)
        .bind(filter.scope.as_deref())
        .bind(filter.source_type_list())
        .bind(coralswarm_core::embed::EMBED_MODEL_CLOUD)
        .bind(filter.since)
        .bind(filter.until)
        .bind(filter.project.as_deref())
        .bind(session_pattern.as_deref())
        .bind(filter.agent_name.as_deref())
        .bind(filter.platform.as_deref())
        .bind(filter.root_session_id.as_deref())
        .fetch_all(&self.pool)
        .await?;

        Ok(rows
            .into_iter()
            .map(|r| {
                let atom_id: Uuid = r.get("atom_id");
                let score: f32 = r.get("score");
                (atom_id, score)
            })
            .collect())
    }

    async fn keyword_search(
        &self,
        graph_id: Uuid,
        query: &str,
        k: usize,
        filter: &RetrievalFilter,
    ) -> Result<Vec<(Uuid, f64)>, StoreError> {
        keyword_search_pg(&self.pool, graph_id, query, k, filter).await
    }

    async fn intake_summary(
        &self,
        graph_id: Uuid,
        since: DateTime<Utc>,
        recent_limit: usize,
        filter: &RetrievalFilter,
    ) -> Result<IntakeSummary, StoreError> {
        // Per-source counts (total = their sum). The `($n::text IS NULL OR col = $n)`
        // always-bind pattern applies the optional filters without dynamic SQL.
        let count_rows: Vec<(String, i64)> = sqlx::query_as(
            r#"
            SELECT source_type, COUNT(*)::int8 AS n
            FROM   (SELECT * FROM atoms WHERE library_atom_permitted(graph_id,atom_id)) atoms
            WHERE  graph_id    = $1
              AND  created_at >= $2
              AND  ($3::text IS NULL OR scope       = $3)
              AND  ($4::text[] IS NULL OR source_type = ANY($4))
            GROUP  BY source_type
            ORDER  BY n DESC, source_type ASC
            "#,
        )
        .bind(graph_id)
        .bind(since)
        .bind(filter.scope.as_deref())
        .bind(filter.source_type_list())
        .fetch_all(&self.pool)
        .await?;

        let mut total: i64 = 0;
        let by_source: Vec<IntakeBucket> = count_rows
            .into_iter()
            .map(|(source_type, count)| {
                total += count;
                IntakeBucket { source_type, count }
            })
            .collect();

        let recent_rows: Vec<(
            Uuid,
            String,
            String,
            DateTime<Utc>,
            DateTime<Utc>,
            Option<String>,
            Option<String>,
            Option<String>,
        )> = sqlx::query_as(
            r#"
            SELECT atom_id, source_type, source_id, timestamp, created_at, channel_id, channel_name, author_name
            FROM   (SELECT * FROM atoms WHERE library_atom_permitted(graph_id,atom_id)) atoms
            WHERE  graph_id    = $1
              AND  created_at >= $2
              AND  ($3::text IS NULL OR scope       = $3)
              AND  ($4::text[] IS NULL OR source_type = ANY($4))
            ORDER  BY created_at DESC
            LIMIT  $5
            "#,
        )
        .bind(graph_id)
        .bind(since)
        .bind(filter.scope.as_deref())
        .bind(filter.source_type_list())
        .bind(recent_limit as i64)
        .fetch_all(&self.pool)
        .await?;

        let recent = recent_rows
            .into_iter()
            .map(
                |(
                    atom_id,
                    source_type,
                    source_id,
                    timestamp,
                    created_at,
                    channel_id,
                    channel_name,
                    author_name,
                )| {
                    Atom {
                        atom_id,
                        source_type,
                        source_id,
                        timestamp,
                        created_at,
                        channel_id,
                        channel_name,
                        author_name,
                    }
                },
            )
            .collect();

        Ok(IntakeSummary {
            total,
            by_source,
            recent,
        })
    }

    async fn intake_summary_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        graph_id: Uuid,
        since: DateTime<Utc>,
        recent_limit: usize,
        filter: &RetrievalFilter,
    ) -> Result<IntakeSummary, StoreError> {
        // Body is deliberately identical to `intake_summary` above except for the
        // executor (`&mut **tx` rather than `&self.pool`) — the same duplication
        // every other `*_scoped` sibling in this impl uses, so the two forms stay
        // trivially diffable.
        let count_rows: Vec<(String, i64)> = sqlx::query_as(
            r#"
            SELECT source_type, COUNT(*)::int8 AS n
            FROM   (SELECT * FROM atoms WHERE library_atom_permitted(graph_id,atom_id)) atoms
            WHERE  graph_id    = $1
              AND  created_at >= $2
              AND  ($3::text IS NULL OR scope       = $3)
              AND  ($4::text[] IS NULL OR source_type = ANY($4))
            GROUP  BY source_type
            ORDER  BY n DESC, source_type ASC
            "#,
        )
        .bind(graph_id)
        .bind(since)
        .bind(filter.scope.as_deref())
        .bind(filter.source_type_list())
        .fetch_all(&mut **tx)
        .await?;

        let mut total: i64 = 0;
        let by_source: Vec<IntakeBucket> = count_rows
            .into_iter()
            .map(|(source_type, count)| {
                total += count;
                IntakeBucket { source_type, count }
            })
            .collect();

        let recent_rows: Vec<(
            Uuid,
            String,
            String,
            DateTime<Utc>,
            DateTime<Utc>,
            Option<String>,
            Option<String>,
            Option<String>,
        )> = sqlx::query_as(
            r#"
            SELECT atom_id, source_type, source_id, timestamp, created_at, channel_id, channel_name, author_name
            FROM   (SELECT * FROM atoms WHERE library_atom_permitted(graph_id,atom_id)) atoms
            WHERE  graph_id    = $1
              AND  created_at >= $2
              AND  ($3::text IS NULL OR scope       = $3)
              AND  ($4::text[] IS NULL OR source_type = ANY($4))
            ORDER  BY created_at DESC
            LIMIT  $5
            "#,
        )
        .bind(graph_id)
        .bind(since)
        .bind(filter.scope.as_deref())
        .bind(filter.source_type_list())
        .bind(recent_limit as i64)
        .fetch_all(&mut **tx)
        .await?;

        let recent = recent_rows
            .into_iter()
            .map(
                |(
                    atom_id,
                    source_type,
                    source_id,
                    timestamp,
                    created_at,
                    channel_id,
                    channel_name,
                    author_name,
                )| {
                    Atom {
                        atom_id,
                        source_type,
                        source_id,
                        timestamp,
                        created_at,
                        channel_id,
                        channel_name,
                        author_name,
                    }
                },
            )
            .collect();

        Ok(IntakeSummary {
            total,
            by_source,
            recent,
        })
    }

    async fn timestamp_window_atoms(
        &self,
        graph_id: Uuid,
        since: DateTime<Utc>,
        until: DateTime<Utc>,
        limit: Option<usize>,
        filter: &RetrievalFilter,
    ) -> Result<Vec<(Uuid, DateTime<Utc>)>, StoreError> {
        use sqlx::Row;

        // Plain range scan on `timestamp` (event time) — no similarity/lexical
        // gate, unlike `vector_search`/`keyword_search`. The
        // `($n::text IS NULL OR col = $n)` always-bind pattern applies the
        // optional scope/source_type/project/session_id filters without
        // dynamic SQL, matching the rest of this file's retrieval methods.
        let session_pattern = filter.session_id.as_deref().map(session_source_id_prefix);

        let rows = sqlx::query(&format!(
            r#"
            SELECT atom_id, timestamp
            FROM   (SELECT * FROM atoms WHERE library_atom_permitted(graph_id,atom_id)) atoms
            WHERE  graph_id   = $1
              AND  timestamp >= $2
              AND  timestamp <= $3
              AND  ($5::text IS NULL OR scope       = $5)
              AND  ($6::text[] IS NULL OR source_type = ANY($6))
              AND  ($7::text IS NULL OR project      = $7)
              AND  ($8::text IS NULL OR source_id LIKE $8)
              {agent_filter}
            ORDER  BY timestamp DESC
            -- `LIMIT NULL` is Postgres for "no limit" (`limit: None`).
            LIMIT  $4
            "#,
            agent_filter = agent_session_filter_sql(9),
        ))
        .bind(graph_id)
        .bind(since)
        .bind(until)
        .bind(limit.map(|l| l as i64))
        .bind(filter.scope.as_deref())
        .bind(filter.source_type_list())
        .bind(filter.project.as_deref())
        .bind(session_pattern.as_deref())
        .bind(filter.agent_name.as_deref())
        .bind(filter.platform.as_deref())
        .bind(filter.root_session_id.as_deref())
        .fetch_all(&self.pool)
        .await?;

        Ok(rows
            .into_iter()
            .map(|r| {
                let atom_id: Uuid = r.get("atom_id");
                let ts: DateTime<Utc> = r.get("timestamp");
                (atom_id, ts)
            })
            .collect())
    }

    async fn expand(
        &self,
        graph_id: Uuid,
        seed_atom_ids: &[Uuid],
        query_embedding: Option<&[f32]>,
    ) -> Result<Vec<NodeWithAtoms>, StoreError> {
        use std::collections::HashMap;

        // Short-circuit: nothing to expand.
        if seed_atom_ids.is_empty() {
            return Ok(vec![]);
        }

        // ── Query 1: find all distinct nodes any seed atom belongs to ─────────
        #[derive(sqlx::FromRow)]
        struct NodeRow {
            node_id: Uuid,
            node_type: String,
            title: String,
        }

        let node_rows: Vec<NodeRow> = sqlx::query_as(
            r#"
            SELECT DISTINCT na.node_id, n.type AS node_type, COALESCE(library_node_title(n.graph_id,n.node_id),'') AS title
            FROM node_atoms na
            JOIN nodes n ON n.node_id = na.node_id
            JOIN atoms seed ON seed.atom_id=na.atom_id AND seed.graph_id=n.graph_id
            WHERE library_atom_permitted(seed.graph_id,seed.atom_id) AND na.atom_id = ANY($1)
              AND n.graph_id = $2 AND library_node_permitted(n.graph_id,n.node_id)
            "#,
        )
        .bind(seed_atom_ids)
        .bind(graph_id)
        .fetch_all(&self.pool)
        .await?;

        if node_rows.is_empty() {
            return Ok(vec![]);
        }

        let node_ids: Vec<Uuid> = node_rows.iter().map(|r| r.node_id).collect();

        // ── Query 2: seeds-first, similarity-ranked siblings per node (D1) ────
        // See `Store::expand`'s doc comment for the full rationale. In short:
        //   - `(na.atom_id = ANY($seeds))` sorts every seed atom to the front of
        //     its node's partition, so seeds are never pushed out by the cap.
        //   - The effective cap is `GREATEST(base cap, seeds actually in that
        //     node)` (the `seed_counts` CTE + `GREATEST` below), not a flat
        //     constant — a node with more seeds than the base cap keeps ALL of
        //     them.
        //   - Filler (non-seed) rows are ranked by cosine distance to
        //     `query_embedding` (`a.embedding_next <=> $3`), restricted to atoms
        //     embedded by the SAME model as the query vector (`a.embed_model =
        //     $4`) — comparing across embedding models is meaningless, not just
        //     noisy (mirrors `Store::vector_search`'s `embed_model` filter).
        //     When `query_embedding` is `None`, or a given filler has no
        //     embedding / a different `embed_model`, its distance is SQL NULL,
        //     which sorts after every real distance (Postgres default
        //     `NULLS LAST` in ascending order) — those rows fall back to the
        //     deterministic `na.atom_id` secondary order.
        #[derive(sqlx::FromRow)]
        struct NodeAtomRow {
            node_id: Uuid,
            atom_id: Uuid,
        }

        let query_vec = query_embedding.map(|e| Vector::from(e.to_vec()));

        let atom_rows: Vec<NodeAtomRow> = sqlx::query_as(
            r#"
            WITH seed_counts AS (
                SELECT na.node_id, COUNT(*) AS seed_count
                FROM node_atoms na
                JOIN atoms a ON a.atom_id=na.atom_id AND a.graph_id=$6
                WHERE library_atom_permitted(a.graph_id,a.atom_id) AND na.node_id = ANY($1)
                  AND na.atom_id = ANY($2)
                GROUP BY na.node_id
            ),
            ranked AS (
                SELECT na.node_id, na.atom_id,
                       ROW_NUMBER() OVER (
                           PARTITION BY na.node_id
                           ORDER BY (na.atom_id = ANY($2)) DESC,
                                    CASE
                                        WHEN $3::vector IS NOT NULL
                                             AND a.embedding_next IS NOT NULL
                                             AND a.embed_model_next = $4
                                        THEN a.embedding_next <=> $3
                                        ELSE NULL
                                    END,
                                    na.atom_id
                       ) AS rn
                FROM node_atoms na
                JOIN (SELECT * FROM atoms WHERE library_atom_permitted(graph_id,atom_id)) a ON a.atom_id = na.atom_id
                WHERE na.node_id = ANY($1) AND a.graph_id=$6
            )
            SELECT ranked.node_id, ranked.atom_id
            FROM ranked
            LEFT JOIN seed_counts sc ON sc.node_id = ranked.node_id
            WHERE ranked.rn <= GREATEST($5::bigint, COALESCE(sc.seed_count, 0))
            ORDER BY ranked.node_id
            "#,
        )
        .bind(node_ids.as_slice())
        .bind(seed_atom_ids)
        .bind(query_vec)
        .bind(coralswarm_core::embed::EMBED_MODEL_CLOUD)
        .bind(MAX_SIBLING_ATOMS_PER_NODE as i64)
        .bind(graph_id)
        .fetch_all(&self.pool)
        .await?;

        // ── Query 3: load atoms from superseder nodes ─────────────────────────
        // For each superseded node in the seed set, pull atoms from the node that
        // supersedes it. `superseded_id` is the original node we already have, so
        // the atom is surfaced under its original context node.
        #[derive(sqlx::FromRow)]
        struct SupersederAtomRow {
            superseded_id: Uuid,
            atom_id: Uuid,
        }

        let superseder_atom_rows: Vec<SupersederAtomRow> = sqlx::query_as(
            r#"
            SELECT se.superseded_id, na.atom_id
            FROM node_atoms na
            JOIN supersession_edge se ON se.superseder_id = na.node_id
            JOIN atoms a ON a.atom_id=na.atom_id AND a.graph_id=$2
            WHERE se.superseded_id = ANY($1::uuid[]) AND library_atom_permitted(a.graph_id,a.atom_id)
            "#,
        )
        .bind(node_ids.as_slice())
        .bind(graph_id)
        .fetch_all(&self.pool)
        .await?;

        // ── Group atom_ids by node_id ─────────────────────────────────────────
        let mut atom_map: HashMap<Uuid, Vec<Uuid>> = HashMap::new();
        for row in atom_rows {
            atom_map.entry(row.node_id).or_default().push(row.atom_id);
        }

        // Inject superseder atoms under the superseded node so callers surface
        // the newer/correct information without knowing about the supersession.
        // Tracked separately in `injected_map` (not just folded into
        // `atom_map`) so the returned `NodeWithAtoms::injected_atom_ids`
        // preserves which entries are borrowed display copies rather than
        // this node's own genuine `node_atoms` membership — the provenance
        // signal `routes::queries::multi_graph_retrieve` needs even when the
        // superseder's own node never separately appears in the expansion.
        let mut injected_map: HashMap<Uuid, Vec<Uuid>> = HashMap::new();
        for row in superseder_atom_rows {
            atom_map
                .entry(row.superseded_id)
                .or_default()
                .push(row.atom_id);
            injected_map
                .entry(row.superseded_id)
                .or_default()
                .push(row.atom_id);
        }

        // ── Combine node metadata with atom lists, sorted by node_id ──────────
        let mut results: Vec<NodeWithAtoms> = node_rows
            .into_iter()
            .map(|n| NodeWithAtoms {
                node_id: n.node_id,
                node_type: n.node_type,
                title: n.title,
                atom_ids: atom_map.remove(&n.node_id).unwrap_or_default(),
                injected_atom_ids: injected_map.remove(&n.node_id).unwrap_or_default(),
            })
            .collect();

        results.sort_by_key(|n| n.node_id);

        Ok(results)
    }

    async fn keyword_search_node_atoms(
        &self,
        graph_id: Uuid,
        query: &str,
        k: usize,
        filter: &RetrievalFilter,
    ) -> Result<Vec<(Uuid, f64)>, StoreError> {
        use sqlx::Row;

        // ── Step 1: qualifying + ranked candidate reef ids (§5.6, D8) ─────────
        // See [`qualified_reef_ids_pg`]'s doc comment for the full rationale
        // (the D8 index-scan fix, the coverage floor, and the full-title-match
        // escape hatch's deliberate deviation from the design-locked spec) —
        // shared with [`Store::matched_reef_ids`] (§5.4) so the two never drift.
        let selected = qualified_reef_ids_pg(&self.pool, graph_id, query, k, filter).await?;
        if selected.is_empty() {
            return Ok(vec![]);
        }

        // ── Step 2: member atoms, only for the final ≤ k selected reefs ───────
        let ids: Vec<Uuid> = selected.iter().map(|(id, _)| *id).collect();
        let atom_rows = sqlx::query(reef_lexical::PERMITTED_MEMBERS_SQL)
            .bind(&ids).bind(graph_id)
            .bind(crate::retrieval::node_query_tokens(query).join(" | ")).fetch_all(&self.pool).await?;

        let mut atoms_by_node: std::collections::HashMap<Uuid, Vec<Uuid>> =
            std::collections::HashMap::new();
        for row in atom_rows {
            let node_id: Uuid = row.get("node_id");
            let atom_id: Uuid = row.get("atom_id");
            atoms_by_node.entry(node_id).or_default().push(atom_id);
        }

        Ok(flatten_reef_atoms(selected, atoms_by_node))
    }

    async fn matched_reef_ids(
        &self,
        graph_id: Uuid,
        query: &str,
        k: usize,
        filter: &RetrievalFilter,
    ) -> Result<Vec<(Uuid, f64)>, StoreError> {
        qualified_reef_ids_pg(&self.pool, graph_id, query, k, filter).await
    }

    async fn reef_atoms_ranked_by_similarity(
        &self,
        graph_id: Uuid,
        node_ids: &[Uuid],
        query_embedding: Option<&[f32]>,
    ) -> Result<std::collections::HashMap<Uuid, Vec<Uuid>>, StoreError> {
        reef_atoms_ranked_by_similarity_pg(&self.pool, graph_id, node_ids, query_embedding).await
    }

    // ── Oplog (ADR-0005) ────────────────────────────────────────────────────────

    /// The cloud is a single logical device regardless of instance count.
    fn device_id(&self) -> &str {
        CLOUD_DEVICE_ID
    }

    /// Append an op to the oplog outside of a mutation transaction (e.g. from
    /// an embed/extract worker).  Returns the assigned monotonic `seq`.
    async fn append_op(&self, op: &NewOp) -> Result<i64, StoreError> {
        let seq: i64 = sqlx::query_scalar(
            "INSERT INTO op_log \
                 (op_id, entity, entity_id, op_type, payload, version, updated_at, device_id, graph_id) \
             VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9) \
             RETURNING seq",
        )
        .bind(op.op_id)
        .bind(&op.entity)
        .bind(&op.entity_id)
        .bind(op.op_type.as_str())
        .bind(&op.payload)
        .bind(op.version)
        .bind(op.updated_at)
        .bind(&op.device_id)
        .bind(op.graph_id)
        .fetch_one(&self.pool)
        .await?;
        Ok(seq)
    }

    /// Delete tombstone ops older than `cutoff` (the 30-day trash purge) —
    /// AND, FM-1 (B2 unit 02), every OTHER op still sitting in `op_log`
    /// under the same `(entity, entity_id)` (the `upsert` ops
    /// `store::sync::atom_content_op`/`atom_create_op`/`atom_embedding_op`
    /// carry, none of which this sweep used to reach — see
    /// `services::deletion::delete_atom_cascade`'s tombstone-building
    /// comment for the failure this closes). Before this fix, an entity's
    /// `upsert` history outlived its own tombstone forever: this predicate
    /// only ever matched `op_type = 'delete'`, so an atom's `content_inline`
    /// upsert op sat in "the 30-day trash can" unswept at ANY age, R2 blob
    /// or not.
    ///
    /// **CORRECTNESS-CRITICAL SCOPING, added on review (this table's
    /// `entity_id` is DETERMINISTIC, not a fresh uuid per row).**
    /// `(entity, entity_id)` pairs are reused across an entity's lifetime —
    /// `node_atom`'s `entity_id` is `compose_id(node_id, atom_id)`
    /// (`store/sync.rs:537`), so `merge_nodes` deleting a link and a LATER
    /// `unmerge_nodes` re-linking the same pair emits a `delete` then,
    /// potentially much later, a fresh `upsert` under the IDENTICAL
    /// `entity_id`; the same shape applies to `supersession_edge` and to an
    /// atom re-created at the same id (`routes/sync.rs:863-885` documents
    /// that case as legitimate). An earlier version of this fix deleted
    /// EVERY row sharing a stale tombstone's `(entity, entity_id)` —
    /// including ops NEWER than the tombstone, i.e. a legitimate relink
    /// that happened AFTER the entity was deleted. That would silently
    /// destroy a fresh op before it is ever pushed to every peer, and peers
    /// whose cursor predates that op's `seq` would never learn the link was
    /// restored — permanent divergence, exactly the failure
    /// `beyond_resurrection_horizon` (`routes/sync.rs`) exists to prevent
    /// on the OTHER side of this same op_log.
    ///
    /// The fix: only purge `(entity, entity_id)` pairs whose stale tombstone
    /// is ALSO that entity's CURRENT (highest-`seq`) op — i.e. nothing newer
    /// exists for that identity. When that holds, the entity has been dead,
    /// continuously, since before `cutoff`, and every op under its identity
    /// (the tombstone and everything that preceded it) is safe to purge
    /// together. When a newer op exists (a relink/recreate), NONE of that
    /// identity's ops are touched, however old the stale tombstone is —
    /// correctness over reclaiming space early; the next cycle re-evaluates
    /// it. `idx_op_log_tombstones` (`0023_sync_oplog.sql:41`) still serves
    /// the candidate scan; `idx_op_log_entity (entity, entity_id, seq DESC)`
    /// serves both the per-candidate "is anything newer" existence check
    /// and the final delete's `(entity, entity_id) IN (...)` lookup — see
    /// `Store::purge_expired_tombstones_scoped` below for the identical
    /// query.
    ///
    /// Entity-agnostic by construction (not just `entity = 'atom'`): a
    /// deleted `node`'s prior upsert ops (title/body) carry the identical
    /// shape of leak and get the identical fix.
    ///
    /// Bounded to [`TOMBSTONE_PURGE_BATCH_LIMIT`] candidates per call (see
    /// that constant's own doc for the measured plans/timings this bound is
    /// based on, finding 11 independent review) — a call it returns
    /// `TOMBSTONE_PURGE_BATCH_LIMIT` for means more work remains; the daily
    /// worker tick (`workers::tombstone_purge`) simply picks it up again
    /// next cycle.
    /// Returns the number of rows removed.
    async fn purge_expired_tombstones(&self, cutoff: DateTime<Utc>) -> Result<u64, StoreError> {
        let result = sqlx::query(
            "DELETE FROM op_log \
             WHERE (entity, entity_id) IN ( \
                 SELECT st.entity, st.entity_id \
                 FROM op_log st \
                 WHERE st.op_type = 'delete' AND st.updated_at < $1 \
                   AND NOT EXISTS ( \
                       SELECT 1 FROM op_log newer \
                       WHERE newer.entity = st.entity \
                         AND newer.entity_id = st.entity_id \
                         AND newer.seq > st.seq \
                   ) \
                 LIMIT $2 \
             )",
        )
            .bind(cutoff)
            .bind(TOMBSTONE_PURGE_BATCH_LIMIT)
            .execute(&self.pool)
            .await?;
        Ok(result.rows_affected())
    }

    // ── Embedding write seam ────────────────────────────────────────────────────

    /// Write embeddings for a batch of atoms and record one `atom_embedding_op`
    /// per atom.
    /// Slices are positional and must be equal length. Every written atom is
    /// stamped with the currently-active `embed_model` /
    /// `coralswarm_core::chunker::CHUNKER_VERSION` (migration 0063) so
    /// `vector_search` can filter out atoms embedded by a stale/different
    /// model. Rejects the whole batch (defense in depth, no partial write) if
    /// any embedding is an all-zero vector — see [`sync::is_zero_vector`]:
    /// a broken/stub embedder previously persisted zero vectors into
    /// production silently, corrupting cosine similarity search.
    ///
    /// Batched in a single transaction with three round-trips regardless of
    /// batch size: one `SELECT … WHERE atom_id = ANY` for graph-id lookup, one
    /// `UPDATE … FROM (unnest…)` for the embeddings, one
    /// `INSERT … SELECT FROM unnest(…)` for the ops. Replaces the previous
    /// per-atom tx loop (review H12g) — at the embed worker's 64-atom batch
    /// size that's a ~64× reduction in PG round-trips.
    async fn set_atom_embeddings(
        &self,
        atom_ids: &[Uuid],
        embeddings: &[Vec<f32>],
    ) -> Result<(), StoreError> {
        if atom_ids.len() != embeddings.len() {
            return Err(StoreError::Db(
                format!(
                    "set_atom_embeddings: atom_ids ({}) != embeddings ({})",
                    atom_ids.len(),
                    embeddings.len()
                )
                .into(),
            ));
        }
        if atom_ids.is_empty() {
            return Ok(());
        }
        if let Some(pos) = embeddings.iter().position(|v| sync::is_zero_vector(v)) {
            return Err(StoreError::Db(
                format!(
                    "set_atom_embeddings: refusing to persist an all-zero embedding vector \
                     for atom {} (batch index {pos}) — this is the signature of a stub/broken \
                     embedder, not a real model output",
                    atom_ids[pos]
                )
                .into(),
            ));
        }

        let now = Utc::now();
        let device_id = self.device_id().to_string();
        let mut tx = self.pool.begin().await?;

        // ── 1. Batched graph_id lookup ──────────────────────────────────────
        let lookup_rows: Vec<(Uuid, Uuid)> =
            sqlx::query_as("SELECT atom_id, graph_id FROM atoms WHERE atom_id = ANY($1)")
                .bind(atom_ids)
                .fetch_all(&mut *tx)
                .await?;
        let graph_by_atom: std::collections::HashMap<Uuid, Uuid> =
            lookup_rows.into_iter().collect();

        // ── 2. Build parallel arrays for the bulk UPDATE + INSERT ───────────
        //
        // Vanished atoms (deleted between ingest and embed) are silently
        // dropped, matching the previous per-atom-tx behaviour.
        let n = atom_ids.len();
        let mut write_ids: Vec<Uuid> = Vec::with_capacity(n);
        let mut write_vecs: Vec<Vector> = Vec::with_capacity(n);
        let mut op_op_ids: Vec<Uuid> = Vec::with_capacity(n);
        let mut op_entities: Vec<String> = Vec::with_capacity(n);
        let mut op_entity_ids: Vec<String> = Vec::with_capacity(n);
        let mut op_types: Vec<String> = Vec::with_capacity(n);
        let mut op_payloads: Vec<Value> = Vec::with_capacity(n);
        let mut op_versions: Vec<i64> = Vec::with_capacity(n);
        let mut op_updateds: Vec<DateTime<Utc>> = Vec::with_capacity(n);
        let mut op_devices: Vec<String> = Vec::with_capacity(n);
        let mut op_graphs: Vec<Uuid> = Vec::with_capacity(n);

        for (atom_id, embedding) in atom_ids.iter().zip(embeddings.iter()) {
            let Some(&gid) = graph_by_atom.get(atom_id) else {
                continue;
            };
            write_ids.push(*atom_id);
            write_vecs.push(Vector::from(embedding.clone()));

            let new_op = sync::atom_embedding_op(
                Uuid::new_v4(),
                *atom_id,
                gid,
                embedding,
                coralswarm_core::embed::EMBED_MODEL_NAME,
                coralswarm_core::chunker::CHUNKER_VERSION,
                now,
                &device_id,
            );
            op_op_ids.push(new_op.op_id);
            op_entities.push(new_op.entity);
            op_entity_ids.push(new_op.entity_id);
            op_types.push(new_op.op_type.as_str().to_string());
            op_payloads.push(new_op.payload);
            op_versions.push(new_op.version);
            op_updateds.push(new_op.updated_at);
            op_devices.push(new_op.device_id);
            op_graphs.push(gid);
        }

        if write_ids.is_empty() {
            // All atoms vanished; nothing to write.
            tx.commit().await?;
            return Ok(());
        }

        // ── 3. Batched UPDATE of embeddings (one round-trip) ────────────────
        // embed_model / chunker_version are the same for the whole batch (one
        // embedder call produced it), so they're bound as scalars ($3, $4)
        // rather than unnested per-row arrays.
        sqlx::query(
            "UPDATE atoms \
             SET    embedding = v.embedding, \
                    embed_model = $3, \
                    chunker_version = $4 \
             FROM   (SELECT unnest($1::uuid[])   AS atom_id, \
                            unnest($2::vector[]) AS embedding) v \
             WHERE  atoms.atom_id = v.atom_id",
        )
        .bind(&write_ids)
        .bind(&write_vecs)
        .bind(coralswarm_core::embed::EMBED_MODEL_NAME)
        .bind(coralswarm_core::chunker::CHUNKER_VERSION)
        .execute(&mut *tx)
        .await?;

        // ── 4. Batched op_log INSERT (one round-trip) ───────────────────────
        //
        // `UNNEST(arr1, arr2, …)` returns one row per index with one column
        // per array, then `INSERT … SELECT … FROM UNNEST(…) AS t(…)` writes
        // all N op_log rows in a single statement. The arrays must be the
        // same length — guaranteed by the single push-per-iteration build
        // above.
        sqlx::query(
            "INSERT INTO op_log \
                 (op_id, entity, entity_id, op_type, payload, version, updated_at, device_id, graph_id) \
             SELECT op_id, entity, entity_id, op_type, payload, version, updated_at, device_id, graph_id \
             FROM   UNNEST($1::uuid[], $2::text[], $3::text[], $4::text[], $5::jsonb[], \
                           $6::int8[], $7::timestamptz[], $8::text[], $9::uuid[]) \
                       AS t(op_id, entity, entity_id, op_type, payload, version, updated_at, device_id, graph_id)",
        )
        .bind(&op_op_ids)
        .bind(&op_entities)
        .bind(&op_entity_ids)
        .bind(&op_types)
        .bind(&op_payloads)
        .bind(&op_versions)
        .bind(&op_updateds)
        .bind(&op_devices)
        .bind(&op_graphs)
        .execute(&mut *tx)
        .await?;

        tx.commit().await?;
        Ok(())
    }

    async fn set_cloud_embeddings(
        &self,
        atom_ids: &[Uuid],
        embeddings: &[Vec<f32>],
    ) -> Result<(), StoreError> {
        let (ids, vecs) = cloud_embedding_batch(atom_ids, embeddings)?;
        if ids.is_empty() {
            return Ok(());
        }
        sqlx::query(
            "UPDATE atoms \
             SET    embedding_next = v.embedding, \
                    embed_model_next = $3 \
             FROM   (SELECT unnest($1::uuid[])   AS atom_id, \
                            unnest($2::vector[]) AS embedding) v \
             WHERE  atoms.atom_id = v.atom_id",
        )
        .bind(&ids)
        .bind(&vecs)
        .bind(coralswarm_core::embed::EMBED_MODEL_CLOUD)
        .execute(&self.pool)
        .await?;
        Ok(())
    }

    // ── Node / node_atom write seams (review H12) ───────────────────────────────

    /// Upsert a reef by `(graph_id, type, title)` and record a node-upsert op
    /// carrying the full post-write row snapshot. Used by the cloud extract
    /// worker.
    async fn resolve_reef_ref(
        &self,
        graph_id: Uuid,
        node_type: &str,
        mention: &str,
        ctx: &ReefRefCtx,
    ) -> Result<ReefResolution, StoreError> {
        let mut tx = self.pool.begin().await?;
        let result = door_resolve_reef_ref_core(&mut tx, graph_id, node_type, mention, ctx).await;
        // Read-only — nothing to commit either way.
        tx.rollback().await.ok();
        result
    }

    async fn resolve_reef_ref_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        graph_id: Uuid,
        node_type: &str,
        mention: &str,
        ctx: &ReefRefCtx,
    ) -> Result<ReefResolution, StoreError> {
        door_resolve_reef_ref_core(tx, graph_id, node_type, mention, ctx).await
    }

    async fn mint_reef(
        &self,
        graph_id: Uuid,
        node_type: &str,
        title: &str,
        ctx: &ReefRefCtx,
    ) -> Result<Uuid, StoreError> {
        let mut tx = self.pool.begin().await?;
        let node_id =
            door_mint_reef_core(&mut tx, graph_id, node_type, title, ctx, self.device_id()).await?;
        tx.commit().await?;
        Ok(node_id)
    }

    async fn mint_reef_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        graph_id: Uuid,
        node_type: &str,
        title: &str,
        ctx: &ReefRefCtx,
    ) -> Result<Uuid, StoreError> {
        door_mint_reef_core(tx, graph_id, node_type, title, ctx, self.device_id()).await
    }

    /// Re-implemented on top of the identity-resolution-at-the-door seam
    /// (design doc §10.2/§10.2's "Legacy wrappers" paragraph): resolves
    /// through [`door_resolve_reef_ref_core`]'s full ladder (identifier,
    /// title/alias, permutation, then a consequential near-match) before
    /// ever minting — this is precisely what closes "Door B" (§2 of the
    /// design doc: this method used to be a bare `INSERT ... ON CONFLICT`
    /// with no alias/identifier lookup at all). `NearMatch` and `Unknown`
    /// both mint (this wrapper has no LLM handle to adjudicate a near-match
    /// with). A `Resolved` hit via anything other than an exact title match
    /// teaches the incoming spelling as an alias, matching
    /// `upsert_node_and_link_atom`'s existing fold behaviour — Door A and
    /// Door B now fold identically. `Rejected` maps to the same
    /// `Err(StoreError::RejectedPlaceholder(_))` this method has always
    /// returned, so every existing caller's error handling is unchanged.
    async fn upsert_node(
        &self,
        graph_id: Uuid,
        node_type: &str,
        title: &str,
    ) -> Result<Uuid, StoreError> {
        let ctx = ReefRefCtx {
            worker: "upsert_node",
            ..Default::default()
        };
        let mut tx = self.pool.begin().await?;
        let resolution = door_resolve_reef_ref_core(&mut tx, graph_id, node_type, title, &ctx).await?;
        let node_id = match resolution {
            ReefResolution::Resolved { node_id, how } if how != ResolveHow::Title => {
                door_attach_reef_alias_core(
                    &mut tx,
                    graph_id,
                    node_id,
                    &title.to_lowercase(),
                    self.device_id(),
                )
                .await?;
                node_id
            }
            ReefResolution::Resolved { node_id, .. } => node_id,
            ReefResolution::NearMatch { .. } | ReefResolution::Unknown => {
                door_mint_reef_core(&mut tx, graph_id, node_type, title, &ctx, self.device_id()).await?
            }
            ReefResolution::Rejected(reason) => {
                tx.rollback().await.ok();
                tracing::info!(
                    %graph_id,
                    node_type,
                    title,
                    reason = %reason,
                    "upsert_node: rejected at the identity-resolution door (§10.2)"
                );
                return Err(StoreError::RejectedPlaceholder(title.to_string()));
            }
        };
        tx.commit().await?;
        Ok(node_id)
    }

    async fn promote_node(
        &self,
        source_node_id: Uuid,
        target_graph_id: Uuid,
        promoted_by: Uuid,
        coral_ids: Option<&[Uuid]>,
        blob_mode: BlobCopyMode<'_>,
    ) -> Result<Promotion, StoreError> {
        let mut tx = self.pool.begin().await?;

        // Snapshot the source reef — it is never modified by promotion.
        let src: Option<(String, String, Value, i32, Uuid)> = sqlx::query_as(
            "SELECT type, title, body, version, graph_id FROM nodes WHERE node_id = $1",
        )
        .bind(source_node_id)
        .fetch_optional(&mut *tx)
        .await?;
        let Some((node_type, title, body, from_version, src_graph_id)) = src else {
            return Err(StoreError::NotFound);
        };

        // The published copy's scope is the target ocean's level ('team'|'org').
        let target_kind: Option<String> =
            sqlx::query_scalar("SELECT kind FROM graphs WHERE id = $1")
                .bind(target_graph_id)
                .fetch_optional(&mut *tx)
                .await?;
        let Some(scope) = target_kind else {
            return Err(StoreError::NotFound);
        };

        // Publish (or re-publish) the copy, keyed by
        // (graph_id, promoted_from_node_id) — NOT title (§4.5 of
        // docs/plans/graph-temporal-memory.md): renaming the source reef and
        // re-promoting must update the SAME target row rather than fork a
        // second, orphaned one under the new title. `node_promotions` below
        // still records provenance (who/when/from-what-version); this column
        // pair is the separate identity the upsert's conflict target itself
        // needs — the two were conflated before this migration, which is
        // exactly what let a rename slip a duplicate past `node_promotions`'
        // own upsert (it only repoints `target_node_id`, it does not delete
        // the orphan the title-keyed INSERT just created).
        // Copying `body` verbatim preserves the decisions_require_decided_at CHECK.
        type CopyRow = (
            Uuid,
            Value,
            String,
            Option<Uuid>,
            DateTime<Utc>,
            DateTime<Utc>,
            i32,
        );
        let (target_node_id, body_out, scope_out, owner_out, created_at, updated_at, version): CopyRow =
            sqlx::query_as(
                "INSERT INTO nodes \
                     (node_id, graph_id, type, title, body, scope, owner_id, created_at, updated_at, \
                      promoted_from_node_id, promoted_from_graph_id) \
                 VALUES (gen_random_uuid(), $1, $2, $3, $4, $5, $6, now(), now(), $7, $8) \
                 ON CONFLICT (graph_id, promoted_from_node_id) \
                 DO UPDATE SET title = EXCLUDED.title, body = EXCLUDED.body, scope = EXCLUDED.scope, \
                               updated_at = now(), version = nodes.version + 1 \
                 RETURNING node_id, body, scope, owner_id, created_at, updated_at, version",
            )
            .bind(target_graph_id)
            .bind(&node_type)
            .bind(&title)
            .bind(&body)
            .bind(&scope)
            .bind(promoted_by)
            .bind(source_node_id)
            .bind(src_graph_id)
            .fetch_one(&mut *tx)
            .await?;

        // Record provenance; re-promote updates the existing (source, target)
        // mapping. `xmax = 0` is true only when this row was freshly inserted.
        let created: bool = sqlx::query_scalar(
            "INSERT INTO node_promotions \
                 (source_node_id, target_graph_id, target_node_id, promoted_by, from_version) \
             VALUES ($1, $2, $3, $4, $5) \
             ON CONFLICT (source_node_id, target_graph_id) \
             DO UPDATE SET target_node_id = EXCLUDED.target_node_id, \
                           promoted_by = EXCLUDED.promoted_by, \
                           from_version = EXCLUDED.from_version, \
                           promoted_at = now() \
             RETURNING (xmax = 0)",
        )
        .bind(source_node_id)
        .bind(target_graph_id)
        .bind(target_node_id)
        .bind(promoted_by)
        .bind(from_version)
        .fetch_one(&mut *tx)
        .await?;

        // Emit a node-upsert op so the published copy syncs to peers.
        let op = sync::node_upsert_op(
            Uuid::new_v4(),
            target_node_id,
            target_graph_id,
            &node_type,
            &title,
            &body_out.to_string(),
            &scope_out,
            owner_out,
            created_at,
            updated_at,
            i64::from(version),
            self.device_id(),
        );
        append_op_tx(&mut tx, &op).await?;

        tx.commit().await?;

        // Corals are additive/widening (ADR-0006): copy the requested subset
        // (or every coral attached to the source reef, when unspecified) into
        // the target and link them to the just-published copy. Both
        // `copy_atoms_to_graph` and `link_node_atom` are idempotent (ON
        // CONFLICT DO NOTHING), so a narrower re-promote never drops corals
        // an earlier, wider promote already copied — corals only ever
        // accumulate on the target reef.
        let src_atom_ids: Vec<Uuid> = match coral_ids {
            Some(ids) => ids.to_vec(),
            None => self.node_atom_ids(source_node_id).await?,
        };
        let corals_copied = if src_atom_ids.is_empty() {
            0
        } else {
            let target_atom_ids = self
                .copy_atoms_to_graph(&src_atom_ids, target_graph_id, blob_mode)
                .await?;
            for atom_id in &target_atom_ids {
                self.link_node_atom(target_node_id, *atom_id).await?;
            }

            target_atom_ids.len()
        };

        Ok(Promotion {
            source_node_id,
            target_graph_id,
            target_node_id,
            created,
            // The unscoped twin still copies corals inline (this PR converts
            // only the scoped path — see `Store::promote_node_scoped`'s doc
            // comment for why that is the one actually reachable at the
            // corpus sizes that motivated this change), so `corals_copied`
            // and `corals_requested` are still the same number here, and
            // there is no job to report.
            corals_requested: corals_copied,
            job_id: None,
        })
    }

    async fn copy_atoms_to_graph(
        &self,
        src_atom_ids: &[Uuid],
        target_graph_id: Uuid,
        blob_mode: BlobCopyMode<'_>,
    ) -> Result<Vec<Uuid>, StoreError> {
        if src_atom_ids.is_empty() {
            return Ok(vec![]);
        }
        let mut tx = self.pool.begin().await?;
        let all = self
            .copy_atoms_to_graph_core(&mut tx, src_atom_ids, target_graph_id, blob_mode, false)
            .await?;
        tx.commit().await?;
        Ok(all)
    }

    /// Link an atom to a node, idempotently. Records a node_atom-upsert op only
    /// when a new row is inserted (re-linking is a no-op for both state and
    /// the oplog).
    async fn link_node_atom(&self, node_id: Uuid, atom_id: Uuid) -> Result<(), StoreError> {
        let mut tx = self.pool.begin().await?;

        let result = sqlx::query(
            "INSERT INTO node_atoms (node_id, atom_id) \
             VALUES ($1, $2) \
             ON CONFLICT DO NOTHING",
        )
        .bind(node_id)
        .bind(atom_id)
        .execute(&mut *tx)
        .await;

        let inserted = match result {
            Ok(r) => r.rows_affected() > 0,
            Err(e) if is_pg_conflict(&e) => {
                // FK violation: atom (or node) is not present. Treat as a
                // harmless skip rather than aborting the worker — matches
                // apply_remote_op's NODE_ATOM Upsert constraint behaviour.
                tracing::warn!(
                    node_id = %node_id,
                    atom_id = %atom_id,
                    "link_node_atom: constraint violation ({e}); skipping"
                );
                tx.rollback().await?;
                return Ok(());
            }
            Err(e) => {
                tx.rollback().await?;
                return Err(e.into());
            }
        };

        if !inserted {
            // Link already exists — no state change, no op.
            tx.commit().await?;
            return Ok(());
        }

        // Look up graph_id inside the same transaction so the op is correctly
        // scoped.
        let graph_id: Option<Uuid> =
            sqlx::query_scalar("SELECT graph_id FROM nodes WHERE node_id = $1")
                .bind(node_id)
                .fetch_optional(&mut *tx)
                .await?;

        let Some(gid) = graph_id else {
            // Node disappeared between insert and lookup (would have been an
            // FK violation above on most schemas, but guard anyway). The link
            // row is still committed; skip the op.
            tx.commit().await?;
            return Ok(());
        };

        let op = sync::node_atom_op(
            Uuid::new_v4(),
            node_id,
            atom_id,
            gid,
            OpType::Upsert,
            Utc::now(),
            self.device_id(),
        );
        append_op_tx(&mut tx, &op).await?;

        tx.commit().await?;
        Ok(())
    }

    /// Combined node upsert + atom link in a single transaction (review #5).
    /// Mirrors `upsert_node` + `link_node_atom` but commits both writes and
    /// both ops together so a crash between them can't produce duplicate
    /// node-upsert ops on retry.
    async fn upsert_node_and_link_atom(
        &self,
        graph_id: Uuid,
        node_type: &str,
        title: &str,
        atom_id: Uuid,
    ) -> Result<Option<Uuid>, StoreError> {
        let mut tx = self.pool.begin().await?;
        let node_id = door_upsert_node_and_link_atom_core(
            &mut tx,
            graph_id,
            node_type,
            title,
            atom_id,
            self.device_id(),
        )
        .await?;
        if node_id.is_none() {
            tx.rollback().await.ok();
            return Ok(None);
        }
        tx.commit().await?;
        Ok(node_id)
    }

    async fn create_decision_candidate_and_link_atom(
        &self,
        graph_id: Uuid,
        title: &str,
        body_json: &str,
        atom_id: Uuid,
    ) -> Result<Uuid, StoreError> {
        type UpsertRow = (
            Uuid,          // node_id
            Value,         // body (jsonb)
            String,        // scope
            Option<Uuid>,  // owner_id
            DateTime<Utc>, // created_at
            DateTime<Utc>, // updated_at
            i32,           // version
        );

        let mut tx = self.pool.begin().await?;

        // INSERT carries the populated body; ON CONFLICT deliberately does NOT
        // touch body, so a re-extraction of the same atom cannot clobber a
        // human's confirm/reject verdict — it only bumps version + re-links.
        let row: UpsertRow = sqlx::query_as(
            "INSERT INTO nodes (node_id, graph_id, type, title, body, created_at, updated_at) \
             VALUES (gen_random_uuid(), $1, 'decision', $2, $3::jsonb, now(), now()) \
             ON CONFLICT (graph_id, type, lower(title), identity_scope) \
             DO UPDATE SET updated_at = now(), version = nodes.version + 1 \
             RETURNING node_id, body, scope, owner_id, created_at, updated_at, version",
        )
        .bind(graph_id)
        .bind(title)
        .bind(body_json)
        .fetch_one(&mut *tx)
        .await?;

        let (node_id, body, scope, owner_id, created_at, updated_at, version) = row;

        let node_op = sync::node_upsert_op(
            Uuid::new_v4(),
            node_id,
            graph_id,
            "decision",
            title,
            &body.to_string(),
            &scope,
            owner_id,
            created_at,
            updated_at,
            i64::from(version),
            self.device_id(),
        );
        append_op_tx(&mut tx, &node_op).await?;

        let link = sqlx::query(
            "INSERT INTO node_atoms (node_id, atom_id) \
             VALUES ($1, $2) \
             ON CONFLICT DO NOTHING",
        )
        .bind(node_id)
        .bind(atom_id)
        .execute(&mut *tx)
        .await?;

        if link.rows_affected() > 0 {
            let link_op = sync::node_atom_op(
                Uuid::new_v4(),
                node_id,
                atom_id,
                graph_id,
                OpType::Upsert,
                Utc::now(),
                self.device_id(),
            );
            append_op_tx(&mut tx, &link_op).await?;
        }

        tx.commit().await?;
        Ok(node_id)
    }

    async fn list_pending_decision_candidates(
        &self,
        account_id: Uuid,
        readable_graph_ids: &[Uuid],
        cursor: Option<(DateTime<Utc>, Uuid)>,
        limit: i64,
    ) -> Result<Vec<DecisionCandidate>, StoreError> {
        type Row = (
            Uuid,          // node_id
            Uuid,          // graph_id
            String,        // title
            Value,         // body (jsonb)
            DateTime<Utc>, // created_at
            Vec<Uuid>,     // source_atom_ids
        );

        // Row-value `<` against the `(created_at DESC, node_id DESC)` order.
        // The keyset lives in WHERE rather than HAVING because both columns
        // are grouping keys, so it filters before aggregation.
        let (cursor_at, cursor_id) = match cursor {
            Some((at, id)) => (Some(at), Some(id)),
            None => (None, None),
        };
        let rows: Vec<Row> = sqlx::query_as(
            "SELECT n.node_id, n.graph_id, n.title, n.body, n.created_at, \
                    COALESCE( \
                        array_agg(na.atom_id) FILTER (WHERE na.atom_id IS NOT NULL), \
                        '{}'::uuid[] \
                    ) AS source_atom_ids \
             FROM nodes n \
             JOIN graphs g ON g.id = n.graph_id \
             LEFT JOIN node_atoms na ON na.node_id = n.node_id \
             WHERE g.account_id = $1 \
               AND n.graph_id = ANY($5::uuid[]) \
               AND n.type = 'decision' \
               AND n.body->>'review_status' = 'pending' \
               AND ($2::timestamptz IS NULL \
                    OR (n.created_at, n.node_id) < ($2, $3::uuid)) \
             GROUP BY n.node_id, n.graph_id, n.title, n.body, n.created_at \
             ORDER BY n.created_at DESC, n.node_id DESC \
             LIMIT $4",
        )
        .bind(account_id)
        .bind(cursor_at)
        .bind(cursor_id)
        .bind(limit)
        .bind(readable_graph_ids)
        .fetch_all(&self.pool)
        .await?;

        Ok(rows
            .into_iter()
            .map(
                |(node_id, graph_id, title, body, created_at, source_atom_ids)| {
                    decision_candidate_from_body(
                        node_id,
                        graph_id,
                        title,
                        &body,
                        created_at,
                        source_atom_ids,
                    )
                },
            )
            .collect())
    }

    async fn count_pending_decision_candidates(
        &self,
        account_id: Uuid,
        readable_graph_ids: &[Uuid],
    ) -> Result<i64, StoreError> {
        let n: i64 = sqlx::query_scalar(
            "SELECT COUNT(*) \
             FROM nodes n \
             JOIN graphs g ON g.id = n.graph_id \
             WHERE g.account_id = $1 \
               AND n.graph_id = ANY($2::uuid[]) \
               AND n.type = 'decision' \
               AND n.body->>'review_status' = 'pending'",
        )
        .bind(account_id)
        .bind(readable_graph_ids)
        .fetch_one(&self.pool)
        .await?;
        Ok(n)
    }

    async fn set_node_review_status(
        &self,
        node_id: Uuid,
        account_id: Uuid,
        body_merge_json: &str,
        title: Option<&str>,
    ) -> Result<bool, StoreError> {
        type UpdatedRow = (
            Uuid,          // node_id
            Uuid,          // graph_id
            String,        // type
            String,        // title
            Value,         // body
            String,        // scope
            Option<Uuid>,  // owner_id
            DateTime<Utc>, // created_at
            DateTime<Utc>, // updated_at
            i32,           // version
        );

        let mut tx = self.pool.begin().await?;

        // The IDOR check (graph → account), the pending-decision guard, and the
        // mutation are one statement: a non-pending / wrong-account / non-decision
        // node simply matches no row → Ok(false) at the route layer.
        // `body || $3::jsonb` shallow-merges the verdict (+ any edited fields /
        // reject_reason); COALESCE keeps the title unless an edit overrides it.
        let row: Option<UpdatedRow> = sqlx::query_as(
            "UPDATE nodes n \
             SET body       = n.body || $3::jsonb, \
                 title      = COALESCE($4, n.title), \
                 updated_at = now(), \
                 version    = n.version + 1 \
             FROM graphs g \
             WHERE n.node_id = $1 \
               AND g.id = n.graph_id \
               AND g.account_id = $2 \
               AND n.type = 'decision' \
               AND n.body->>'review_status' = 'pending' \
             RETURNING n.node_id, n.graph_id, n.type, n.title, n.body, n.scope, \
                       n.owner_id, n.created_at, n.updated_at, n.version",
        )
        .bind(node_id)
        .bind(account_id)
        .bind(body_merge_json)
        .bind(title)
        .fetch_optional(&mut *tx)
        .await?;

        let Some((
            node_id,
            graph_id,
            ref node_type,
            ref title,
            ref body,
            ref scope,
            owner_id,
            created_at,
            updated_at,
            version,
        )) = row
        else {
            tx.commit().await?;
            return Ok(false);
        };

        let op = sync::node_upsert_op(
            Uuid::new_v4(),
            node_id,
            graph_id,
            node_type,
            title,
            &body.to_string(),
            scope,
            owner_id,
            created_at,
            updated_at,
            i64::from(version),
            self.device_id(),
        );
        append_op_tx(&mut tx, &op).await?;

        tx.commit().await?;
        Ok(true)
    }
    // ── RLS-scoped transaction surface: atoms/nodes/graphs cluster ─────────────
    // Real `PostgresStore` bodies for the `_scoped` trait methods declared
    // (with a default `Err` body) near the top of this file's `Store` trait —
    // see that block's doc comment for the full design rationale. Each method
    // here is byte-identical SQL to its unscoped twin above; only the
    // transaction source and lifecycle differ (caller-supplied `tx`, no local
    // `commit`/`rollback`).

    async fn list_graphs_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        account_id: Uuid,
    ) -> Result<Vec<Graph>, StoreError> {
        // Order: primary first, then by recency — so the UI lists the private
        // home ocean at the top regardless of when it was created (ADR-0006).
        // Same 9-column shape and same "no archived/member filter" rationale
        // as the unscoped `list_graphs` above — `my_team_role` is literal
        // `NULL::text`, same reasoning as that method (no caller `user_id`
        // here either).
        let rows: Vec<GraphRow> = sqlx::query_as(&format!(
            "SELECT g.id, g.name, g.kind, g.is_primary, g.created_at, g.owner_user_id, \
             g.archived_at, {TEAM_ID_SUBQUERY} AS team_id, NULL::text AS my_team_role \
             FROM graphs g \
             WHERE g.account_id = $1 \
             ORDER BY g.is_primary DESC, g.created_at DESC"
        ))
        .bind(account_id)
        .fetch_all(&mut **tx)
        .await?;

        Ok(rows.into_iter().map(graph_row_to_graph).collect())
    }

    async fn create_graph_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        account_id: Uuid,
        name: &str,
        kind: &str,
    ) -> Result<Graph, StoreError> {
        // A personal ocean becomes the account's primary when none exists yet —
        // the first personal ocean a user creates is their private home
        // (ADR-0006). Owner-aware sub-select — see the unscoped `create_graph`
        // above for the full rationale (byte-identical predicate, mirrors
        // `uq_graphs_one_primary_account_wide` exactly for the owner_user_id =
        // NULL row this INSERT always produces).
        let is_primary_sql = "$3 = 'personal' AND NOT EXISTS \
             (SELECT 1 FROM graphs \
              WHERE account_id = $1 AND owner_user_id IS NULL AND archived_at IS NULL AND is_primary)";

        // `team_id` always `NULL` here too — see the unscoped `create_graph`
        // above for why (same route-level `kind IN ('personal', 'org')`
        // restriction, same `create_team_tx` bypass of this method).
        // `my_team_role` is literal `NULL::text` for the same reason.
        let row: GraphRow = sqlx::query_as(&format!(
            "INSERT INTO graphs (account_id, name, kind, is_primary) \
             VALUES ($1, $2, $3, {is_primary_sql}) \
             RETURNING id, name, kind, is_primary, created_at, owner_user_id, archived_at, \
             NULL::uuid AS team_id, NULL::text AS my_team_role"
        ))
        .bind(account_id)
        .bind(name)
        .bind(kind)
        .fetch_one(&mut **tx)
        .await?;

        Ok(graph_row_to_graph(row))
    }

    async fn get_graph_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        graph_id: Uuid,
        account_id: Uuid,
    ) -> Result<Option<Graph>, StoreError> {
        // `my_team_role` is literal `NULL::text` — see the unscoped
        // `get_graph` above (no caller `user_id` on this path either).
        let row: Option<GraphRow> = sqlx::query_as(&format!(
            "SELECT g.id, g.name, g.kind, g.is_primary, g.created_at, g.owner_user_id, \
             g.archived_at, {TEAM_ID_SUBQUERY} AS team_id, NULL::text AS my_team_role \
             FROM graphs g \
             WHERE g.id = $1 AND g.account_id = $2"
        ))
        .bind(graph_id)
        .bind(account_id)
        .fetch_optional(&mut **tx)
        .await?;

        Ok(row.map(graph_row_to_graph))
    }

    async fn graph_exists_for_account_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        graph_id: Uuid,
        account_id: Uuid,
    ) -> Result<bool, StoreError> {
        let owned: Option<bool> =
            sqlx::query_scalar("SELECT true FROM graphs WHERE id = $1 AND account_id = $2")
                .bind(graph_id)
                .bind(account_id)
                .fetch_optional(&mut **tx)
                .await?;

        Ok(owned.is_some())
    }

    async fn list_atoms_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        graph_id: Uuid,
    ) -> Result<Vec<Atom>, StoreError> {
        page_sources::list_atoms_scoped(tx, graph_id).await
    }

    async fn list_atoms_page_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        graph_id: Uuid,
        page_size: i64,
        offset: i64,
    ) -> Result<Vec<Atom>, StoreError> {
        let rows: Vec<(
            Uuid,
            String,
            String,
            DateTime<Utc>,
            DateTime<Utc>,
            Option<String>,
            Option<String>,
            Option<String>,
        )> = sqlx::query_as(
            "SELECT atom_id, source_type, source_id, timestamp, created_at, channel_id, channel_name, author_name \
             FROM (SELECT * FROM atoms WHERE library_atom_permitted(graph_id,atom_id)) atoms \
             WHERE graph_id = $1 \
             ORDER BY created_at DESC \
             LIMIT $2 OFFSET $3",
        )
        .bind(graph_id)
        .bind(page_size)
        .bind(offset)
        .fetch_all(&mut **tx)
        .await?;

        Ok(rows
            .into_iter()
            .map(
                |(
                    atom_id,
                    source_type,
                    source_id,
                    timestamp,
                    created_at,
                    channel_id,
                    channel_name,
                    author_name,
                )| {
                    Atom {
                        atom_id,
                        source_type,
                        source_id,
                        timestamp,
                        created_at,
                        channel_id,
                        channel_name,
                        author_name,
                    }
                },
            )
            .collect())
    }

    // Byte-identical SQL to `source_groups`'s unscoped twin — the only
    // difference is that this executes inside the caller's
    // `begin_member_scoped` transaction, so the `member_ocean_isolation` RLS
    // policy on `atoms`/`node_atoms` has the GUC it reads. See that method
    // for the shape rationale.
    async fn source_groups_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        graph_id: Uuid,
    ) -> Result<Vec<SourceGroupSummary>, StoreError> {
        let sql = format!(
            r#"
            WITH atom_groups AS (
                SELECT
                    atom_id,
                    split_part(source_id, ':chunk:', 1) AS base_source_id,
                    {key} AS channel_key,
                    channel_name,
                    source_type,
                    timestamp
                FROM (SELECT * FROM atoms WHERE library_atom_permitted(graph_id,atom_id)) atoms
                WHERE graph_id = $1
            ),
            group_stats AS (
                SELECT
                    channel_key,
                    (array_agg('#' || channel_name)
                        FILTER (WHERE channel_name IS NOT NULL AND channel_name <> ''))[1] AS channel_label,
                    MODE() WITHIN GROUP (ORDER BY source_type) AS source_type,
                    COUNT(*) AS coral_count,
                    COUNT(DISTINCT base_source_id) AS instance_count,
                    MIN(timestamp) AS first_ts,
                    MAX(timestamp) AS last_ts
                FROM atom_groups
                GROUP BY channel_key
            ),
            reef_counts AS (
                SELECT ag.channel_key, COUNT(DISTINCT na.node_id) AS reef_count
                FROM atom_groups ag
                JOIN node_atoms na ON na.atom_id = ag.atom_id
                GROUP BY ag.channel_key
            )
            SELECT gs.channel_key, gs.channel_label, gs.source_type, gs.coral_count,
                   gs.instance_count, COALESCE(rc.reef_count, 0) AS reef_count,
                   gs.first_ts, gs.last_ts
            FROM group_stats gs
            LEFT JOIN reef_counts rc ON rc.channel_key = gs.channel_key
            ORDER BY gs.last_ts DESC NULLS LAST
            "#,
            key = CHANNEL_KEY_SQL,
        );
        let rows: Vec<(
            String,
            Option<String>,
            String,
            i64,
            i64,
            i64,
            Option<DateTime<Utc>>,
            Option<DateTime<Utc>>,
        )> = sqlx::query_as(&sql).bind(graph_id).fetch_all(&mut **tx).await?;

        Ok(rows
            .into_iter()
            .map(
                |(
                    channel_key,
                    channel_label,
                    source_type,
                    coral_count,
                    instance_count,
                    reef_count,
                    first_ts,
                    last_ts,
                )| SourceGroupSummary {
                    channel_key,
                    channel_label,
                    source_type,
                    coral_count,
                    instance_count,
                    reef_count,
                    first_ts,
                    last_ts,
                },
            )
            .collect())
    }

    // Byte-identical SQL to `source_group_detail_meta`'s unscoped twin, same
    // reasoning as `source_groups_scoped` above.
    async fn source_group_detail_meta_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        graph_id: Uuid,
        channel_key: &str,
    ) -> Result<Option<SourceGroupDetailMeta>, StoreError> {
        let summary_sql = format!(
            r#"
            WITH atom_group AS (
                SELECT
                    atom_id,
                    split_part(source_id, ':chunk:', 1) AS base_source_id,
                    channel_name,
                    source_type,
                    timestamp
                FROM (SELECT * FROM atoms WHERE library_atom_permitted(graph_id,atom_id)) atoms
                WHERE graph_id = $1 AND {key} = $2
            )
            SELECT
                (array_agg('#' || channel_name)
                    FILTER (WHERE channel_name IS NOT NULL AND channel_name <> ''))[1] AS channel_label,
                MODE() WITHIN GROUP (ORDER BY source_type) AS source_type,
                COUNT(*) AS coral_count,
                COUNT(DISTINCT base_source_id) AS instance_count,
                MIN(timestamp) AS first_ts,
                MAX(timestamp) AS last_ts
            FROM atom_group
            "#,
            key = CHANNEL_KEY_SQL,
        );
        let (channel_label, source_type, coral_count, instance_count, first_ts, last_ts): (
            Option<String>,
            Option<String>,
            i64,
            i64,
            Option<DateTime<Utc>>,
            Option<DateTime<Utc>>,
        ) = sqlx::query_as(&summary_sql)
            .bind(graph_id)
            .bind(channel_key)
            .fetch_one(&mut **tx)
            .await?;

        if coral_count == 0 {
            return Ok(None);
        }

        let reefs_sql = format!(
            r#"
            WITH grp_atoms AS (
                SELECT atom_id FROM (SELECT * FROM atoms WHERE library_atom_permitted(graph_id,atom_id)) atoms WHERE graph_id = $1 AND {key} = $2
            )
            SELECT DISTINCT n.node_id, n.type, COALESCE(library_node_title(n.graph_id,n.node_id),'')
            FROM grp_atoms ga
            JOIN node_atoms na ON na.atom_id = ga.atom_id
            JOIN nodes n ON n.node_id = na.node_id
            ORDER BY n.node_id
            "#,
            key = CHANNEL_KEY_SQL,
        );
        let reef_rows: Vec<(Uuid, String, String)> = sqlx::query_as(&reefs_sql)
            .bind(graph_id)
            .bind(channel_key)
            .fetch_all(&mut **tx)
            .await?;
        let reef_count = reef_rows.len() as i64;
        let reefs = reef_rows
            .into_iter()
            .map(|(node_id, node_type, title)| SourceGroupReef {
                node_id,
                node_type,
                title,
            })
            .collect();

        let ids_sql = format!(
            r#"
            SELECT source_id, MAX(created_at) AS newest
            FROM (SELECT * FROM atoms WHERE library_atom_permitted(graph_id,atom_id)) atoms
            WHERE graph_id = $1 AND {key} = $2
            GROUP BY source_id
            ORDER BY newest DESC
            "#,
            key = CHANNEL_KEY_SQL,
        );
        let id_rows: Vec<(String, DateTime<Utc>)> = sqlx::query_as(&ids_sql)
            .bind(graph_id)
            .bind(channel_key)
            .fetch_all(&mut **tx)
            .await?;
        let source_ids = id_rows.into_iter().map(|(id, _)| id).collect();

        Ok(Some(SourceGroupDetailMeta {
            summary: SourceGroupSummary {
                channel_key: channel_key.to_string(),
                channel_label,
                source_type: source_type.unwrap_or_default(),
                coral_count,
                instance_count,
                reef_count,
                first_ts,
                last_ts,
            },
            source_ids,
            reefs,
        }))
    }

    // Byte-identical SQL to `list_atoms_page_for_channel`'s unscoped twin,
    // same reasoning as `source_groups_scoped` above.
    async fn list_atoms_page_for_channel_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        graph_id: Uuid,
        channel_key: &str,
        page_size: i64,
        offset: i64,
    ) -> Result<Vec<Atom>, StoreError> {
        let sql = format!(
            "SELECT atom_id, source_type, source_id, timestamp, created_at, channel_id, channel_name, author_name \
             FROM (SELECT * FROM atoms WHERE library_atom_permitted(graph_id,atom_id)) atoms \
             WHERE graph_id = $1 AND {key} = $2 \
             ORDER BY created_at DESC, atom_id DESC \
             LIMIT $3 OFFSET $4",
            key = CHANNEL_KEY_SQL,
        );
        let rows: Vec<(
            Uuid,
            String,
            String,
            DateTime<Utc>,
            DateTime<Utc>,
            Option<String>,
            Option<String>,
            Option<String>,
        )> = sqlx::query_as(&sql)
            .bind(graph_id)
            .bind(channel_key)
            .bind(page_size)
            .bind(offset)
            .fetch_all(&mut **tx)
            .await?;

        Ok(rows
            .into_iter()
            .map(
                |(
                    atom_id,
                    source_type,
                    source_id,
                    timestamp,
                    created_at,
                    channel_id,
                    channel_name,
                    author_name,
                )| Atom {
                    atom_id,
                    source_type,
                    source_id,
                    timestamp,
                    created_at,
                    channel_id,
                    channel_name,
                    author_name,
                },
            )
            .collect())
    }

    async fn insert_atoms_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        atom_ids: &[Uuid],
        graph_id: Uuid,
        source_type: &str,
        source_ids: &[String],
        blob_keys: &[String],
        participants: &[String],
        timestamp: DateTime<Utc>,
        ingested_by: Uuid,
        scope: &str,
        fts_language: &str,
        excerpts: &[Option<String>],
        titles: &[Option<String>],
        title_kinds: &[Option<String>],
        symbols: &[Option<String>],
        content_hash: Option<&str>,
    ) -> Result<Vec<Uuid>, StoreError> {
        // Build a lookup from atom_id → positional index so we can recover the
        // per-atom source_id / blob_key for each actually-inserted row.
        let id_to_idx: std::collections::HashMap<Uuid, usize> = atom_ids
            .iter()
            .enumerate()
            .map(|(i, &id)| (id, i))
            .collect();

        let now = Utc::now();

        // `excerpt` (gap 9 / migration 0116_atoms_excerpt) is written HERE,
        // in the same INSERT as every other atom, from the caller's
        // pre-derived `excerpts` array — not conditioned on whether the
        // caller stores the full text inline or in R2. That is what makes
        // the journal's excerpt independent of the R2 on/off toggle.
        //
        // `title`/`title_kind` (title-always-present PR) follow the exact
        // same shape: `routes::ingest` pre-derives a deterministic fallback
        // title synchronously, so a coral is never left titleless waiting on
        // the async sweep. `title_kind = 'fallback'` wherever a title is
        // written is what lets `workers::atom_title_backfill` find these rows
        // later and try to upgrade them to a real LLM headline.
        //
        // `symbols` (retrieval fix, migration `0247`/`0100`) is the SAME
        // shape again: `routes::ingest` pre-derives it from
        // `Chunk::symbols`, so it lands in this one INSERT alongside every
        // other write-time-derived column rather than a later backfill pass.
        //
        // `content_hash` (migration `0271`/`0112`) is one scalar for the
        // whole request — every chunk of one ingest gets the same value —
        // so it binds like `participants`/`timestamp`, not as an unnest.
        let rows: Vec<(Uuid,)> = sqlx::query_as(
            r#"
            INSERT INTO atoms
                (atom_id, graph_id, source_type, source_id, content_blob_key,
                 participants, timestamp, ingested_by, scope, fts_language, created_at,
                 excerpt, title, title_kind, symbols, content_hash)
            SELECT unnest($1::uuid[]), $2, $3, unnest($4::text[]), unnest($5::text[]),
                   $6, $7, $8, $9, $10, now(),
                   unnest($11::text[]), unnest($12::text[]), unnest($13::text[]), unnest($14::text[]),
                   $15
            ON CONFLICT (graph_id, source_type, source_id) DO NOTHING
            RETURNING atom_id
            "#,
        )
        .bind(atom_ids)
        .bind(graph_id)
        .bind(source_type)
        .bind(source_ids)
        .bind(blob_keys)
        .bind(participants)
        .bind(timestamp)
        .bind(ingested_by)
        .bind(scope)
        .bind(fts_language)
        .bind(excerpts)
        .bind(titles)
        .bind(title_kinds)
        .bind(symbols)
        .bind(content_hash)
        .fetch_all(&mut **tx)
        .await?;

        let inserted: Vec<Uuid> = rows.into_iter().map(|(id,)| id).collect();

        // Append one create-op per actually-inserted atom (skips DO NOTHING rows).
        for &atom_id in &inserted {
            if let Some(&idx) = id_to_idx.get(&atom_id) {
                let op = sync::atom_create_op(
                    Uuid::new_v4(),
                    atom_id,
                    graph_id,
                    source_type,
                    &source_ids[idx],
                    &blob_keys[idx],
                    participants,
                    timestamp,
                    Some(ingested_by),
                    scope,
                    fts_language,
                    now,
                    self.device_id(),
                );
                append_op_tx(&mut *tx, &op).await?;
            }
        }

        Ok(inserted)
    }

    async fn delete_atoms_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        atom_ids: &[Uuid],
    ) -> Result<(), StoreError> {
        // Returning the full row snapshot so we can record a tombstone op.
        type DeletedRow = (
            Uuid,           // atom_id
            Uuid,           // graph_id
            String,         // source_type
            String,         // source_id
            String,         // content_blob_key
            Option<String>, // content_inline
            Vec<String>,    // participants
            DateTime<Utc>,  // timestamp
            Option<Uuid>,   // ingested_by
            String,         // scope
            String,         // fts_language
            DateTime<Utc>,  // created_at
        );

        let deleted: Vec<DeletedRow> = sqlx::query_as(
            r#"
            DELETE FROM atoms
            WHERE atom_id = ANY($1)
            RETURNING
                atom_id, graph_id, source_type, source_id, content_blob_key,
                content_inline, participants, timestamp, ingested_by, scope,
                fts_language, created_at
            "#,
        )
        .bind(atom_ids)
        .fetch_all(&mut **tx)
        .await?;

        let now = Utc::now();

        for (
            atom_id,
            graph_id,
            source_type,
            source_id,
            content_blob_key,
            content_inline,
            participants,
            atom_timestamp,
            ingested_by,
            scope,
            fts_language,
            created_at,
        ) in deleted
        {
            use serde_json::json;
            use sync::field;
            // Build a last-known snapshot payload for the tombstone.
            let snapshot = json!({
                field::ATOM_ID:           atom_id.to_string(),
                field::GRAPH_ID:          graph_id.to_string(),
                field::SOURCE_TYPE:       source_type,
                field::SOURCE_ID:         source_id,
                field::CONTENT_BLOB_KEY:  content_blob_key,
                field::CONTENT_INLINE:    content_inline,
                field::PARTICIPANTS:      participants,
                field::TIMESTAMP:         atom_timestamp.to_rfc3339(),
                field::INGESTED_BY:       ingested_by.map(|u| u.to_string()),
                field::SCOPE:             scope,
                field::FTS_LANGUAGE:      fts_language,
                field::CREATED_AT:        created_at.to_rfc3339(),
            });
            let op = sync::atom_delete_op(
                Uuid::new_v4(),
                snapshot,
                atom_id,
                graph_id,
                now,
                self.device_id(),
            );
            append_op_tx(&mut *tx, &op).await?;
        }

        Ok(())
    }

    async fn set_atoms_inline_content_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        atom_ids: &[Uuid],
        texts: &[String],
    ) -> Result<(), StoreError> {
        sqlx::query(
            r#"UPDATE atoms SET content_inline = v.text
               FROM (SELECT unnest($1::uuid[]) AS id, unnest($2::text[]) AS text) v
               WHERE atoms.atom_id = v.id"#,
        )
        .bind(atom_ids)
        .bind(texts)
        .execute(&mut **tx)
        .await?;

        let now = Utc::now();

        // For each updated atom, look up its graph_id and append a content op.
        for (atom_id, text) in atom_ids.iter().zip(texts.iter()) {
            let graph_id: Option<Uuid> =
                sqlx::query_scalar("SELECT graph_id FROM atoms WHERE atom_id = $1")
                    .bind(atom_id)
                    .fetch_optional(&mut **tx)
                    .await?;

            if let Some(gid) = graph_id {
                let op = sync::atom_content_op(
                    Uuid::new_v4(),
                    *atom_id,
                    gid,
                    text,
                    now,
                    self.device_id(),
                );
                append_op_tx(&mut *tx, &op).await?;
            }
        }

        Ok(())
    }

    async fn stamp_atom_provenance_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        atom_ids: &[Uuid],
        channel_id: Option<&str>,
        channel_name: Option<&str>,
        author_id: Option<&str>,
        author_name: Option<&str>,
        project: Option<&str>,
        mcp_client_name: Option<&str>,
    ) -> Result<(), StoreError> {
        if atom_ids.is_empty()
            || (channel_id.is_none()
                && channel_name.is_none()
                && author_id.is_none()
                && author_name.is_none()
                && project.is_none()
                && mcp_client_name.is_none())
        {
            return Ok(());
        }
        sqlx::query(
            r#"
            UPDATE atoms
            SET channel_id      = COALESCE($2, channel_id),
                channel_name    = COALESCE($3, channel_name),
                author_id       = COALESCE($4, author_id),
                author_name     = COALESCE($5, author_name),
                project         = COALESCE($6, project),
                mcp_client_name = COALESCE($7, mcp_client_name)
            WHERE atom_id = ANY($1)
            "#,
        )
        .bind(atom_ids)
        .bind(channel_id)
        .bind(channel_name)
        .bind(author_id)
        .bind(author_name)
        .bind(project)
        .bind(mcp_client_name)
        .execute(&mut **tx)
        .await?;
        Ok(())
    }

    async fn upsert_supersession_edge_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        superseder_id: Uuid,
        superseded_id: Uuid,
    ) -> Result<SupersessionEdge, StoreError> {
        // Single round-trip: `DO UPDATE` with a no-op `SET` (preserving the
        // existing row's `source`, matching the old `DO NOTHING` semantics) so
        // `RETURNING` fires whether the row was just inserted or already existed.
        // The conflict target is the table's pkey `(superseded_id, superseder_id)`.
        // NOTE: `supersession_edge` has no creation-timestamp column, so
        // `created_at` is the server clock at upsert time, not a stored value.

        // This is the MANUAL route (`POST /supersede`, source='user'): a human
        // is directly asserting the supersession. T4 (2026-08-08): unlike the
        // `_with_kind_scoped` sibling's `source='auto'` edges — which
        // unconditionally flip a superseded `confirmed` decision back to
        // `pending` review — this path never re-queues. The human already
        // decided; the review queue exists to surface machine-detected
        // contradictions a human HASN'T seen yet, not to second-guess one they
        // just acted on. `(xmax = 0)` still distinguishes a fresh INSERT from a
        // conflict DO-UPDATE in the RETURNING clause below, but is otherwise
        // unused now.
        let (sid, ssid, created_at, _edge_inserted): (Uuid, Uuid, DateTime<Utc>, bool) =
            sqlx::query_as(
                r#"
            INSERT INTO supersession_edge (superseder_id, superseded_id, source, graph_id)
            VALUES ($1, $2, 'user', (SELECT graph_id FROM nodes WHERE node_id = $2))
            ON CONFLICT (superseded_id, superseder_id)
            DO UPDATE SET source = supersession_edge.source
            RETURNING superseder_id, superseded_id, now() AS created_at, (xmax = 0) AS inserted
            "#,
            )
            .bind(superseder_id)
            .bind(superseded_id)
            .fetch_one(&mut **tx)
            .await?;

        // Look up graph_id from the superseder node so the op is graph-scoped.
        let graph_id: Option<Uuid> =
            sqlx::query_scalar("SELECT graph_id FROM nodes WHERE node_id = $1")
                .bind(superseder_id)
                .fetch_optional(&mut **tx)
                .await?;

        if let Some(gid) = graph_id {
            let op = sync::supersession_op(
                Uuid::new_v4(),
                superseder_id,
                superseded_id,
                gid,
                "user",
                OpType::Upsert,
                created_at,
                self.device_id(),
            );
            append_op_tx(&mut *tx, &op).await?;
        }

        Ok(SupersessionEdge {
            superseder_id: sid,
            superseded_id: ssid,
            created_at,
        })
    }

    async fn upsert_supersession_edge_with_kind_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        superseder_id: Uuid,
        superseded_id: Uuid,
        kind: SupersessionKind,
    ) -> Result<SupersessionEdge, StoreError> {
        // Scoped twin of `upsert_supersession_edge_with_kind` (unscoped) —
        // see that method's inline comments and this trait method's doc
        // comment for the `kind`-preserved-on-conflict rationale.
        let (sid, ssid, created_at, edge_inserted): (Uuid, Uuid, DateTime<Utc>, bool) =
            sqlx::query_as(
                r#"
            INSERT INTO supersession_edge (superseder_id, superseded_id, source, graph_id, kind)
            VALUES ($1, $2, 'auto', (SELECT graph_id FROM nodes WHERE node_id = $2), $3)
            ON CONFLICT (superseded_id, superseder_id)
            DO UPDATE SET source = supersession_edge.source
            RETURNING superseder_id, superseded_id, now() AS created_at, (xmax = 0) AS inserted
            "#,
            )
            .bind(superseder_id)
            .bind(superseded_id)
            .bind(kind.as_str())
            .fetch_one(&mut **tx)
            .await?;

        // Conflict-triggered review (CS-069): a freshly-inserted `source='auto'`
        // edge against a `type = 'decision'` reef flips it `confirmed →
        // pending` UNCONDITIONALLY (T4, 2026-08-08) — see
        // `upsert_supersession_edge_with_kind` (unscoped twin) for the full
        // rationale on why the old coral_count/degree gate was removed here
        // and why the `source='user'` sibling (`upsert_supersession_edge_
        // scoped`) never flips at all.
        type FlippedRow = (
            Uuid,          // graph_id
            String,        // type
            String,        // title
            Value,         // body
            String,        // scope
            Option<Uuid>,  // owner_id
            DateTime<Utc>, // created_at
            DateTime<Utc>, // updated_at
            i32,           // version
        );
        let flipped: Option<FlippedRow> = if edge_inserted {
            sqlx::query_as(
                r#"
            UPDATE nodes
               SET body       = jsonb_set(
                                    jsonb_set(body, '{review_status}', '"pending"'),
                                    '{pending_since}', to_jsonb(now())),
                   updated_at = now(),
                   version    = version + 1
             WHERE node_id = $1
               AND type = 'decision'
               AND body->>'review_status' = 'confirmed'
            RETURNING graph_id, type, title, body, scope, owner_id,
                      created_at, updated_at, version
            "#,
            )
            .bind(superseded_id)
            .fetch_optional(&mut **tx)
            .await?
        } else {
            None
        };

        if let Some((
            f_graph_id,
            ref f_type,
            ref f_title,
            ref f_body,
            ref f_scope,
            f_owner_id,
            f_created_at,
            f_updated_at,
            f_version,
        )) = flipped
        {
            let op = sync::node_upsert_op(
                Uuid::new_v4(),
                superseded_id,
                f_graph_id,
                f_type,
                f_title,
                &f_body.to_string(),
                f_scope,
                f_owner_id,
                f_created_at,
                f_updated_at,
                i64::from(f_version),
                self.device_id(),
            );
            append_op_tx(&mut *tx, &op).await?;
        }

        let graph_id: Option<Uuid> =
            sqlx::query_scalar("SELECT graph_id FROM nodes WHERE node_id = $1")
                .bind(superseder_id)
                .fetch_optional(&mut **tx)
                .await?;

        if let Some(gid) = graph_id {
            let op = sync::supersession_op(
                Uuid::new_v4(),
                superseder_id,
                superseded_id,
                gid,
                "auto",
                OpType::Upsert,
                created_at,
                self.device_id(),
            );
            append_op_tx(&mut *tx, &op).await?;
        }

        Ok(SupersessionEdge {
            superseder_id: sid,
            superseded_id: ssid,
            created_at,
        })
    }

    async fn delete_supersession_edge_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        node_a: Uuid,
        node_b: Uuid,
    ) -> Result<u64, StoreError> {
        type DeletedEdge = (Uuid, Uuid, String); // superseder_id, superseded_id, source

        let deleted: Vec<DeletedEdge> = sqlx::query_as(
            r#"
            DELETE FROM supersession_edge
            WHERE (superseder_id = $1 AND superseded_id = $2)
               OR (superseder_id = $2 AND superseded_id = $1)
            RETURNING superseder_id, superseded_id, source
            "#,
        )
        .bind(node_a)
        .bind(node_b)
        .fetch_all(&mut **tx)
        .await?;

        let count = deleted.len() as u64;
        let now = Utc::now();

        for (superseder_id, superseded_id, source) in deleted {
            // Look up graph_id; skip the op if the superseder node is already gone.
            let graph_id: Option<Uuid> =
                sqlx::query_scalar("SELECT graph_id FROM nodes WHERE node_id = $1")
                    .bind(superseder_id)
                    .fetch_optional(&mut **tx)
                    .await?;

            if let Some(gid) = graph_id {
                let op = sync::supersession_op(
                    Uuid::new_v4(),
                    superseder_id,
                    superseded_id,
                    gid,
                    &source,
                    OpType::Delete,
                    now,
                    self.device_id(),
                );
                append_op_tx(&mut *tx, &op).await?;
            }
        }

        Ok(count)
    }

    async fn graph_node_atoms_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        graph_id: Uuid,
        limit: i64,
        offset: i64,
    ) -> Result<Vec<GraphNodeAtom>, StoreError> {
        type EdgeRow = (Uuid, Uuid, String, Option<DateTime<Utc>>);
        let rows: Vec<EdgeRow> = sqlx::query_as(
            // Identical SQL to the unscoped sibling — the difference is the
            // transaction, which carries the RLS account scope. Keeping the
            // statements byte-identical is deliberate: a divergence between a
            // scoped and unscoped pair is exactly how a "we fixed it in the
            // scoped path" bug survives.
            "SELECT na.node_id, na.atom_id, a.source_type, a.timestamp \
             FROM   node_atoms na \
             JOIN   nodes n ON n.node_id = na.node_id \
             JOIN   (SELECT * FROM atoms WHERE library_atom_permitted(graph_id,atom_id)) a ON a.atom_id = na.atom_id \
             WHERE  n.graph_id = $1 \
             ORDER BY na.node_id, na.atom_id \
             LIMIT $2 OFFSET $3",
        )
        .bind(graph_id)
        .bind(limit)
        .bind(offset)
        .fetch_all(&mut **tx)
        .await?;

        Ok(rows
            .into_iter()
            .map(|(node_id, atom_id, source_type, timestamp)| GraphNodeAtom {
                node_id,
                atom_id,
                source_type,
                timestamp,
            })
            .collect())
    }

    async fn graph_node_atom_facets_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        graph_id: Uuid,
    ) -> Result<GraphEdgeFacets, StoreError> {
        // Joins `atoms` even though it needs no column from it, so that
        // `total_edges` counts the SAME population as `by_source_type` below.
        // Without it an edge whose atom row is absent is counted in the total
        // but in no source-type bucket — and the client compares its drained
        // count against this total to decide whether the view is partial, so a
        // mismatch there makes the partiality flag itself wrong.
        //
        // `by_week` is necessarily a SUBSET of both (it excludes NULL
        // timestamps) and is not expected to reconcile.
        let total: i64 = sqlx::query_scalar(
            "SELECT count(*) FROM node_atoms na \
             JOIN nodes n ON n.node_id = na.node_id \
             JOIN (SELECT * FROM atoms WHERE library_atom_permitted(graph_id,atom_id)) a ON a.atom_id = na.atom_id \
             WHERE n.graph_id = $1",
        )
        .bind(graph_id)
        .fetch_one(&mut **tx)
        .await?;

        let by_source_type: Vec<(String, i64)> = sqlx::query_as(
            "SELECT a.source_type, count(*) FROM node_atoms na \
             JOIN nodes n ON n.node_id = na.node_id \
             JOIN (SELECT * FROM atoms WHERE library_atom_permitted(graph_id,atom_id)) a ON a.atom_id = na.atom_id \
             WHERE n.graph_id = $1 GROUP BY a.source_type ORDER BY count(*) DESC",
        )
        .bind(graph_id)
        .fetch_all(&mut **tx)
        .await?;

        let by_week: Vec<(DateTime<Utc>, i64)> = sqlx::query_as(
            "SELECT date_trunc('week', a.timestamp) AS wk, count(*) FROM node_atoms na \
             JOIN nodes n ON n.node_id = na.node_id \
             JOIN (SELECT * FROM atoms WHERE library_atom_permitted(graph_id,atom_id)) a ON a.atom_id = na.atom_id \
             WHERE n.graph_id = $1 AND a.timestamp IS NOT NULL \
             GROUP BY wk ORDER BY wk",
        )
        .bind(graph_id)
        .fetch_all(&mut **tx)
        .await?;

        Ok(GraphEdgeFacets {
            total_edges: total,
            by_source_type,
            by_week,
        })
    }

    async fn list_nodes_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        graph_id: Uuid,
        node_type: Option<&str>,
        page_size: i64,
        offset: i64,
    ) -> Result<Vec<Node>, StoreError> {
        page_sources::list_nodes_scoped(tx, graph_id, node_type, page_size, offset).await
    }

    async fn nodes_by_ids_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        graph_id: Uuid,
        node_ids: &[Uuid],
    ) -> Result<Vec<(Uuid, String)>, StoreError> {
        if node_ids.is_empty() {
            return Ok(Vec::new());
        }
        let rows: Vec<(Uuid, String)> = sqlx::query_as(verdict::NODE_TITLES_SQL)
        .bind(graph_id)
        .bind(node_ids)
        .fetch_all(&mut **tx)
        .await?;
        Ok(rows)
    }

    async fn nodes_by_ids_with_counts_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        graph_id: Uuid,
        node_ids: &[Uuid],
    ) -> Result<Vec<(Uuid, String, i64)>, StoreError> {
        nodes_by_ids_with_counts_via(&mut **tx, graph_id, node_ids).await
    }

