    async fn list_entity_nodes_after_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        graph_id: Uuid,
        after: Option<(DateTime<Utc>, Uuid)>,
        limit: i64,
    ) -> Result<Vec<Node>, StoreError> {
        type NodeRow = (Uuid, String, String, String, DateTime<Utc>, DateTime<Utc>, i64);
        let (after_updated_at, after_node_id) = match after {
            Some((u, n)) => (Some(u), Some(n)),
            None => (None, None),
        };
        let rows: Vec<NodeRow> = sqlx::query_as(
            "SELECT n.node_id, n.type, n.title, n.scope, n.created_at, n.updated_at, \
                    n.coral_count::bigint AS atom_count \
             FROM nodes n \
             WHERE n.graph_id = $1 \
               AND n.type = 'entity' \
               AND ( $2::timestamptz IS NULL \
                     OR (n.updated_at, n.node_id) > ($2::timestamptz, $3::uuid) ) \
             ORDER BY n.updated_at ASC, n.node_id ASC \
             LIMIT $4",
        )
        .bind(graph_id)
        .bind(after_updated_at)
        .bind(after_node_id)
        .bind(limit)
        .fetch_all(&mut **tx)
        .await?;
        Ok(rows
            .into_iter()
            .map(
                |(node_id, node_type, title, scope, created_at, updated_at, atom_count)| Node {
                    node_id,
                    node_type,
                    title,
                    scope,
                    created_at,
                    updated_at,
                    atom_count,
                },
            )
            .collect())
    }

    async fn get_er_sweep_cursor_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        graph_id: Uuid,
    ) -> Result<Option<(DateTime<Utc>, Uuid)>, StoreError> {
        let row: Option<(Option<DateTime<Utc>>, Option<Uuid>)> = sqlx::query_as(
            "SELECT er_sweep_cursor_updated_at, er_sweep_cursor_node_id FROM graphs WHERE id = $1",
        )
        .bind(graph_id)
        .fetch_optional(&mut **tx)
        .await?;
        Ok(row.and_then(|(u, n)| match (u, n) {
            (Some(u), Some(n)) => Some((u, n)),
            _ => None,
        }))
    }

    async fn set_er_sweep_cursor_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        graph_id: Uuid,
        expected: Option<(DateTime<Utc>, Uuid)>,
        cursor: Option<(DateTime<Utc>, Uuid)>,
    ) -> Result<bool, StoreError> {
        let (updated_at, node_id) = match cursor {
            Some((u, n)) => (Some(u), Some(n)),
            None => (None, None),
        };
        let (expected_updated_at, expected_node_id) = match expected {
            Some((u, n)) => (Some(u), Some(n)),
            None => (None, None),
        };
        // Same CAS guard as `PostgresStore::set_er_sweep_cursor` — see its
        // doc comment.
        let result = sqlx::query(
            "UPDATE graphs SET er_sweep_cursor_updated_at = $2, er_sweep_cursor_node_id = $3 \
             WHERE id = $1 \
               AND er_sweep_cursor_updated_at IS NOT DISTINCT FROM $4 \
               AND er_sweep_cursor_node_id IS NOT DISTINCT FROM $5",
        )
        .bind(graph_id)
        .bind(updated_at)
        .bind(node_id)
        .bind(expected_updated_at)
        .bind(expected_node_id)
        .execute(&mut **tx)
        .await?;
        Ok(result.rows_affected() > 0)
    }

