    async fn patch_node_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        node_id: Uuid,
        title: Option<&str>,
        node_type: Option<&str>,
        expected_version: Option<i64>,
    ) -> Result<Option<Node>, StoreError> {
        // Extended row: pulls the extra columns needed for the op payload.
        // `nodes.version` is INTEGER (INT4) → decoded as i32; cast to i64 for the op.
        // `atom_count` reads `nodes.coral_count` (§2.2), cast to BIGINT (INT8) → i64
        // to match this tuple's decode type.
        type UpdatedRow = (
            Uuid,          // node_id
            String,        // type
            String,        // title
            String,        // scope
            DateTime<Utc>, // created_at
            DateTime<Utc>, // updated_at
            i64,           // atom_count (COUNT returns BIGINT)
            Uuid,          // graph_id
            Value,         // body (jsonb)
            Option<Uuid>,  // owner_id
            i32,           // version (INTEGER / INT4)
        );

        // Optimistic-concurrency guard (checked+fixed items #6): lock the row
        // and compare its current version BEFORE the UPDATE below, inside the
        // same transaction, so there's no TOCTOU window between the check and
        // the write. `None` (the caller didn't ask for the guard) skips this
        // entirely — unchanged, last-writer-wins behavior.
        if let Some(expected) = expected_version {
            let current: Option<i32> = sqlx::query_scalar(
                "SELECT version FROM nodes WHERE node_id = $1 FOR UPDATE",
            )
            .bind(node_id)
            .fetch_optional(&mut **tx)
            .await?;
            match current {
                None => return Ok(None), // no such node — same as the unguarded path
                Some(v) if i64::from(v) != expected => {
                    return Err(StoreError::Conflict(version_conflict_msg(expected, v.into())));
                }
                Some(_) => {} // matches; fall through to the UPDATE below
            }
        }

        let row: Option<UpdatedRow> = match sqlx::query_as(
            "UPDATE nodes \
             SET title      = COALESCE($2, title), \
                 type       = COALESCE($3, type), \
                 updated_at = now(), \
                 version    = version + 1 \
             WHERE node_id = $1 \
             RETURNING \
                 node_id, type, title, scope, created_at, updated_at, \
                 coral_count::bigint AS atom_count, \
                 graph_id, body, owner_id, version",
        )
        .bind(node_id)
        .bind(title)
        .bind(node_type)
        .fetch_optional(&mut **tx)
        .await
        {
            Ok(r) => r,
            // `nodes_graph_type_title_unique` (migration 0017): a title/type
            // edit that collides with another reef in the same ocean. Caller-
            // fixable, so surface it distinctly rather than as an opaque
            // internal error (checked+fixed items #3).
            Err(e)
                if e.as_database_error()
                    .and_then(|d| d.code())
                    .map(|c| c == "23505")
                    .unwrap_or(false) =>
            {
                return Err(StoreError::Conflict(title_type_conflict_msg()));
            }
            Err(e) => return Err(e.into()),
        };

        if let Some((
            node_id,
            ref node_type,
            ref node_title,
            ref scope,
            created_at,
            updated_at,
            _atom_count,
            graph_id,
            ref body,
            owner_id,
            version,
        )) = row
        {
            let op = sync::node_upsert_op(
                Uuid::new_v4(),
                node_id,
                graph_id,
                node_type,
                node_title,
                &body.to_string(), // jsonb → text (body is a JSON string in the payload)
                scope,
                owner_id,
                created_at,
                updated_at,
                i64::from(version), // INT4 → i64 for the op payload
                self.device_id(),
            );
            append_op_tx(&mut *tx, &op).await?;
        }

        Ok(row.map(
            |(node_id, node_type, title, scope, created_at, updated_at, atom_count, ..)| Node {
                node_id,
                node_type,
                title,
                scope,
                created_at,
                updated_at,
                atom_count,
            },
        ))
    }

