    async fn link_node_atoms_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        pairs: &[(Uuid, Uuid)],
    ) -> Result<(), StoreError> {
        if pairs.is_empty() {
            return Ok(());
        }
        let node_ids: Vec<Uuid> = pairs.iter().map(|(n, _)| *n).collect();
        let atom_ids: Vec<Uuid> = pairs.iter().map(|(_, a)| *a).collect();

        // One multi-row upsert; RETURNING yields only the genuinely-new links so
        // we emit exactly one op per real state change (re-links produce none).
        let inserted: Vec<(Uuid, Uuid)> = sqlx::query_as(
            "INSERT INTO node_atoms (node_id, atom_id) \
             SELECT * FROM UNNEST($1::uuid[], $2::uuid[]) \
             ON CONFLICT DO NOTHING \
             RETURNING node_id, atom_id",
        )
        .bind(&node_ids)
        .bind(&atom_ids)
        .fetch_all(&mut **tx)
        .await?;

        for (node_id, atom_id) in &inserted {
            let gid: Option<Uuid> =
                sqlx::query_scalar("SELECT graph_id FROM nodes WHERE node_id = $1")
                    .bind(node_id)
                    .fetch_optional(&mut **tx)
                    .await?;
            if let Some(gid) = gid {
                let op = sync::node_atom_op(
                    Uuid::new_v4(),
                    *node_id,
                    *atom_id,
                    gid,
                    OpType::Upsert,
                    Utc::now(),
                    self.device_id(),
                );
                append_op_tx(&mut *tx, &op).await?;
            }
        }

        Ok(())
    }

    async fn list_meeting_new_entities_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        graph_id: Uuid,
        source_id: &str,
    ) -> Result<Vec<MeetingEntity>, StoreError> {
        // Entity reefs linked to this meeting's chunk atoms (source_id prefix),
        // created at/after the transcript so we surface only entities this meeting
        // introduced (best-effort).
        type Row = (Uuid, String, DateTime<Utc>);
        let rows: Vec<Row> = sqlx::query_as(&format!(
            "SELECT DISTINCT n.node_id, n.title, n.created_at \
             FROM nodes n \
             JOIN node_atoms na ON na.node_id = n.node_id \
             JOIN atoms a ON a.atom_id = na.atom_id \
             WHERE n.graph_id = $1 \
               AND n.type = 'entity' \
               AND a.graph_id = $1 \
               AND a.source_id LIKE $2 \
               AND {floor} \
               AND n.created_at >= COALESCE( \
                   (SELECT created_at FROM meeting_transcripts \
                    WHERE graph_id = $1 AND source_id = $3), \
                   '-infinity'::timestamptz) \
             ORDER BY n.created_at ASC \
             LIMIT {cap}",
            cap = MEETING_DETAIL_CAP + 1,
            floor = crate::history_floor::admits_atom("a")
        ))
        .bind(graph_id)
        .bind(like_prefix(source_id))
        .bind(source_id)
        .fetch_all(&mut **tx)
        .await?;
        Ok(rows
            .into_iter()
            .map(|(node_id, title, created_at)| MeetingEntity {
                node_id,
                title,
                created_at,
            })
            .collect())
    }

    async fn meeting_occurred_at_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        graph_id: Uuid,
        source_id: &str,
    ) -> Result<Option<DateTime<Utc>>, StoreError> {
        let occurred_at: Option<DateTime<Utc>> = sqlx::query_scalar(&format!(
            "SELECT MIN(timestamp) FROM atoms a WHERE graph_id = $1 AND source_id LIKE $2 AND {floor}",
            floor = crate::history_floor::admits_atom("a")
        ))
        .bind(graph_id)
        .bind(like_prefix(source_id))
        .fetch_one(&mut **tx)
        .await?;
        Ok(occurred_at)
    }

