    async fn set_node_digest_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        node_id: Uuid,
        digest_json: &str,
    ) -> Result<(), StoreError> {
        type Row = (
            Uuid,
            String,
            String,
            Value,
            String,
            Option<Uuid>,
            DateTime<Utc>,
            DateTime<Utc>,
            i32,
        );
        let updated: Option<Row> = sqlx::query_as(
            "UPDATE nodes SET body = jsonb_set(body, '{digest}', $2::jsonb), \
                 updated_at = now(), version = version + 1 \
             WHERE node_id = $1 \
             RETURNING graph_id, type, title, body, scope, owner_id, created_at, updated_at, version",
        )
        .bind(node_id)
        .bind(digest_json)
        .fetch_optional(&mut **tx)
        .await?;
        if let Some((graph_id, t, ti, b, sc, ow, ca, ua, ve)) = updated {
            append_op_tx(
                &mut *tx,
                &sync::node_upsert_op(
                    Uuid::new_v4(),
                    node_id,
                    graph_id,
                    &t,
                    &ti,
                    &b.to_string(),
                    &sc,
                    ow,
                    ca,
                    ua,
                    i64::from(ve),
                    self.device_id(),
                ),
            )
            .await?;
        }
        Ok(())
    }

    async fn node_digest_context_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        node_id: Uuid,
    ) -> Result<Option<NodeDigestContext>, StoreError> {
        type Row = (Uuid, String, String, i64, i64, Option<String>);
        let row: Option<Row> = sqlx::query_as(verdict::NODE_DIGEST_CONTEXT_SQL)
        .bind(node_id)
        .fetch_optional(&mut **tx)
        .await?;
        Ok(row.map(
            |(graph_id, node_type, title, coral_count, digest_coral_count, cached_digest)| {
                NodeDigestContext {
                    graph_id,
                    node_type,
                    title,
                    coral_count,
                    digest_coral_count,
                    cached_digest,
                }
            },
        ))
    }

