    async fn ensure_self_node_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        graph_id: Uuid,
        owner_user_id: Uuid,
        title: &str,
    ) -> Result<(Uuid, String), StoreError> {
        type UpsertRow = (
            Uuid,          // node_id
            Value,         // body (jsonb)
            String,        // scope
            Option<Uuid>,  // owner_id
            DateTime<Utc>, // created_at
            DateTime<Utc>, // updated_at
            i32,           // version (INT4)
        );

        // Fast path: a self reef already exists for this ocean — return it
        // unchanged (do NOT rename, so the bootstrap title sticks).
        if let Some((existing_id, existing_title)) = sqlx::query_as::<_, (Uuid, String)>(
            "SELECT n.node_id, n.title \
             FROM graphs g JOIN nodes n ON n.node_id = g.self_node_id \
             WHERE g.id = $1 AND g.self_node_id IS NOT NULL",
        )
        .bind(graph_id)
        .fetch_optional(&mut **tx)
        .await?
        {
            return Ok((existing_id, existing_title));
        }

        // Create (or adopt an existing same-title) entity reef for the owner.
        // `owner_id` stamps the human the reef stands for. The node-upsert op is
        // emitted like any other.
        let row: UpsertRow = sqlx::query_as(
            "INSERT INTO nodes (node_id, graph_id, type, title, owner_id, created_at, updated_at) \
             VALUES (gen_random_uuid(), $1, 'entity', $2, $3, now(), now()) \
             ON CONFLICT (graph_id, type, lower(title), identity_scope) \
             DO UPDATE SET updated_at = now(), version = nodes.version + 1 \
             RETURNING node_id, body, scope, owner_id, created_at, updated_at, version",
        )
        .bind(graph_id)
        .bind(title)
        .bind(owner_user_id)
        .fetch_one(&mut **tx)
        .await?;

        let (node_id, body, scope, owner_id, created_at, updated_at, version) = row;

        let op = sync::node_upsert_op(
            Uuid::new_v4(),
            node_id,
            graph_id,
            "entity",
            title,
            &body.to_string(),
            &scope,
            owner_id,
            created_at,
            updated_at,
            i64::from(version),
            self.device_id(),
        );
        append_op_tx(&mut *tx, &op).await?;

        // Stamp the pointer. `self_node_id` is server-only (not in an op): the
        // reef itself syncs, but which reef is "self" is a cloud-side ingest
        // decision, so it is not propagated through the oplog.
        sqlx::query("UPDATE graphs SET self_node_id = $1 WHERE id = $2")
            .bind(node_id)
            .bind(graph_id)
            .execute(&mut **tx)
            .await?;

        Ok((node_id, title.to_string()))
    }

