    async fn append_message_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        msg: NewMessage,
    ) -> Result<ConversationMessage, StoreError> {
        // seq = MAX(seq)+1 can race two concurrent appends to the same
        // conversation onto the same value; the UNIQUE(conversation_id, seq)
        // constraint then rejects one. Retry on a unique violation — the retry
        // recomputes the next free seq (cs-ask-chat-a M2).
        for attempt in 0..5 {
            let scope_json = serde_json::json!(msg
                .scope_graph_ids
                .iter()
                .map(|u| u.to_string())
                .collect::<Vec<_>>());
            let res = sqlx::query_as::<_, PgMsgRow>(
                r#"INSERT INTO conversation_messages
                       (conversation_id, seq, role, text, citations, sources, mode, timing,
                        scope_graph_ids)
                   VALUES ($1,
                           (SELECT COALESCE(MAX(seq), -1) + 1
                              FROM conversation_messages WHERE conversation_id = $1),
                           $2, $3, $4, $5, $6, $7, $8)
                   RETURNING id, conversation_id, seq, role, text, citations, sources,
                             mode, timing, scope_graph_ids, created_at"#,
            )
            .bind(msg.conversation_id)
            .bind(&msg.role)
            .bind(&msg.text)
            .bind(&msg.citations)
            .bind(&msg.sources)
            .bind(&msg.mode)
            .bind(&msg.timing)
            .bind(&scope_json)
            .fetch_one(&mut **tx)
            .await;
            match res {
                Ok(row) => return Ok(pg_msg(row)),
                Err(e) => {
                    let unique = e
                        .as_database_error()
                        .map(|d| d.is_unique_violation())
                        .unwrap_or(false);
                    if unique && attempt < 4 {
                        continue;
                    }
                    return Err(e.into());
                }
            }
        }
        unreachable!("append_message retry loop always returns")
    }

