    async fn upsert_meeting_transcript_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        graph_id: Uuid,
        source_id: &str,
        raw_blob_key: Option<&str>,
        raw_inline: Option<&str>,
        duration_ms: Option<i64>,
        segments: Option<&serde_json::Value>,
    ) -> Result<(), StoreError> {
        // `segments` uses COALESCE(EXCLUDED, existing) so a re-ingest that omits
        // segments does not wipe a previously-stored set; a re-ingest that
        // carries them refreshes. The `summary*` columns are never written here.
        sqlx::query(
            "INSERT INTO meeting_transcripts \
                (graph_id, source_id, raw_blob_key, raw_inline, duration_ms, segments) \
             VALUES ($1, $2, $3, $4, $5, $6) \
             ON CONFLICT (graph_id, source_id) DO UPDATE SET \
                raw_blob_key = EXCLUDED.raw_blob_key, \
                raw_inline   = EXCLUDED.raw_inline, \
                duration_ms  = EXCLUDED.duration_ms, \
                segments     = COALESCE(EXCLUDED.segments, meeting_transcripts.segments)",
        )
        .bind(graph_id)
        .bind(source_id)
        .bind(raw_blob_key)
        .bind(raw_inline)
        .bind(duration_ms)
        .bind(segments)
        .execute(&mut **tx)
        .await?;
        Ok(())
    }

    async fn get_meeting_transcript_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        graph_id: Uuid,
        source_id: &str,
    ) -> Result<Option<MeetingTranscript>, StoreError> {
        type Row = (
            Option<String>,
            Option<String>,
            Option<i64>,
            DateTime<Utc>,
            Option<serde_json::Value>,
            String,
            Option<serde_json::Value>,
            Option<String>,
            Option<String>,
        );
        // The reader's team-seat history floor (#1545, crate::history_floor).
        let row: Option<Row> = sqlx::query_as(&format!(
            "SELECT raw_blob_key, raw_inline, duration_ms, created_at, \
                    segments, summary_status, summary, summary_model, summary_error \
             FROM meeting_transcripts t WHERE graph_id = $1 AND source_id = $2 AND {floor}",
            floor = crate::history_floor::admits_transcript("t")
        ))
        .bind(graph_id)
        .bind(source_id)
        .fetch_optional(&mut **tx)
        .await?;
        Ok(row.map(
            |(
                raw_blob_key,
                raw_inline,
                duration_ms,
                created_at,
                segments,
                summary_status,
                summary,
                summary_model,
                summary_error,
            )| MeetingTranscript {
                graph_id,
                source_id: source_id.to_string(),
                raw_blob_key,
                raw_inline,
                duration_ms,
                created_at,
                segments,
                summary_status,
                summary,
                summary_model,
                summary_error,
            },
        ))
    }

