    async fn reset_meeting_summary_pending_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        graph_id: Uuid,
        source_id: &str,
    ) -> Result<SummaryResetOutcome, StoreError> {
        // One atomic statement: the `existing` CTE snapshots whether the row is
        // present; `upd` resets it to `pending` ONLY when it isn't already
        // `running`; the final SELECT (present only when the row exists) reports
        // whether the reset fired. Reset-when-not-running + report-in-one avoids a
        // read-then-write race between two concurrent Retries.
        let row: Option<(bool,)> = sqlx::query_as(
            "WITH existing AS ( \
                 SELECT 1 FROM meeting_transcripts \
                 WHERE graph_id = $1 AND source_id = $2 \
             ), upd AS ( \
                 UPDATE meeting_transcripts \
                 SET summary_status = 'pending', summary_error = NULL, summary_updated_at = now() \
                 WHERE graph_id = $1 AND source_id = $2 \
                   AND summary_status IS DISTINCT FROM 'running' \
                 RETURNING 1 \
             ) \
             SELECT EXISTS (SELECT 1 FROM upd) AS did_reset FROM existing",
        )
        .bind(graph_id)
        .bind(source_id)
        .fetch_optional(&mut **tx)
        .await?;
        Ok(match row {
            None => SummaryResetOutcome::NotFound,
            Some((true,)) => SummaryResetOutcome::Reset,
            Some((false,)) => SummaryResetOutcome::AlreadyRunning,
        })
    }

    async fn list_meeting_transcripts_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        graph_id: Uuid,
        limit: i64,
        offset: i64,
        since: Option<DateTime<Utc>>,
        until: Option<DateTime<Utc>>,
    ) -> Result<Vec<MeetingTranscript>, StoreError> {
        type Row = (String, Option<i64>, DateTime<Utc>);
        // The reader's team-seat history floor (#1545, crate::history_floor).
        let rows: Vec<Row> = sqlx::query_as(&format!(
            "SELECT source_id, duration_ms, created_at \
             FROM meeting_transcripts t \
             WHERE graph_id = $1 \
               AND ($4::timestamptz IS NULL OR created_at >= $4) \
               AND ($5::timestamptz IS NULL OR created_at <= $5) \
               AND {floor} \
             ORDER BY created_at DESC \
             LIMIT $2 OFFSET $3",
            floor = crate::history_floor::admits_transcript("t")
        ))
        .bind(graph_id)
        .bind(limit)
        .bind(offset)
        .bind(since)
        .bind(until)
        .fetch_all(&mut **tx)
        .await?;
        Ok(rows
            .into_iter()
            .map(|(source_id, duration_ms, created_at)| MeetingTranscript {
                graph_id,
                source_id,
                // Metadata-only listing never reads blob keys / inline text, and
                // does not surface summary state (callers use the per-meeting
                // `get_meeting_transcript` / summary API for that).
                raw_blob_key: None,
                raw_inline: None,
                duration_ms,
                created_at,
                segments: None,
                summary_status: "pending".to_string(),
                summary: None,
                summary_model: None,
                summary_error: None,
            })
            .collect())
    }

