    async fn get_active_meeting_share_by_token_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        token: &str,
    ) -> Result<Option<MeetingShare>, StoreError> {
        type Row = (Uuid, Uuid, String, String, Uuid, DateTime<Utc>);
        // Same `g.archived_at IS NULL` gate as the unscoped
        // `get_active_meeting_share_by_token` — see that method's comment.
        // This is the copy the org-tenant plane actually exercises
        // (`routes::shares::resolve_share_by_token`'s scoped branch runs
        // unconditionally, consumer AND org-tenant alike).
        let row: Option<Row> = sqlx::query_as(
            "SELECT ms.id, ms.graph_id, ms.source_id, ms.visibility, ms.created_by, ms.created_at \
             FROM meeting_shares ms \
             JOIN graphs g ON g.id = ms.graph_id \
             WHERE ms.token = $1 AND ms.revoked_at IS NULL AND g.archived_at IS NULL",
        )
        .bind(token)
        .fetch_optional(&mut **tx)
        .await?;
        Ok(row.map(
            |(id, graph_id, source_id, visibility, created_by, created_at)| MeetingShare {
                id,
                graph_id,
                source_id,
                token: token.to_string(),
                visibility,
                created_by,
                created_at,
                revoked_at: None,
            },
        ))
    }

    async fn list_query_history_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        account_id: Uuid,
        caller_user_id: Uuid,
        graph_id: Option<Uuid>,
        limit: i64,
        offset: i64,
    ) -> Result<Vec<QueryHistoryRow>, StoreError> {
        type HistoryRow = (
            Uuid,
            Uuid,
            Option<Uuid>,
            String,
            String,
            i32,
            i32,
            i32,
            DateTime<Utc>,
        );

        // `AND (user_id = $N OR user_id IS NULL)` (Group-B security fix, PR 0
        // of the member-private-oceans plan, item 6): see the trait doc
        // comment on `Store::list_query_history` for why the `IS NULL` arm is
        // kept.
        let rows: Vec<HistoryRow> = match graph_id {
            Some(gid) => {
                sqlx::query_as(verdict::QUERY_HISTORY_GRAPH_PAGE_SQL)
                .bind(account_id)
                .bind(caller_user_id)
                .bind(gid)
                .bind(limit)
                .bind(offset)
                .fetch_all(&mut **tx)
                .await?
            }
            None => {
                sqlx::query_as(verdict::QUERY_HISTORY_PAGE_SQL)
                .bind(account_id)
                .bind(caller_user_id)
                .bind(limit)
                .bind(offset)
                .fetch_all(&mut **tx)
                .await?
            }
        };

        Ok(rows
            .into_iter()
            .map(
                |(
                    id,
                    graph_id,
                    user_id,
                    query_text,
                    answer_summary,
                    citation_count,
                    input_tokens,
                    output_tokens,
                    created_at,
                )| QueryHistoryRow {
                    id,
                    graph_id,
                    user_id,
                    query_text,
                    answer_summary,
                    citation_count,
                    input_tokens,
                    output_tokens,
                    created_at,
                },
            )
            .collect())
    }

