    async fn list_activity_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        account_id: Uuid,
        caller_user_id: Uuid,
        graph_id: Option<Uuid>,
        event_type: Option<&str>,
        limit: u32,
        offset: u32,
    ) -> Result<Vec<ActivityEvent>, StoreError> {
        // Build the query dynamically based on which optional filters are
        // present. We use four variants to avoid runtime string building while
        // keeping the SQL readable and the bind parameters type-safe.
        //
        // `AND (user_id = $N OR user_id IS NULL)` (Group-B security fix, PR 0
        // of the member-private-oceans plan, item 7): see the trait doc
        // comment on `Store::list_activity` for why the `IS NULL` arm is kept.
        type ActivityRow = (
            Uuid,
            Option<Uuid>,
            Option<Uuid>,
            String,
            Value,
            DateTime<Utc>,
        );

        let rows: Vec<ActivityRow> = match (graph_id, event_type) {
            (None, None) => {
                sqlx::query_as(
                    "SELECT id, user_id, graph_id, event_type, payload, created_at \
                     FROM activity_events \
                     WHERE account_id = $1 \
                       AND (user_id = $2 OR user_id IS NULL) \
                     ORDER BY created_at DESC \
                     LIMIT $3 OFFSET $4",
                )
                .bind(account_id)
                .bind(caller_user_id)
                .bind(limit as i64)
                .bind(offset as i64)
                .fetch_all(&mut **tx)
                .await?
            }
            (Some(gid), None) => {
                sqlx::query_as(
                    "SELECT id, user_id, graph_id, event_type, payload, created_at \
                     FROM activity_events \
                     WHERE account_id = $1 \
                       AND (user_id = $2 OR user_id IS NULL) \
                       AND graph_id = $3 \
                     ORDER BY created_at DESC \
                     LIMIT $4 OFFSET $5",
                )
                .bind(account_id)
                .bind(caller_user_id)
                .bind(gid)
                .bind(limit as i64)
                .bind(offset as i64)
                .fetch_all(&mut **tx)
                .await?
            }
            (None, Some(et)) => {
                sqlx::query_as(
                    "SELECT id, user_id, graph_id, event_type, payload, created_at \
                     FROM activity_events \
                     WHERE account_id = $1 \
                       AND (user_id = $2 OR user_id IS NULL) \
                       AND event_type = $3 \
                     ORDER BY created_at DESC \
                     LIMIT $4 OFFSET $5",
                )
                .bind(account_id)
                .bind(caller_user_id)
                .bind(et)
                .bind(limit as i64)
                .bind(offset as i64)
                .fetch_all(&mut **tx)
                .await?
            }
            (Some(gid), Some(et)) => {
                sqlx::query_as(
                    "SELECT id, user_id, graph_id, event_type, payload, created_at \
                     FROM activity_events \
                     WHERE account_id = $1 \
                       AND (user_id = $2 OR user_id IS NULL) \
                       AND graph_id = $3 \
                       AND event_type = $4 \
                     ORDER BY created_at DESC \
                     LIMIT $5 OFFSET $6",
                )
                .bind(account_id)
                .bind(caller_user_id)
                .bind(gid)
                .bind(et)
                .bind(limit as i64)
                .bind(offset as i64)
                .fetch_all(&mut **tx)
                .await?
            }
        };

        Ok(rows
            .into_iter()
            .map(
                |(id, user_id, graph_id, event_type, payload, created_at)| ActivityEvent {
                    id,
                    user_id,
                    graph_id,
                    event_type,
                    payload,
                    created_at,
                },
            )
            .collect())
    }

    #[allow(clippy::too_many_arguments)]
    async fn upsert_journal_rollup(
        &self,
        account_id: Uuid,
        user_id: Uuid,
        graph_id: Uuid,
        hour_start: DateTime<Utc>,
        summary: &str,
        stats: Value,
        input_fingerprint: &str,
        model: &str,
    ) -> Result<JournalRollup, StoreError> {
        let row: PgJournalRollupRow = sqlx::query_as(&format!(
            r#"
            INSERT INTO journal_rollups
                (account_id, user_id, graph_id, hour_start, period_start, granularity,
                 summary, stats, input_fingerprint, model, recompile_count, compiled_at)
            VALUES ($1, $2, $3, $4, $4, 'hour', $5, $6, $7, $8, 0, now())
            ON CONFLICT (user_id, graph_id, granularity, hour_start) DO UPDATE SET
                account_id        = EXCLUDED.account_id,
                summary           = EXCLUDED.summary,
                stats             = EXCLUDED.stats,
                input_fingerprint = EXCLUDED.input_fingerprint,
                model             = EXCLUDED.model,
                recompile_count   = journal_rollups.recompile_count + 1,
                compiled_at       = EXCLUDED.compiled_at
            RETURNING {JOURNAL_ROLLUP_COLUMNS}
            "#
        ))
        .bind(account_id)
        .bind(user_id)
        .bind(graph_id)
        .bind(hour_start)
        .bind(summary)
        .bind(stats)
        .bind(input_fingerprint)
        .bind(model)
        .fetch_one(&self.pool)
        .await?;

        Ok(pg_journal_rollup(row))
    }

    #[allow(clippy::too_many_arguments)]
    async fn upsert_journal_tier_rollup(
        &self,
        account_id: Uuid,
        user_id: Uuid,
        graph_id: Uuid,
        granularity: &str,
        period_start: DateTime<Utc>,
        tz: &str,
        summary: &str,
        stats: Value,
        input_fingerprint: &str,
        model: &str,
        stale_sibling_ids: &[Uuid],
    ) -> Result<JournalRollup, StoreError> {
        // Own short transaction (this method is called directly against the
        // ambient pool, unlike its `_scoped` sibling below): the stale-
        // sibling delete and the insert/update must land atomically, so a
        // boundary-matched read can never observe both the old- and
        // new-boundary row at once — see this method's trait doc comment
        // (ticket 20).
        let mut tx = self.pool.begin().await?;

        if !stale_sibling_ids.is_empty() {
            sqlx::query(
                "DELETE FROM journal_rollups \
                 WHERE id = ANY($1) AND user_id = $2 AND graph_id = $3 AND granularity = $4",
            )
            .bind(stale_sibling_ids)
            .bind(user_id)
            .bind(graph_id)
            .bind(granularity)
            .execute(&mut *tx)
            .await?;
        }

        let row: PgJournalRollupRow = sqlx::query_as(&format!(
            r#"
            INSERT INTO journal_rollups
                (account_id, user_id, graph_id, hour_start, period_start, granularity, tz,
                 summary, stats, input_fingerprint, model, recompile_count, compiled_at)
            VALUES ($1, $2, $3, $4, $4, $5, $6, $7, $8, $9, $10, 0, now())
            ON CONFLICT (user_id, graph_id, granularity, hour_start) DO UPDATE SET
                account_id        = EXCLUDED.account_id,
                tz                = EXCLUDED.tz,
                summary           = EXCLUDED.summary,
                stats             = EXCLUDED.stats,
                input_fingerprint = EXCLUDED.input_fingerprint,
                model             = EXCLUDED.model,
                recompile_count   = journal_rollups.recompile_count + 1,
                compiled_at       = EXCLUDED.compiled_at
            RETURNING {JOURNAL_ROLLUP_COLUMNS}
            "#
        ))
        .bind(account_id)
        .bind(user_id)
        .bind(graph_id)
        .bind(period_start)
        .bind(granularity)
        .bind(tz)
        .bind(summary)
        .bind(stats)
        .bind(input_fingerprint)
        .bind(model)
        .fetch_one(&mut *tx)
        .await?;

        tx.commit().await?;

        Ok(pg_journal_rollup(row))
    }

    #[allow(clippy::too_many_arguments)]
    async fn upsert_journal_tier_rollup_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        account_id: Uuid,
        user_id: Uuid,
        graph_id: Uuid,
        granularity: &str,
        period_start: DateTime<Utc>,
        tz: &str,
        summary: &str,
        stats: Value,
        input_fingerprint: &str,
        model: &str,
        stale_sibling_ids: &[Uuid],
    ) -> Result<JournalRollup, StoreError> {
        // Deletes inside the SAME caller-scoped `tx` as the insert/update
        // below — see the unscoped sibling's doc comment (ticket 20).
        if !stale_sibling_ids.is_empty() {
            sqlx::query(
                "DELETE FROM journal_rollups \
                 WHERE id = ANY($1) AND account_id = $2 AND user_id = $3 \
                   AND graph_id = $4 AND granularity = $5",
            )
            .bind(stale_sibling_ids)
            .bind(account_id)
            .bind(user_id)
            .bind(graph_id)
            .bind(granularity)
            .execute(&mut **tx)
            .await?;
        }

        let row: PgJournalRollupRow = sqlx::query_as(&format!(
            r#"
            INSERT INTO journal_rollups
                (account_id, user_id, graph_id, hour_start, period_start, granularity, tz,
                 summary, stats, input_fingerprint, model, recompile_count, compiled_at)
            VALUES ($1, $2, $3, $4, $4, $5, $6, $7, $8, $9, $10, 0, now())
            ON CONFLICT (user_id, graph_id, granularity, hour_start) DO UPDATE SET
                account_id        = EXCLUDED.account_id,
                tz                = EXCLUDED.tz,
                summary           = EXCLUDED.summary,
                stats             = EXCLUDED.stats,
                input_fingerprint = EXCLUDED.input_fingerprint,
                model             = EXCLUDED.model,
                recompile_count   = journal_rollups.recompile_count + 1,
                compiled_at       = EXCLUDED.compiled_at
            RETURNING {JOURNAL_ROLLUP_COLUMNS}
            "#
        ))
        .bind(account_id)
        .bind(user_id)
        .bind(graph_id)
        .bind(period_start)
        .bind(granularity)
        .bind(tz)
        .bind(summary)
        .bind(stats)
        .bind(input_fingerprint)
        .bind(model)
        .fetch_one(&mut **tx)
        .await?;

        Ok(pg_journal_rollup(row))
    }

    async fn journal_delete_orphaned_tier_rows(
        &self,
        user_id: Uuid,
        graph_id: Uuid,
        granularity: &str,
        ids: &[Uuid],
    ) -> Result<u64, StoreError> {
        if ids.is_empty() {
            return Ok(0);
        }
        let result = sqlx::query(
            "DELETE FROM journal_rollups \
             WHERE id = ANY($1) AND user_id = $2 AND graph_id = $3 AND granularity = $4",
        )
        .bind(ids)
        .bind(user_id)
        .bind(graph_id)
        .bind(granularity)
        .execute(&self.pool)
        .await?;
        Ok(result.rows_affected())
    }

    async fn journal_delete_orphaned_tier_rows_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        account_id: Uuid,
        user_id: Uuid,
        graph_id: Uuid,
        granularity: &str,
        ids: &[Uuid],
    ) -> Result<u64, StoreError> {
        if ids.is_empty() {
            return Ok(0);
        }
        let result = sqlx::query(
            "DELETE FROM journal_rollups \
             WHERE id = ANY($1) AND account_id = $2 AND user_id = $3 \
               AND graph_id = $4 AND granularity = $5",
        )
        .bind(ids)
        .bind(account_id)
        .bind(user_id)
        .bind(graph_id)
        .bind(granularity)
        .execute(&mut **tx)
        .await?;
        Ok(result.rows_affected())
    }

    async fn list_journal_rollups(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        user_id: Uuid,
        graph_ids: &[Uuid],
        granularity: &str,
        from: DateTime<Utc>,
        to: DateTime<Utc>,
    ) -> Result<Vec<JournalRollup>, StoreError> {
        // The reader's team-seat history floor (#1545): a rollup summarizes
        // its whole period, so one that starts before the floor is hidden.
        let rows: Vec<PgJournalRollupRow> = sqlx::query_as(&format!(
            "SELECT {JOURNAL_ROLLUP_COLUMNS} \
             FROM journal_rollups \
             WHERE user_id = $1 AND graph_id = ANY($2) AND granularity = $3 \
               AND hour_start >= $4 AND hour_start < $5 AND {floor} \
             ORDER BY hour_start ASC",
            floor = crate::history_floor::admits_period("graph_id", "hour_start")
        ))
        .bind(user_id)
        .bind(graph_ids)
        .bind(granularity)
        .bind(from)
        .bind(to)
        .fetch_all(&mut **tx)
        .await?;

        Ok(rows.into_iter().map(pg_journal_rollup).collect())
    }

    async fn journal_tier_window_groups(
        &self,
        child_granularity: &str,
        parent_granularity: &str,
        window_from: DateTime<Utc>,
        window_to: DateTime<Utc>,
    ) -> Result<Vec<JournalTierWindowGroup>, StoreError> {
        // ONE query, ONE snapshot — see `journal_tier_window_groups_from_rows`'s
        // doc comment for why this replaced two separate SELECTs.
        let rows: Vec<PgJournalRollupRow> = sqlx::query_as(&format!(
            "SELECT {JOURNAL_ROLLUP_COLUMNS} \
             FROM journal_rollups \
             WHERE granularity = ANY($1) AND period_start >= $2 AND period_start < $3 \
             ORDER BY user_id, graph_id, period_start ASC"
        ))
        .bind([child_granularity, parent_granularity])
        .bind(window_from)
        .bind(window_to)
        .fetch_all(&self.pool)
        .await?;

        Ok(journal_tier_window_groups_from_rows(
            parent_granularity,
            rows.into_iter().map(pg_journal_rollup).collect(),
        ))
    }

    async fn journal_tier_window_groups_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        account_id: Option<Uuid>,
        child_granularity: &str,
        parent_granularity: &str,
        window_from: DateTime<Utc>,
        window_to: DateTime<Utc>,
    ) -> Result<Vec<JournalTierWindowGroup>, StoreError> {
        // ONE query, ONE snapshot — see `journal_tier_window_groups_from_rows`'s
        // doc comment for why this replaced two separate SELECTs.
        //
        // `$1::uuid IS NULL OR …` is the org-tenant caller's arm (see the
        // trait doc): one account per tenant database, so no account
        // predicate. The cast is load-bearing — `$1` also appears in an
        // equality against a `uuid` column, but writing the bare `$1 IS NULL`
        // leaves Postgres to resolve the parameter type from that other use
        // alone, and spelling it here keeps the query self-describing.
        let rows: Vec<PgJournalRollupRow> = sqlx::query_as(&format!(
            "SELECT {JOURNAL_ROLLUP_COLUMNS} \
             FROM journal_rollups \
             WHERE ($1::uuid IS NULL OR account_id = $1) AND granularity = ANY($2) \
               AND period_start >= $3 AND period_start < $4 \
             ORDER BY user_id, graph_id, period_start ASC"
        ))
        .bind(account_id)
        .bind([child_granularity, parent_granularity])
        .bind(window_from)
        .bind(window_to)
        .fetch_all(&mut **tx)
        .await?;

        Ok(journal_tier_window_groups_from_rows(
            parent_granularity,
            rows.into_iter().map(pg_journal_rollup).collect(),
        ))
    }

    async fn user_timezone(&self, user_id: Uuid) -> Result<Option<String>, StoreError> {
        let row: Option<(Option<String>,)> = sqlx::query_as("SELECT timezone FROM users WHERE id = $1")
            .bind(user_id)
            .fetch_optional(&self.pool)
            .await?;
        Ok(row.and_then(|(tz,)| tz))
    }

    async fn set_user_timezone(&self, user_id: Uuid, timezone: &str) -> Result<(), StoreError> {
        sqlx::query(
            "UPDATE users SET timezone = $2, updated_at = now() \
             WHERE id = $1 AND timezone IS DISTINCT FROM $2",
        )
        .bind(user_id)
        .bind(timezone)
        .execute(&self.pool)
        .await?;
        Ok(())
    }

    async fn user_active_graph(
        &self,
        user_id: Uuid,
        account_id: Uuid,
    ) -> Result<Option<Uuid>, StoreError> {
        let row: Option<(Uuid,)> = sqlx::query_as(
            "SELECT graph_id FROM user_active_graph WHERE user_id = $1 AND account_id = $2",
        )
        .bind(user_id)
        .bind(account_id)
        .fetch_optional(crate::tenancy::scope::request_read(&self.pool))
        .await?;
        Ok(row.map(|(graph_id,)| graph_id))
    }

    async fn set_user_active_graph(
        &self,
        user_id: Uuid,
        account_id: Uuid,
        graph_id: Uuid,
    ) -> Result<(), StoreError> {
        sqlx::query(
            "INSERT INTO user_active_graph (user_id, account_id, graph_id, updated_at) \
             VALUES ($1, $2, $3, now()) \
             ON CONFLICT (user_id, account_id) DO UPDATE \
               SET graph_id = EXCLUDED.graph_id, updated_at = now() \
             WHERE user_active_graph.graph_id IS DISTINCT FROM EXCLUDED.graph_id",
        )
        .bind(user_id)
        .bind(account_id)
        .bind(graph_id)
        .execute(&self.pool)
        .await?;
        Ok(())
    }

    async fn journal_range_aggregate(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        user_id: Uuid,
        graph_ids: &[Uuid],
        from: DateTime<Utc>,
        to: DateTime<Utc>,
    ) -> Result<Vec<JournalHourAggregate>, StoreError> {
        // One row per (hour, graph, source_type, grouping_key) — the atoms
        // half of the aggregate. `grouping_key` mirrors the convention
        // documented on `JournalInputAtom::source_id`: a coding-session
        // atom's `source_id` is `"cc:{session_id}:{checkpoint_id}[:chunk:N]"`
        // (migration `0076_coding_sessions`'s header) — but, unlike every
        // other MCP identifier in this codebase, `session_id` and
        // `checkpoint_id` carry NO charset restriction beyond a length cap
        // (`add_context`'s validation, `mcp/tools/write.rs`), so they may
        // themselves contain colons. `split_part(source_id, ':', 2)` used to
        // extract `session_id` here, which truncates at the FIRST colon
        // inside a colon-bearing `session_id` (e.g. `"cc:team:alpha:ckpt-1"`
        // truncates to `"team"`) — splitting one session into multiple
        // blocks and breaking the `coding_sessions` title join. Fixed by
        // joining the same way every other session read in this codebase
        // does (`Store::list_coding_sessions`'s `coral_count` subquery,
        // `session_source_id_prefix`): match each atom against the actual
        // `coding_sessions.session_id` via the escaped `"cc:{session_id}:%"`
        // LIKE prefix, so the grouping key is the session ROW's own
        // `session_id`, never a heuristic re-split of `source_id`. The
        // `REPLACE` chain mirrors `session_source_id_prefix`'s escaping
        // exactly, just expressed as SQL string functions since the pattern
        // is correlated (depends on `cs.session_id`, a column from the
        // joined row, not a single caller-supplied value known before the
        // query runs) — same rationale as that method's own doc comment.
        // `UNIQUE (graph_id, session_id)` (migration `0076`'s `coding_sessions`
        // table) plus that escaping's own no-cross-session-prefix-collision
        // guarantee (`session_source_id_prefix`'s test suite) means at most
        // one `coding_sessions` row can match any one atom, so this LEFT
        // JOIN can never fan a row out. A `coding_session` atom whose
        // session upsert never landed (`upsert_coding_session_scoped` is
        // best-effort, `routes/ingest.rs` step 8d) has no match; rather than
        // guess a boundary between `session_id`/`checkpoint_id` with no
        // verified session row to check it against, that atom falls back to
        // grouping by its own full `source_id` (one block per orphaned
        // checkpoint) instead of silently mis-grouping it with another
        // orphan under a wrong heuristic split. Every other source type
        // still strips a trailing `:chunk:{n}` off its own `source_id` (the
        // `meeting_transcripts` chunking convention, migration `0056`'s
        // header) to recover its "base" container id. `MAX(fa.title)` is a
        // cheap, deterministic stand-in for "some atom in this group got
        // titled" (0097's per-CORAL headline, NOT a session/meeting title)
        // — used only when there is no better title source for this block
        // (see the mapping below).
        type BlockRow = (
            DateTime<Utc>,  // hour_start
            String,         // source_type
            i64,            // atom_count
            Option<String>, // any_title (MAX(atoms.title) in the group)
            Option<String>, // session_title (coding_sessions.title, coding_session groups only)
        );
        // `{sess}` below is `ingest::atom::SESSION_SOURCE_TYPES_SQL_ARRAY`
        // — see the inline SQL comments and that constant's doc comment.
        let sql = format!(
            r#"
            WITH filtered_atoms AS (
                SELECT
                    a.graph_id,
                    date_trunc('hour', a."timestamp" AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' AS hour_start,
                    a.source_type,
                    a.title,
                    {grouping_key} AS grouping_key,
                    cs.title AS session_title
                FROM atoms a
                {session_join}
                WHERE a.ingested_by = $1
                  AND a.graph_id = ANY($2)
                  AND a."timestamp" >= $3 AND a."timestamp" < $4
                  -- The reader's team-seat history floor (#1545).
                  AND {floor}
            )
            SELECT
                fa.hour_start,
                fa.source_type,
                COUNT(*) AS atom_count,
                MAX(fa.title) AS any_title,
                MAX(fa.session_title) AS session_title
            FROM filtered_atoms fa
            GROUP BY fa.hour_start, fa.graph_id, fa.source_type, fa.grouping_key
            ORDER BY fa.hour_start ASC, COUNT(*) DESC, fa.source_type ASC, fa.grouping_key ASC
            "#,
            grouping_key = crate::journal_grouping::grouping_key_sql(),
            session_join = crate::journal_grouping::session_join_sql(),
            floor = crate::history_floor::admits_atom("a")
        );
        let block_rows: Vec<BlockRow> = sqlx::query_as(&sql)
        .bind(user_id)
        .bind(graph_ids)
        .bind(from)
        .bind(to)
        .fetch_all(&mut **tx)
        .await?;

        // The "asks" half — `query_history` rows in the same window, same
        // author-attribution and graph_ids predicates.
        type AskRow = (DateTime<Utc>, i64);
        let ask_rows: Vec<AskRow> = sqlx::query_as(
            "SELECT date_trunc('hour', qh.created_at AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' AS hour_start, \
                    COUNT(*) AS asks \
             FROM query_history qh \
             WHERE qh.user_id = $1 AND qh.graph_id = ANY($2) \
               AND qh.created_at >= $3 AND qh.created_at < $4 \
             GROUP BY 1",
        )
        .bind(user_id)
        .bind(graph_ids)
        .bind(from)
        .bind(to)
        .fetch_all(&mut **tx)
        .await?;

        // `BTreeMap` so the final `Vec` comes out hour_start-ascending for
        // free, matching `list_journal_rollups`'s own ordering contract.
        let mut by_hour: std::collections::BTreeMap<DateTime<Utc>, (i64, Vec<JournalAggregateBlock>)> =
            std::collections::BTreeMap::new();
        for (hour_start, source_type, atom_count, any_title, session_title) in block_rows {
            // Title precedence: a coding session's own (title-sweep-produced)
            // title first, then any grouped atom's per-coral headline, then a
            // generic source_type label. Every other source type skips
            // straight to "grouped atom's headline, else label" — there is no
            // cheap session/meeting-level title source for them today (a real
            // meeting title requires resolving the raw transcript, which can
            // be R2-encrypted — out of scope for this deterministic, DB-only
            // aggregate; see `routes::journal`'s module doc for the full
            // deviation note).
            // Rider A: was `source_type == "coding_session"` — every session
            // source type now gets a `session_title` from the widened
            // LATERAL join above, so the title-precedence rule must widen
            // with it or a `meeting_session` block would have
            // a real session title available and never use it.
            let title = if crate::ingest::atom::is_session_source_type(&source_type) {
                session_title.or(any_title).unwrap_or_else(|| journal_block_title_fallback(&source_type))
            } else {
                any_title.unwrap_or_else(|| journal_block_title_fallback(&source_type))
            };
            let entry = by_hour.entry(hour_start).or_insert_with(|| (0, Vec::new()));
            entry.0 += atom_count;
            entry.1.push(JournalAggregateBlock { source_type, title, atom_count });
        }

        let mut asks_by_hour: std::collections::HashMap<DateTime<Utc>, i64> =
            std::collections::HashMap::new();
        for (hour_start, asks) in ask_rows {
            asks_by_hour.insert(hour_start, asks);
            // An "asks only" hour (no atoms) must still surface — this makes
            // sure it has a `by_hour` entry to attach `asks` to below.
            by_hour.entry(hour_start).or_insert_with(|| (0, Vec::new()));
        }

        Ok(by_hour
            .into_iter()
            .map(|(hour_start, (atom_count, blocks))| JournalHourAggregate {
                hour_start,
                atom_count,
                asks: asks_by_hour.get(&hour_start).copied().unwrap_or(0),
                blocks,
            })
            .collect())
    }

    async fn journal_hour_items(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        user_id: Uuid,
        graph_ids: &[Uuid],
        hour_start: DateTime<Utc>,
        cursor: Option<(DateTime<Utc>, Uuid)>,
        limit: i64,
    ) -> Result<Vec<JournalHourItem>, StoreError> {
        let hour_end = hour_start + chrono::Duration::hours(1);
        let (cursor_ts, cursor_id) = match cursor {
            Some((ts, id)) => (Some(ts), Some(id)),
            None => (None, None),
        };

        // One row per source, discriminated by `kind` — the UNION ALL this
        // builds is deliberately a raw, un-cast-checked query (this codebase's
        // convention for every `graph_id = ANY($n)` journal query, `sqlx::
        // query_as` not the `!` macro) so the three branches must each list
        // EVERY output column with an explicit type, even where a branch has
        // no data for it (`NULL::text`, etc.) — Postgres infers a UNION ALL's
        // column types from the first branch, and a later branch's untyped
        // `NULL` alone is ambiguous.
        //
        // The atoms branch reuses `journal_range_aggregate`'s CURRENT
        // `coding_sessions` join exactly: `LEFT JOIN LATERAL ... ORDER BY
        // length(session_id) DESC LIMIT 1` on the escaped `"cc:{session_id}:%"`
        // LIKE prefix, never `split_part(source_id, ':', 2)` (a colon-bearing
        // `session_id` like `"cc:team:alpha:ckpt-1"` truncates wrong under
        // `split_part`) and never a plain `LEFT JOIN` (one session id can be a
        // literal prefix of another — `"team"`/`"team:alpha"` can coexist —
        // so an unranked join can match, and fan an atom out across, more
        // than one `coding_sessions` row; the longest-match `ORDER BY`/`LIMIT`
        // picks the unique correct one). See that method's own LATERAL
        // subquery comment for the full rationale; duplicated here (not
        // extracted into a shared view) because it is one join condition,
        // not enough surface to justify a cross-query dependency.
        type ItemRow = (
            Uuid,           // id
            Uuid,           // graph_id
            DateTime<Utc>,  // occurred_at
            String,         // kind: "atom" | "activity" | "ask"
            Option<String>, // source_type (atom only)
            Option<String>, // title (atom only — session title, else atoms.title)
            Option<String>, // excerpt (atom only, persisted — migration 0116_atoms_excerpt)
            Option<String>, // content_inline (atom only, excerpt fallback for pre-backfill rows)
            Option<i32>,    // header_len (atom only)
            Option<String>, // event_type (activity only)
            Option<Value>,  // payload (activity only)
            Option<String>, // query_text (ask only)
            Option<i32>,    // citation_count (ask only)
        );
        // `{sess}` is `ingest::atom::SESSION_SOURCE_TYPES_SQL_ARRAY` — see
        // the inline SQL comment below and that constant's doc comment.
        let sql = format!(
            r#"
            WITH filtered_atoms AS (
                SELECT
                    a.atom_id       AS id,
                    a.graph_id      AS graph_id,
                    a."timestamp"   AS occurred_at,
                    a.source_type   AS source_type,
                    COALESCE(cs.title, a.title) AS title,
                    a.excerpt        AS excerpt,
                    a.content_inline AS content_inline,
                    a.header_len    AS header_len
                FROM atoms a
                LEFT JOIN LATERAL (
                    SELECT cs_inner.session_id, cs_inner.title
                    FROM coding_sessions cs_inner
                    -- Rider A (capture unit 03): every session-carrying
                    -- source_type joins against `coding_sessions` the same
                    -- way, not just coding sessions. `{{sess}}` is derived
                    -- from `SessionKind::ALL`
                    -- (`ingest::atom::SESSION_SOURCE_TYPES_SQL_ARRAY`), so
                    -- this list is DERIVED, not hand-kept in lockstep, and
                    -- cannot drift from `is_session_source_type`.
                    WHERE a.source_type = ANY({sess})
                      AND cs_inner.graph_id = a.graph_id
                      AND a.source_id LIKE (
                              'cc:' || REPLACE(REPLACE(REPLACE(
                                  cs_inner.session_id, '\', '\\'), '%', '\%'), '_', '\_')
                              || ':%'
                          )
                    ORDER BY length(cs_inner.session_id) DESC
                    LIMIT 1
                ) cs ON true
                WHERE a.ingested_by = $1
                  AND a.graph_id = ANY($2)
                  AND a."timestamp" >= $3 AND a."timestamp" < $4
                  -- The reader's team-seat history floor (#1545).
                  AND {floor}
            ),
            filtered_activity AS (
                SELECT
                    e.id AS id, e.graph_id AS graph_id, e.created_at AS occurred_at,
                    e.event_type AS event_type, e.payload AS payload
                FROM activity_events e
                WHERE e.user_id = $1
                  AND e.graph_id = ANY($2)
                  AND e.created_at >= $3 AND e.created_at < $4
            ),
            filtered_asks AS (
                SELECT
                    qh.id AS id, qh.graph_id AS graph_id, qh.created_at AS occurred_at,
                    qh.query_text AS query_text, qh.citation_count AS citation_count
                FROM query_history qh
                WHERE qh.user_id = $1
                  AND qh.graph_id = ANY($2)
                  AND qh.created_at >= $3 AND qh.created_at < $4
            ),
            combined AS (
                SELECT
                    id, graph_id, occurred_at, 'atom'::text AS kind,
                    source_type, title, excerpt, content_inline, header_len,
                    NULL::text  AS event_type, NULL::jsonb AS payload,
                    NULL::text  AS query_text, NULL::int   AS citation_count
                FROM filtered_atoms
                UNION ALL
                SELECT
                    id, graph_id, occurred_at, 'activity'::text AS kind,
                    NULL::text AS source_type, NULL::text AS title,
                    NULL::text AS excerpt, NULL::text AS content_inline, NULL::int AS header_len,
                    event_type, payload,
                    NULL::text AS query_text, NULL::int AS citation_count
                FROM filtered_activity
                UNION ALL
                SELECT
                    id, graph_id, occurred_at, 'ask'::text AS kind,
                    NULL::text AS source_type, NULL::text AS title,
                    NULL::text AS excerpt, NULL::text AS content_inline, NULL::int AS header_len,
                    NULL::text AS event_type, NULL::jsonb AS payload,
                    query_text, citation_count
                FROM filtered_asks
            )
            SELECT id, graph_id, occurred_at, kind, source_type, title, excerpt, content_inline,
                   header_len, event_type, payload, query_text, citation_count
            FROM combined
            WHERE $5::timestamptz IS NULL
               OR (occurred_at, id) > ($5::timestamptz, $6::uuid)
            ORDER BY occurred_at ASC, id ASC
            LIMIT $7
            "#,
            sess = *crate::ingest::atom::SESSION_SOURCE_TYPES_SQL_ARRAY,
            floor = crate::history_floor::admits_atom("a")
        );
        let rows: Vec<ItemRow> = sqlx::query_as(&sql)
        .bind(user_id)
        .bind(graph_ids)
        .bind(hour_start)
        .bind(hour_end)
        .bind(cursor_ts)
        .bind(cursor_id)
        .bind(limit)
        .fetch_all(&mut **tx)
        .await?;

        Ok(rows
            .into_iter()
            .filter_map(
                |(
                    id,
                    graph_id,
                    occurred_at,
                    kind,
                    source_type,
                    title,
                    excerpt,
                    content_inline,
                    header_len,
                    event_type,
                    payload,
                    query_text,
                    citation_count,
                )| {
                    let kind = match kind.as_str() {
                        "atom" => {
                            // Prefer the persisted excerpt (written at ingest
                            // time, storage-backend-independent — gap 9 /
                            // migration 0116_atoms_excerpt), falling back to
                            // deriving it from `content_inline` for rows
                            // written before that column existed and never
                            // backfilled — same `derive_journal_excerpt`
                            // helper `journal_hour_inputs` uses, so the two
                            // read paths can never strip/truncate
                            // differently.
                            let excerpt =
                                excerpt.or_else(|| derive_journal_excerpt(content_inline.as_deref(), header_len));
                            JournalHourItemKind::Atom {
                                source_type: source_type?,
                                excerpt,
                                group_label: title,
                            }
                        }
                        "activity" => {
                            let event_type = event_type?;
                            let payload = payload.unwrap_or(Value::Null);
                            let label = crate::workers::journal_sweep::activity_event_label(
                                &event_type,
                                &payload,
                            );
                            JournalHourItemKind::Activity { event_type, label }
                        }
                        "ask" => JournalHourItemKind::Ask {
                            question: query_text.unwrap_or_default(),
                            citation_count: citation_count.unwrap_or(0),
                        },
                        // Unreachable given the query's own `'atom'|'activity'|'ask'`
                        // literals, but stay total rather than panicking on a
                        // hypothetical future row shape.
                        _ => return None,
                    };
                    Some(JournalHourItem { id, graph_id, occurred_at, kind })
                },
            )
            .collect())
    }

    async fn journal_hour_item_totals(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        user_id: Uuid,
        graph_ids: &[Uuid],
        hour_start: DateTime<Utc>,
    ) -> Result<JournalHourItemTotals, StoreError> {
        let hour_end = hour_start + chrono::Duration::hours(1);
        type TotalsRow = (i64, i64, i64);
        let (atoms, activity, asks): TotalsRow = sqlx::query_as(&format!(
            r#"
            SELECT
                (SELECT COUNT(*) FROM atoms a
                  WHERE a.ingested_by = $1 AND a.graph_id = ANY($2)
                    AND a."timestamp" >= $3 AND a."timestamp" < $4 AND {floor}) AS atoms,
                (SELECT COUNT(*) FROM activity_events e
                  WHERE e.user_id = $1 AND e.graph_id = ANY($2)
                    AND e.created_at >= $3 AND e.created_at < $4) AS activity,
                (SELECT COUNT(*) FROM query_history qh
                  WHERE qh.user_id = $1 AND qh.graph_id = ANY($2)
                    AND qh.created_at >= $3 AND qh.created_at < $4) AS asks
            "#,
            floor = crate::history_floor::admits_atom("a")
        ))
        .bind(user_id)
        .bind(graph_ids)
        .bind(hour_start)
        .bind(hour_end)
        .fetch_one(&mut **tx)
        .await?;

        Ok(JournalHourItemTotals { atoms, activity, asks })
    }

    async fn journal_hour_inputs(
        &self,
        user_id: Uuid,
        graph_id: Uuid,
        hour_start: DateTime<Utc>,
    ) -> Result<JournalHourInputs, StoreError> {
        let hour_end = hour_start + chrono::Duration::hours(1);

        type JournalAtomRow = (
            Uuid,           // atom_id
            String,         // source_type
            String,         // source_id
            Option<String>, // title
            Option<String>, // excerpt (migration 0116_atoms_excerpt)
            Option<String>, // content_inline (fallback for pre-backfill rows)
            Option<i32>,    // header_len
            DateTime<Utc>,  // timestamp
            DateTime<Utc>,  // created_at
            Option<String>, // coding_sessions.session_id (coding_session atoms only)
        );
        // Same escaped `LIKE "cc:{session_id}:%"` join
        // [`Store::journal_range_aggregate`] uses to resolve a coding-session
        // atom's actual session row — see [`JournalInputAtom::
        // coding_session_id`]'s doc comment for why this can't be recovered
        // by re-splitting `source_id` in Rust, and that method's own LATERAL
        // subquery for why `ORDER BY length(session_id) DESC LIMIT 1` is
        // required: `UNIQUE (graph_id, session_id)` does NOT prevent one
        // session id from being a literal prefix of another ("team" and
        // "team:alpha" can coexist), so the escaped-LIKE predicate can match
        // more than one `coding_sessions` row for a single atom — a plain
        // LEFT JOIN would fan that atom out into duplicate rows.
        //
        // `{sess}` is `ingest::atom::SESSION_SOURCE_TYPES_SQL_ARRAY` — see
        // the inline SQL comment below and that constant's doc comment.
        let sql = format!(
            r#"
            SELECT a.atom_id, a.source_type, a.source_id, a.title, a.excerpt, a.content_inline,
                   a.header_len, a."timestamp", a.created_at, cs.session_id
            FROM atoms a
            LEFT JOIN LATERAL (
                SELECT cs_inner.session_id
                FROM coding_sessions cs_inner
                -- Rider A (capture unit 03): `{{sess}}` is derived from
                -- `SessionKind::ALL`
                -- (`ingest::atom::SESSION_SOURCE_TYPES_SQL_ARRAY`), so
                -- this list is DERIVED, not hand-kept in lockstep, and
                -- cannot drift from `is_session_source_type`.
                WHERE a.source_type = ANY({sess})
                  AND cs_inner.graph_id = a.graph_id
                  AND a.source_id LIKE (
                          'cc:' || REPLACE(REPLACE(REPLACE(
                              cs_inner.session_id, '\', '\\'), '%', '\%'), '_', '\_')
                          || ':%'
                      )
                ORDER BY length(cs_inner.session_id) DESC
                LIMIT 1
            ) cs ON true
            WHERE a.ingested_by = $1 AND a.graph_id = $2
              AND a."timestamp" >= $3 AND a."timestamp" < $4
            ORDER BY a."timestamp" ASC
            "#,
            sess = *crate::ingest::atom::SESSION_SOURCE_TYPES_SQL_ARRAY
        );
        let atom_rows: Vec<JournalAtomRow> = sqlx::query_as(&sql)
        .bind(user_id)
        .bind(graph_id)
        .bind(hour_start)
        .bind(hour_end)
        .fetch_all(&self.pool)
        .await?;

        let atoms = atom_rows
            .into_iter()
            .map(
                |(
                    atom_id,
                    source_type,
                    source_id,
                    title,
                    excerpt,
                    content_inline,
                    header_len,
                    timestamp,
                    created_at,
                    coding_session_id,
                )| {
                    // Prefer the persisted excerpt (written at ingest time,
                    // storage-backend-independent — gap 9 / migration
                    // 0116_atoms_excerpt). Fall back to deriving it from
                    // `content_inline` for rows written before this column
                    // existed and never backfilled (the bounded migration
                    // backfill only covers headerless rows).
                    let excerpt = excerpt.or_else(|| derive_journal_excerpt(content_inline.as_deref(), header_len));
                    JournalInputAtom {
                        atom_id,
                        source_type,
                        source_id,
                        title,
                        excerpt,
                        timestamp,
                        created_at,
                        coding_session_id,
                    }
                },
            )
            .collect();

        type JournalActivityRow = (Uuid, String, Value, DateTime<Utc>);
        let activity_rows: Vec<JournalActivityRow> = sqlx::query_as(
            "SELECT id, event_type, payload, created_at \
             FROM activity_events \
             WHERE user_id = $1 AND graph_id = $2 \
               AND created_at >= $3 AND created_at < $4 \
             ORDER BY created_at ASC",
        )
        .bind(user_id)
        .bind(graph_id)
        .bind(hour_start)
        .bind(hour_end)
        .fetch_all(&self.pool)
        .await?;

        let activity = activity_rows
            .into_iter()
            .map(|(id, event_type, payload, created_at)| JournalInputActivityEvent {
                id,
                event_type,
                payload,
                created_at,
            })
            .collect();

        // The asks half — `query_history` rows this user asked in this
        // graph/hour (audit gaps #4/#5): every completed-query path funnels
        // into this one table via `routes::queries::spawn_query_history`,
        // unlike `activity_events`' `query_run` type, which only the legacy
        // non-streaming `create_query` ever emits. Same `user_id`/`graph_id`
        // equality + `created_at` window predicate the atoms/activity
        // queries above use, so `journal_dirty_hours`'s own `ask_inputs` CTE
        // (same file, below) stays in lockstep with this read.
        type JournalAskRow = (Uuid, String, i32, DateTime<Utc>);
        let ask_rows: Vec<JournalAskRow> = sqlx::query_as(
            "SELECT id, query_text, citation_count, created_at \
             FROM query_history \
             WHERE user_id = $1 AND graph_id = $2 \
               AND created_at >= $3 AND created_at < $4 \
             ORDER BY created_at ASC",
        )
        .bind(user_id)
        .bind(graph_id)
        .bind(hour_start)
        .bind(hour_end)
        .fetch_all(&self.pool)
        .await?;

        let asks = ask_rows
            .into_iter()
            .map(|(id, query_text, citation_count, created_at)| JournalInputAsk {
                id,
                query_text,
                citation_count,
                created_at,
            })
            .collect();

        Ok(JournalHourInputs { atoms, activity, asks })
    }

    async fn journal_dirty_hours(
        &self,
        lookback_from: DateTime<Utc>,
        now: DateTime<Utc>,
    ) -> Result<Vec<JournalDirtyHour>, StoreError> {
        // `AT TIME ZONE 'UTC'` (twice — the standard Postgres idiom) makes the
        // hour truncation independent of the session's `TimeZone` GUC, so
        // `hour_start` always lands on a UTC hour boundary regardless of how
        // the connection is configured — see migration `0113_journal_rollups`'s
        // header.
        //
        // Candidate hours are the UNION of `atoms`, `activity_events`, AND
        // `query_history` — mirroring `journal_hour_inputs`'s own three
        // queries exactly (same WHERE-clause semantics per table) — so a
        // change confined to any ONE of the three in an already-compiled
        // hour is detected, and an hour with rows in only one of them still
        // surfaces as a candidate. `query_history` (not `activity_events`'
        // `query_run` type) is the asks source — hourly-completeness audit
        // gaps #4/#5: the streaming web-chat path and MCP `ask_ocean` never
        // emitted `query_run`, so an ask landing only in `query_history`
        // would otherwise never re-dirty its hour.
        // [`JournalHourInputs::union_fingerprint`] re-derives this same
        // aggregate in Rust from an already-fetched `JournalHourInputs`, so
        // PR B's compile worker and this query can never silently disagree
        // about what an hour's inputs are.
        type DirtyRow = (
            Uuid,           // account_id
            Uuid,           // user_id
            Uuid,           // graph_id
            DateTime<Utc>,  // hour_start
            i64,            // input_count
            DateTime<Utc>,  // max_created_at
            Uuid,           // max_input_id (an atom_id or an activity_events.id)
            Option<String>, // existing journal_rollups.input_fingerprint, if any
            Option<i16>,    // existing journal_rollups.recompile_count, if any
            Option<DateTime<Utc>>, // existing journal_rollups.compiled_at, if any
        );

        let rows: Vec<DirtyRow> = sqlx::query_as(
            r#"
            WITH atom_inputs AS (
                SELECT
                    g.account_id AS account_id,
                    a.ingested_by AS user_id,
                    a.graph_id AS graph_id,
                    date_trunc('hour', a."timestamp" AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' AS hour_start,
                    a.created_at AS created_at,
                    a.atom_id AS input_id
                FROM atoms a
                JOIN graphs g ON g.id = a.graph_id
                WHERE a.ingested_by IS NOT NULL
                  AND a."timestamp" >= $1
                  AND a."timestamp" <  $2
            ),
            activity_inputs AS (
                -- Same WHERE-clause semantics `journal_hour_inputs` uses for
                -- `activity_events` (user_id/graph_id equality, created_at
                -- window) — `user_id`/`graph_id` are nullable on this table,
                -- and an implicit equality-bind would exclude NULLs the same
                -- way; the explicit IS NOT NULL here just keeps that true
                -- under a GROUP BY with no bound user/graph to compare
                -- against.
                SELECT
                    e.account_id AS account_id,
                    e.user_id AS user_id,
                    e.graph_id AS graph_id,
                    date_trunc('hour', e.created_at AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' AS hour_start,
                    e.created_at AS created_at,
                    e.id AS input_id
                FROM activity_events e
                WHERE e.user_id IS NOT NULL
                  AND e.graph_id IS NOT NULL
                  AND e.created_at >= $1
                  AND e.created_at <  $2
            ),
            ask_inputs AS (
                -- The "asks" half (audit gaps #4/#5): `query_history` rows,
                -- same `user_id IS NOT NULL` + `created_at` window semantics
                -- `journal_hour_inputs` uses for this table. `query_history`
                -- already carries `account_id` directly (no `graphs` join
                -- needed, unlike `atom_inputs`).
                SELECT
                    qh.account_id AS account_id,
                    qh.user_id AS user_id,
                    qh.graph_id AS graph_id,
                    date_trunc('hour', qh.created_at AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' AS hour_start,
                    qh.created_at AS created_at,
                    qh.id AS input_id
                FROM query_history qh
                WHERE qh.user_id IS NOT NULL
                  AND qh.created_at >= $1
                  AND qh.created_at <  $2
            ),
            candidate_hours AS (
                SELECT
                    account_id,
                    user_id,
                    graph_id,
                    hour_start,
                    COUNT(*) AS input_count,
                    MAX(created_at) AS max_created_at,
                    -- Postgres has no built-in MAX(uuid) aggregate; the
                    -- text round-trip is order-preserving because every
                    -- canonical UUID string has hyphens in the same fixed
                    -- positions, so comparing the hex characters position-
                    -- by-position agrees with comparing the underlying
                    -- 128-bit values.
                    MAX(input_id::text)::uuid AS max_input_id
                FROM (
                    SELECT * FROM atom_inputs
                    UNION ALL
                    SELECT * FROM activity_inputs
                    UNION ALL
                    SELECT * FROM ask_inputs
                ) all_inputs
                GROUP BY account_id, user_id, graph_id, hour_start
            )
            SELECT c.account_id, c.user_id, c.graph_id, c.hour_start,
                   c.input_count, c.max_created_at, c.max_input_id,
                   r.input_fingerprint, r.recompile_count, r.compiled_at
            FROM candidate_hours c
            -- `r.granularity = 'hour'`: ticket 15 (migration
            -- `0117_journal_tier_rollups`) reuses `hour_start` as every tier's
            -- boundary column, so without this a whole-hour-offset zone's
            -- day/week/month row (whose `hour_start` can legitimately equal
            -- some UTC hour boundary) could join here instead of — or
            -- alongside — this hour's own row, corrupting the dirty-check.
            LEFT JOIN journal_rollups r
              ON r.user_id = c.user_id AND r.graph_id = c.graph_id AND r.hour_start = c.hour_start
                 AND r.granularity = 'hour'
            "#,
        )
        .bind(lookback_from)
        .bind(now)
        .fetch_all(&self.pool)
        .await?;

        Ok(rows
            .into_iter()
            .filter_map(
                |(
                    account_id,
                    user_id,
                    graph_id,
                    hour_start,
                    input_count,
                    max_created_at,
                    max_input_id,
                    existing_fingerprint,
                    existing_recompile_count,
                    existing_compiled_at,
                )| {
                    let current_fingerprint =
                        journal_input_fingerprint(input_count, max_created_at, max_input_id);
                    if existing_fingerprint.as_deref() == Some(current_fingerprint.as_str()) {
                        None
                    } else {
                        Some(JournalDirtyHour {
                            account_id,
                            user_id,
                            graph_id,
                            hour_start,
                            current_fingerprint,
                            existing_recompile_count: existing_recompile_count.unwrap_or(0),
                            existing_compiled_at,
                        })
                    }
                },
            )
            .collect())
    }

    async fn journal_delete_stale_rollups(
        &self,
        lookback_from: DateTime<Utc>,
        now: DateTime<Utc>,
    ) -> Result<Vec<JournalStaleRollup>, StoreError> {
        // LOCKSTEP: `atom_inputs`/`activity_inputs`/`ask_inputs` here must
        // match `journal_dirty_hours`'s CTEs of the same name above exactly
        // (same WHERE-clause semantics, same hour bucketing). Aligned with
        // PR #469 (`fix-journal-asks-query-history`), which added the
        // `query_history` arm to `journal_dirty_hours`'s union — `ask_inputs`
        // below mirrors that CTE's predicate bit-for-bit (`user_id IS NOT
        // NULL`, no `graph_id IS NOT NULL` check since `query_history.graph_id`
        // is a NOT NULL column, unlike `activity_events.graph_id`).
        type StaleRow = (Uuid, Uuid, Uuid, DateTime<Utc>);

        let rows: Vec<StaleRow> = sqlx::query_as(
            r#"
            WITH atom_inputs AS (
                SELECT
                    a.ingested_by AS user_id,
                    a.graph_id AS graph_id,
                    date_trunc('hour', a."timestamp" AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' AS hour_start
                FROM atoms a
                WHERE a.ingested_by IS NOT NULL
                  AND a."timestamp" >= $1
                  AND a."timestamp" <  $2
            ),
            activity_inputs AS (
                SELECT
                    e.user_id AS user_id,
                    e.graph_id AS graph_id,
                    date_trunc('hour', e.created_at AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' AS hour_start
                FROM activity_events e
                WHERE e.user_id IS NOT NULL
                  AND e.graph_id IS NOT NULL
                  AND e.created_at >= $1
                  AND e.created_at <  $2
            ),
            ask_inputs AS (
                SELECT
                    qh.user_id AS user_id,
                    qh.graph_id AS graph_id,
                    date_trunc('hour', qh.created_at AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' AS hour_start
                FROM query_history qh
                WHERE qh.user_id IS NOT NULL
                  AND qh.created_at >= $1
                  AND qh.created_at <  $2
            ),
            live_hours AS (
                SELECT user_id, graph_id, hour_start FROM atom_inputs
                UNION ALL
                SELECT user_id, graph_id, hour_start FROM activity_inputs
                UNION ALL
                SELECT user_id, graph_id, hour_start FROM ask_inputs
            )
            DELETE FROM journal_rollups r
            WHERE r.granularity = 'hour'
              -- Ticket 15 (migration `0117_journal_tier_rollups`) reuses
              -- `hour_start` as every TIER's boundary column (day/week/month
              -- rows set it equal to their own `period_start` — see that
              -- migration's header), so an unqualified `r.hour_start`
              -- predicate here would treat a day/week/month row exactly like
              -- an hour row: `live_hours` is built entirely from `atoms`/
              -- `activity_events`/`query_history`, all bucketed to a plain
              -- UTC HOUR, so a tier row's boundary essentially never matches
              -- one of those buckets and would be deleted as "zero input" on
              -- the very next sweep pass after being compiled — this
              -- predicate is what stops that. Tier-row staleness (a day/
              -- week/month row whose children are ALL later deleted) is
              -- explicitly out of scope for ticket 15 (chained recompile
              -- handles a PARTIAL child change; total-deletion self-heal for
              -- tiers is a follow-up, same "partial self-heals, total
              -- doesn't" split gap #8 already drew for the hour tier).
              AND r.hour_start >= $1
              -- Closed hours only: the inputs union above is bounded by
              -- `< $2` (now) on event/occurred time, so a rollup for the
              -- CURRENT partial hour could look zero-input while an atom
              -- with a client-supplied timestamp later in the hour (but
              -- after `now`) still exists. A fully-closed hour's inputs all
              -- sort strictly before `now`, so the mismatch can't occur.
              AND r.hour_start <  date_trunc('hour', $2)
              AND NOT EXISTS (
                  SELECT 1 FROM live_hours lh
                  WHERE lh.user_id = r.user_id
                    AND lh.graph_id = r.graph_id
                    AND lh.hour_start = r.hour_start
              )
            RETURNING r.account_id, r.user_id, r.graph_id, r.hour_start
            "#,
        )
        .bind(lookback_from)
        .bind(now)
        .fetch_all(&self.pool)
        .await?;

        Ok(rows
            .into_iter()
            .map(|(account_id, user_id, graph_id, hour_start)| JournalStaleRollup {
                account_id,
                user_id,
                graph_id,
                hour_start,
            })
            .collect())
    }

    async fn journal_dirty_hours_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        account_id: Option<Uuid>,
        lookback_from: DateTime<Utc>,
        now: DateTime<Utc>,
    ) -> Result<Vec<JournalDirtyHour>, StoreError> {
        // Identical to `journal_dirty_hours`'s query, PLUS an explicit
        // `account_id = $3` predicate on all three arms of the union — see
        // this method's trait doc comment for why a cross-account scan like
        // this one gets the belt-and-suspenders treatment
        // `journal_hour_inputs_scoped`/`upsert_journal_rollup_scoped` don't
        // need, and why the org-tenant caller passes `None` to drop it.
        type DirtyRow = (
            Uuid,
            Uuid,
            Uuid,
            DateTime<Utc>,
            i64,
            DateTime<Utc>,
            Uuid,
            Option<String>,
            Option<i16>,
            Option<DateTime<Utc>>,
        );

        let rows: Vec<DirtyRow> = sqlx::query_as(
            r#"
            WITH atom_inputs AS (
                SELECT
                    g.account_id AS account_id,
                    a.ingested_by AS user_id,
                    a.graph_id AS graph_id,
                    date_trunc('hour', a."timestamp" AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' AS hour_start,
                    a.created_at AS created_at,
                    a.atom_id AS input_id
                FROM atoms a
                JOIN graphs g ON g.id = a.graph_id
                WHERE a.ingested_by IS NOT NULL
                  AND a."timestamp" >= $1
                  AND a."timestamp" <  $2
                  AND ($3::uuid IS NULL OR g.account_id = $3)
            ),
            activity_inputs AS (
                SELECT
                    e.account_id AS account_id,
                    e.user_id AS user_id,
                    e.graph_id AS graph_id,
                    date_trunc('hour', e.created_at AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' AS hour_start,
                    e.created_at AS created_at,
                    e.id AS input_id
                FROM activity_events e
                WHERE e.user_id IS NOT NULL
                  AND e.graph_id IS NOT NULL
                  AND e.created_at >= $1
                  AND e.created_at <  $2
                  AND ($3::uuid IS NULL OR e.account_id = $3)
            ),
            ask_inputs AS (
                -- See `journal_dirty_hours`'s identical CTE for why
                -- `query_history` (not `activity_events`' `query_run`) is
                -- the asks source (audit gaps #4/#5).
                SELECT
                    qh.account_id AS account_id,
                    qh.user_id AS user_id,
                    qh.graph_id AS graph_id,
                    date_trunc('hour', qh.created_at AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' AS hour_start,
                    qh.created_at AS created_at,
                    qh.id AS input_id
                FROM query_history qh
                WHERE qh.user_id IS NOT NULL
                  AND qh.created_at >= $1
                  AND qh.created_at <  $2
                  AND ($3::uuid IS NULL OR qh.account_id = $3)
            ),
            candidate_hours AS (
                SELECT
                    account_id,
                    user_id,
                    graph_id,
                    hour_start,
                    COUNT(*) AS input_count,
                    MAX(created_at) AS max_created_at,
                    MAX(input_id::text)::uuid AS max_input_id
                FROM (
                    SELECT * FROM atom_inputs
                    UNION ALL
                    SELECT * FROM activity_inputs
                    UNION ALL
                    SELECT * FROM ask_inputs
                ) all_inputs
                GROUP BY account_id, user_id, graph_id, hour_start
            )
            SELECT c.account_id, c.user_id, c.graph_id, c.hour_start,
                   c.input_count, c.max_created_at, c.max_input_id,
                   r.input_fingerprint, r.recompile_count, r.compiled_at
            FROM candidate_hours c
            -- `r.granularity = 'hour'`: ticket 15 (migration
            -- `0117_journal_tier_rollups`) reuses `hour_start` as every tier's
            -- boundary column, so without this a whole-hour-offset zone's
            -- day/week/month row (whose `hour_start` can legitimately equal
            -- some UTC hour boundary) could join here instead of — or
            -- alongside — this hour's own row, corrupting the dirty-check.
            LEFT JOIN journal_rollups r
              ON r.user_id = c.user_id AND r.graph_id = c.graph_id AND r.hour_start = c.hour_start
                 AND r.granularity = 'hour'
            "#,
        )
        .bind(lookback_from)
        .bind(now)
        .bind(account_id)
        .fetch_all(&mut **tx)
        .await?;

        Ok(rows
            .into_iter()
            .filter_map(
                |(
                    account_id,
                    user_id,
                    graph_id,
                    hour_start,
                    input_count,
                    max_created_at,
                    max_input_id,
                    existing_fingerprint,
                    existing_recompile_count,
                    existing_compiled_at,
                )| {
                    let current_fingerprint =
                        journal_input_fingerprint(input_count, max_created_at, max_input_id);
                    if existing_fingerprint.as_deref() == Some(current_fingerprint.as_str()) {
                        None
                    } else {
                        Some(JournalDirtyHour {
                            account_id,
                            user_id,
                            graph_id,
                            hour_start,
                            current_fingerprint,
                            existing_recompile_count: existing_recompile_count.unwrap_or(0),
                            existing_compiled_at,
                        })
                    }
                },
            )
            .collect())
    }

    async fn journal_delete_stale_rollups_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        account_id: Option<Uuid>,
        lookback_from: DateTime<Utc>,
        now: DateTime<Utc>,
    ) -> Result<Vec<JournalStaleRollup>, StoreError> {
        // LOCKSTEP: identical requirement as `journal_delete_stale_rollups`
        // (unscoped, above) — see that method's doc comment. Aligned with PR
        // #469's `ask_inputs` CTE the same way.
        type StaleRow = (Uuid, Uuid, Uuid, DateTime<Utc>);

        let rows: Vec<StaleRow> = sqlx::query_as(
            r#"
            WITH atom_inputs AS (
                SELECT
                    a.ingested_by AS user_id,
                    a.graph_id AS graph_id,
                    date_trunc('hour', a."timestamp" AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' AS hour_start
                FROM atoms a
                JOIN graphs g ON g.id = a.graph_id
                WHERE a.ingested_by IS NOT NULL
                  AND a."timestamp" >= $1
                  AND a."timestamp" <  $2
                  AND ($3::uuid IS NULL OR g.account_id = $3)
            ),
            activity_inputs AS (
                SELECT
                    e.user_id AS user_id,
                    e.graph_id AS graph_id,
                    date_trunc('hour', e.created_at AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' AS hour_start
                FROM activity_events e
                WHERE e.user_id IS NOT NULL
                  AND e.graph_id IS NOT NULL
                  AND e.created_at >= $1
                  AND e.created_at <  $2
                  AND ($3::uuid IS NULL OR e.account_id = $3)
            ),
            ask_inputs AS (
                SELECT
                    qh.user_id AS user_id,
                    qh.graph_id AS graph_id,
                    date_trunc('hour', qh.created_at AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' AS hour_start
                FROM query_history qh
                WHERE qh.user_id IS NOT NULL
                  AND qh.created_at >= $1
                  AND qh.created_at <  $2
                  AND ($3::uuid IS NULL OR qh.account_id = $3)
            ),
            live_hours AS (
                SELECT user_id, graph_id, hour_start FROM atom_inputs
                UNION ALL
                SELECT user_id, graph_id, hour_start FROM activity_inputs
                UNION ALL
                SELECT user_id, graph_id, hour_start FROM ask_inputs
            )
            DELETE FROM journal_rollups r
            WHERE ($3::uuid IS NULL OR r.account_id = $3)
              AND r.granularity = 'hour'
              -- See `journal_delete_stale_rollups`'s (unscoped, above) doc
              -- comment on this predicate — same ticket-15 `hour_start`-reuse
              -- rationale applies identically here.
              AND r.hour_start >= $1
              -- `date_trunc('hour', $2)`, NOT plain `$2` (CodeRabbit round 1):
              -- this scoped copy had drifted from the unscoped one's own
              -- `< date_trunc('hour', $2)` upper bound (see that method's
              -- "Closed hours only" comment on why — `live_hours` is bounded
              -- by `< now` on event time, so a same-hour atom timestamped
              -- later than `now` but still inside the CURRENT hour is not
              -- yet visible to the union). Without the truncation this scoped
              -- path could delete the current, still-open hour's rollup
              -- whenever the union happened to be momentarily empty at scan
              -- time — exactly the consumer-plane path that actually runs in
              -- production.
              AND r.hour_start <  date_trunc('hour', $2)
              AND NOT EXISTS (
                  SELECT 1 FROM live_hours lh
                  WHERE lh.user_id = r.user_id
                    AND lh.graph_id = r.graph_id
                    AND lh.hour_start = r.hour_start
              )
            RETURNING r.account_id, r.user_id, r.graph_id, r.hour_start
            "#,
        )
        .bind(lookback_from)
        .bind(now)
        .bind(account_id)
        .fetch_all(&mut **tx)
        .await?;

        Ok(rows
            .into_iter()
            .map(|(account_id, user_id, graph_id, hour_start)| JournalStaleRollup {
                account_id,
                user_id,
                graph_id,
                hour_start,
            })
            .collect())
    }

    async fn journal_hour_inputs_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        user_id: Uuid,
        graph_id: Uuid,
        hour_start: DateTime<Utc>,
    ) -> Result<JournalHourInputs, StoreError> {
        let hour_end = hour_start + chrono::Duration::hours(1);

        type JournalAtomRow = (
            Uuid,
            String,
            String,
            Option<String>,
            Option<String>, // excerpt (migration 0027_atoms_excerpt)
            Option<String>, // content_inline (fallback for pre-backfill rows)
            Option<i32>,
            DateTime<Utc>,
            DateTime<Utc>,
            Option<String>, // coding_sessions.session_id (coding_session atoms only)
        );
        // Same escaped `LIKE "cc:{session_id}:%"` LATERAL join as the
        // unscoped sibling above — see [`JournalInputAtom::
        // coding_session_id`]'s doc comment, and [`Store::
        // journal_range_aggregate`]'s LATERAL subquery comment for why
        // `ORDER BY length(session_id) DESC LIMIT 1` is required (a plain
        // LEFT JOIN can match — and so fan out — more than one
        // `coding_sessions` row when one session id is a literal prefix of
        // another).
        //
        // `{sess}` is `ingest::atom::SESSION_SOURCE_TYPES_SQL_ARRAY` — see
        // the inline SQL comment below and that constant's doc comment.
        let sql = format!(
            r#"
            SELECT a.atom_id, a.source_type, a.source_id, a.title, a.excerpt, a.content_inline,
                   a.header_len, a."timestamp", a.created_at, cs.session_id
            FROM atoms a
            LEFT JOIN LATERAL (
                SELECT cs_inner.session_id
                FROM coding_sessions cs_inner
                -- Rider A (capture unit 03): `{{sess}}` is derived from
                -- `SessionKind::ALL`
                -- (`ingest::atom::SESSION_SOURCE_TYPES_SQL_ARRAY`), so
                -- this list is DERIVED, not hand-kept in lockstep, and
                -- cannot drift from `is_session_source_type`.
                WHERE a.source_type = ANY({sess})
                  AND cs_inner.graph_id = a.graph_id
                  AND a.source_id LIKE (
                          'cc:' || REPLACE(REPLACE(REPLACE(
                              cs_inner.session_id, '\', '\\'), '%', '\%'), '_', '\_')
                          || ':%'
                      )
                ORDER BY length(cs_inner.session_id) DESC
                LIMIT 1
            ) cs ON true
            WHERE a.ingested_by = $1 AND a.graph_id = $2
              AND a."timestamp" >= $3 AND a."timestamp" < $4
            ORDER BY a."timestamp" ASC
            "#,
            sess = *crate::ingest::atom::SESSION_SOURCE_TYPES_SQL_ARRAY
        );
        let atom_rows: Vec<JournalAtomRow> = sqlx::query_as(&sql)
        .bind(user_id)
        .bind(graph_id)
        .bind(hour_start)
        .bind(hour_end)
        .fetch_all(&mut **tx)
        .await?;

        let atoms = atom_rows
            .into_iter()
            .map(
                |(
                    atom_id,
                    source_type,
                    source_id,
                    title,
                    excerpt,
                    content_inline,
                    header_len,
                    timestamp,
                    created_at,
                    coding_session_id,
                )| {
                    // See `journal_hour_inputs`'s twin comment above — same
                    // persisted-first, derive-as-fallback logic.
                    let excerpt = excerpt.or_else(|| derive_journal_excerpt(content_inline.as_deref(), header_len));
                    JournalInputAtom {
                        atom_id,
                        source_type,
                        source_id,
                        title,
                        excerpt,
                        timestamp,
                        created_at,
                        coding_session_id,
                    }
                },
            )
            .collect();

        type JournalActivityRow = (Uuid, String, Value, DateTime<Utc>);
        let activity_rows: Vec<JournalActivityRow> = sqlx::query_as(
            "SELECT id, event_type, payload, created_at \
             FROM activity_events \
             WHERE user_id = $1 AND graph_id = $2 \
               AND created_at >= $3 AND created_at < $4 \
             ORDER BY created_at ASC",
        )
        .bind(user_id)
        .bind(graph_id)
        .bind(hour_start)
        .bind(hour_end)
        .fetch_all(&mut **tx)
        .await?;

        let activity = activity_rows
            .into_iter()
            .map(|(id, event_type, payload, created_at)| JournalInputActivityEvent {
                id,
                event_type,
                payload,
                created_at,
            })
            .collect();

        // See `journal_hour_inputs`'s identical query for why `query_history`
        // (not `activity_events`' `query_run`) is the asks source.
        type JournalAskRow = (Uuid, String, i32, DateTime<Utc>);
        let ask_rows: Vec<JournalAskRow> = sqlx::query_as(
            "SELECT id, query_text, citation_count, created_at \
             FROM query_history \
             WHERE user_id = $1 AND graph_id = $2 \
               AND created_at >= $3 AND created_at < $4 \
             ORDER BY created_at ASC",
        )
        .bind(user_id)
        .bind(graph_id)
        .bind(hour_start)
        .bind(hour_end)
        .fetch_all(&mut **tx)
        .await?;

        let asks = ask_rows
            .into_iter()
            .map(|(id, query_text, citation_count, created_at)| JournalInputAsk {
                id,
                query_text,
                citation_count,
                created_at,
            })
            .collect();

        Ok(JournalHourInputs { atoms, activity, asks })
    }

    #[allow(clippy::too_many_arguments)]
    async fn upsert_journal_rollup_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        account_id: Uuid,
        user_id: Uuid,
        graph_id: Uuid,
        hour_start: DateTime<Utc>,
        summary: &str,
        stats: Value,
        input_fingerprint: &str,
        model: &str,
    ) -> Result<JournalRollup, StoreError> {
        let row: PgJournalRollupRow = sqlx::query_as(&format!(
            r#"
            INSERT INTO journal_rollups
                (account_id, user_id, graph_id, hour_start, period_start, granularity,
                 summary, stats, input_fingerprint, model, recompile_count, compiled_at)
            VALUES ($1, $2, $3, $4, $4, 'hour', $5, $6, $7, $8, 0, now())
            ON CONFLICT (user_id, graph_id, granularity, hour_start) DO UPDATE SET
                account_id        = EXCLUDED.account_id,
                summary           = EXCLUDED.summary,
                stats             = EXCLUDED.stats,
                input_fingerprint = EXCLUDED.input_fingerprint,
                model             = EXCLUDED.model,
                recompile_count   = journal_rollups.recompile_count + 1,
                compiled_at       = EXCLUDED.compiled_at
            RETURNING {JOURNAL_ROLLUP_COLUMNS}
            "#
        ))
        .bind(account_id)
        .bind(user_id)
        .bind(graph_id)
        .bind(hour_start)
        .bind(summary)
        .bind(stats)
        .bind(input_fingerprint)
        .bind(model)
        .fetch_one(&mut **tx)
        .await?;

        Ok(pg_journal_rollup(row))
    }

