    async fn get_caller_key_envelope_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        team_id: Uuid,
        caller_user_id: Uuid,
    ) -> Result<Option<TeamKeyEnvelope>, StoreError> {
        use sqlx::Row;
        let row = sqlx::query(
            "SELECT tk.id AS team_key_id, tmke.wrapped_key \
             FROM teams t \
             JOIN team_keys tk ON tk.graph_id = t.graph_id \
             JOIN team_member_key_envelopes tmke ON tmke.team_key_id = tk.id AND tmke.user_id = $2 \
             WHERE t.id = $1 \
             ORDER BY tk.version DESC LIMIT 1",
        )
        .bind(team_id)
        .bind(caller_user_id)
        .fetch_optional(&mut **tx)
        .await?;

        Ok(row.map(|r| TeamKeyEnvelope {
            team_key_id: r.get("team_key_id"),
            wrapped_key: r.get("wrapped_key"),
        }))
    }

