    #[allow(clippy::too_many_arguments)]
    async fn soft_remove_team_member_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        member_id: Uuid,
        team_id: Uuid,
        actor_user_id: Uuid,
        target_user_id: Uuid,
        old_role: &str,
        action: &str,
    ) -> Result<u64, StoreError> {
        let result = sqlx::query("UPDATE team_members SET departing_at = now() WHERE id = $1")
            .bind(member_id)
            .execute(&mut **tx)
            .await?;
        if result.rows_affected() > 0 {
            sqlx::query(
                "INSERT INTO membership_events (team_id, actor_user_id, target_user_id, action, old_role, new_role) \
                 VALUES ($1, $2, $3, $4, $5, NULL)",
            )
            .bind(team_id)
            .bind(actor_user_id)
            .bind(target_user_id)
            .bind(action)
            .bind(old_role)
            .execute(&mut **tx)
            .await?;
        }
        Ok(result.rows_affected())
    }

    #[allow(clippy::too_many_arguments)]
    async fn update_team_member_role_tx_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        team_id: Uuid,
        member_id: Uuid,
        target_user_id: Uuid,
        actor_user_id: Uuid,
        old_role: &str,
        new_role: &str,
    ) -> Result<u64, StoreError> {
        let result = sqlx::query("UPDATE team_members SET role = $1 WHERE id = $2")
            .bind(new_role)
            .bind(member_id)
            .execute(&mut **tx)
            .await?;
        // Same "audit only real mutations" guard as the unscoped method
        // above and as `soft_remove_team_member_scoped` — a stale/already-
        // departed `member_id` must not fabricate a `role_changed` row.
        if result.rows_affected() > 0 {
            sqlx::query(
                "INSERT INTO membership_events (team_id, actor_user_id, target_user_id, action, old_role, new_role) \
                 VALUES ($1, $2, $3, 'role_changed', $4, $5)",
            )
            .bind(team_id)
            .bind(actor_user_id)
            .bind(target_user_id)
            .bind(old_role)
            .bind(new_role)
            .execute(&mut **tx)
            .await?;
        }
        Ok(result.rows_affected())
    }

