    async fn rename_team_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        team_id: Uuid,
        new_name: &str,
        actor_user_id: Uuid,
    ) -> Result<u64, StoreError> {
        // See the unscoped sibling's comments — same no-op-on-unchanged-name
        // and `graphs.name`-tracking rationale.
        let result = sqlx::query("UPDATE teams SET name = $2 WHERE id = $1 AND name <> $2")
            .bind(team_id)
            .bind(new_name)
            .execute(&mut **tx)
            .await?;
        if result.rows_affected() > 0 {
            let graphs_result = sqlx::query(
                "UPDATE graphs SET name = $2 \
                 WHERE id = (SELECT graph_id FROM teams WHERE id = $1)",
            )
            .bind(team_id)
            .bind(new_name)
            .execute(&mut **tx)
            .await?;
            // See the unscoped sibling's identical check just above in this
            // file for the full rationale: a zero-row `graphs` companion
            // update here would otherwise silently commit (the CALLER owns
            // this `tx` and decides when to commit it, via
            // `commit_write_tx!` in `routes::teams::rename_team`) with
            // `teams.name` already changed and `graphs.name` left behind.
            // Returning `Err` here propagates out of `scoped_store!` in the
            // route handler, which never reaches its own `commit_write_tx!`
            // call — so the half-rename never lands.
            if graphs_result.rows_affected() == 0 {
                return Err(StoreError::Db(Box::from(format!(
                    "rename_team_scoped: teams row {team_id} was renamed but its graphs \
                     companion row was not found (missing/dangling graph_id) — \
                     refusing to commit a half-rename"
                ))));
            }

            sqlx::query(
                "INSERT INTO membership_events (team_id, actor_user_id, target_user_id, action, old_role, new_role) \
                 VALUES ($1, $2, $2, 'renamed', NULL, NULL)",
            )
            .bind(team_id)
            .bind(actor_user_id)
            .execute(&mut **tx)
            .await?;
        }
        Ok(result.rows_affected())
    }

    async fn archive_team_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        team_id: Uuid,
        actor_user_id: Uuid,
    ) -> Result<u64, StoreError> {
        // See the unscoped sibling's comment — same idempotent-on-already-
        // archived shape.
        let result = sqlx::query(
            "UPDATE graphs SET archived_at = now() \
             WHERE id = (SELECT graph_id FROM teams WHERE id = $1) AND archived_at IS NULL",
        )
        .bind(team_id)
        .execute(&mut **tx)
        .await?;
        if result.rows_affected() > 0 {
            sqlx::query(
                "INSERT INTO membership_events (team_id, actor_user_id, target_user_id, action, old_role, new_role) \
                 VALUES ($1, $2, $2, 'archived', NULL, NULL)",
            )
            .bind(team_id)
            .bind(actor_user_id)
            .execute(&mut **tx)
            .await?;
        }
        Ok(result.rows_affected())
    }

    async fn restore_team_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        team_id: Uuid,
        actor_user_id: Uuid,
    ) -> Result<u64, StoreError> {
        // See `archive_team_scoped`'s comment — same idempotent shape,
        // inverted.
        let result = sqlx::query(
            "UPDATE graphs SET archived_at = NULL \
             WHERE id = (SELECT graph_id FROM teams WHERE id = $1) AND archived_at IS NOT NULL",
        )
        .bind(team_id)
        .execute(&mut **tx)
        .await?;
        if result.rows_affected() > 0 {
            sqlx::query(
                "INSERT INTO membership_events (team_id, actor_user_id, target_user_id, action, old_role, new_role) \
                 VALUES ($1, $2, $2, 'restored', NULL, NULL)",
            )
            .bind(team_id)
            .bind(actor_user_id)
            .execute(&mut **tx)
            .await?;
        }
        Ok(result.rows_affected())
    }

