    async fn add_team_member_tx_no_envelope_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        team_id: Uuid,
        new_user_id: Uuid,
        role: &str,
        actor_user_id: Uuid,
    ) -> Result<AddedTeamMember, StoreError> {
        // No `team_member_key_envelopes` row — see the trait doc comment
        // (design doc #3): the org team key was already wrapped once, under
        // the org account DEK, at `create_team` time. This is a pure
        // roster insert.
        let member_id: Uuid = sqlx::query_scalar(
            "INSERT INTO team_members (team_id, user_id, role) VALUES ($1, $2, $3) RETURNING id",
        )
        .bind(team_id)
        .bind(new_user_id)
        .bind(role)
        .fetch_one(&mut **tx)
        .await?;

        sqlx::query(
            "INSERT INTO membership_events (team_id, actor_user_id, target_user_id, action, old_role, new_role) \
             VALUES ($1, $2, $3, 'added', NULL, $4)",
        )
        .bind(team_id)
        .bind(actor_user_id)
        .bind(new_user_id)
        .bind(role)
        .execute(&mut **tx)
        .await?;

        Ok(AddedTeamMember { member_id })
    }

    async fn create_team_tx_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        account_id: Uuid,
        user_id: Uuid,
        name: &str,
        wrapped_for_creator: &[u8],
    ) -> Result<CreatedTeam, StoreError> {
        // Ids are minted HERE rather than read back with `RETURNING`, and that
        // is load-bearing under tenant RLS, not a style choice: `INSERT ...
        // RETURNING` applies the table's SELECT policy to the returned row, and
        // none of these three rows is selectable yet — a team ocean becomes
        // visible only once its `team_members` row exists, which is the last
        // insert below. With `RETURNING` the very first statement fails, with
        // the same "new row violates row-level security policy" text and the
        // same SQLSTATE 42501 a genuine `WITH CHECK` refusal raises. See
        // `migrations_tenant/0040_team_create_bootstrap_rls.sql`, "the
        // RETURNING trap". Client-minted v4 uuids also keep 0040's bootstrap
        // grant INSERT-only — had `RETURNING` stayed, it would have needed a
        // SELECT arm, which is the widening that design exists to refuse.
        let graph_id = Uuid::new_v4();
        let team_id = Uuid::new_v4();
        let team_key_id = Uuid::new_v4();

        sqlx::query(
            "INSERT INTO graphs (id, account_id, name, kind) VALUES ($1, $2, $3, 'team')",
        )
        .bind(graph_id)
        .bind(account_id)
        .bind(name)
        .execute(&mut **tx)
        .await?;

        // Only now — the resolver checks `kind = 'team'`, so the row must
        // exist. Everything below this line is what the grant covers.
        crate::tenancy::scope::set_team_bootstrap_graph(tx, graph_id).await?;

        sqlx::query(
            "INSERT INTO teams (id, account_id, graph_id, name, created_by) VALUES ($1, $2, $3, $4, $5)",
        )
        .bind(team_id)
        .bind(account_id)
        .bind(graph_id)
        .bind(name)
        .bind(user_id)
        .execute(&mut **tx)
        .await?;

        sqlx::query(
            "INSERT INTO team_keys (id, graph_id, version, created_by) VALUES ($1, $2, 1, $3)",
        )
        .bind(team_key_id)
        .bind(graph_id)
        .bind(user_id)
        .execute(&mut **tx)
        .await?;

        sqlx::query(
            "INSERT INTO team_member_key_envelopes (team_key_id, user_id, wrapped_key) VALUES ($1, $2, $3)",
        )
        .bind(team_key_id)
        .bind(user_id)
        .bind(wrapped_for_creator)
        .execute(&mut **tx)
        .await?;

        sqlx::query("INSERT INTO team_members (team_id, user_id, role) VALUES ($1, $2, 'admin')")
            .bind(team_id)
            .bind(user_id)
            .execute(&mut **tx)
            .await?;

        // Audit (design doc #7) — see the unscoped sibling's doc comment.
        sqlx::query(
            "INSERT INTO membership_events (team_id, actor_user_id, target_user_id, action, old_role, new_role) \
             VALUES ($1, $2, $2, 'created', NULL, 'admin')",
        )
        .bind(team_id)
        .bind(user_id)
        .execute(&mut **tx)
        .await?;

        Ok(CreatedTeam { team_id, graph_id })
    }

    #[allow(clippy::too_many_arguments)]
    async fn add_team_member_tx_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        team_id: Uuid,
        team_key_id: Uuid,
        new_user_id: Uuid,
        role: &str,
        wrapped_for_new_member: &[u8],
        actor_user_id: Uuid,
    ) -> Result<AddedTeamMember, StoreError> {
        sqlx::query(
            "INSERT INTO team_member_key_envelopes (team_key_id, user_id, wrapped_key) VALUES ($1, $2, $3)",
        )
        .bind(team_key_id)
        .bind(new_user_id)
        .bind(wrapped_for_new_member)
        .execute(&mut **tx)
        .await?;

        let member_id: Uuid = sqlx::query_scalar(
            "INSERT INTO team_members (team_id, user_id, role) VALUES ($1, $2, $3) RETURNING id",
        )
        .bind(team_id)
        .bind(new_user_id)
        .bind(role)
        .fetch_one(&mut **tx)
        .await?;

        // Audit (design doc #7) — see the unscoped sibling's doc comment.
        sqlx::query(
            "INSERT INTO membership_events (team_id, actor_user_id, target_user_id, action, old_role, new_role) \
             VALUES ($1, $2, $3, 'added', NULL, $4)",
        )
        .bind(team_id)
        .bind(actor_user_id)
        .bind(new_user_id)
        .bind(role)
        .execute(&mut **tx)
        .await?;

        Ok(AddedTeamMember { member_id })
    }

    async fn node_atom_ids_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        node_id: Uuid,
    ) -> Result<Vec<Uuid>, StoreError> {
        let ids: Vec<Uuid> =
            sqlx::query_scalar("SELECT atom_id FROM node_atoms WHERE node_id = $1")
                .bind(node_id)
                .fetch_all(&mut **tx)
                .await?;

        Ok(ids)
    }

    async fn node_ids_for_atoms_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        graph_id: Uuid,
        atom_ids: &[Uuid],
    ) -> Result<Vec<Uuid>, StoreError> {
        if atom_ids.is_empty() {
            return Ok(Vec::new());
        }
        // The `n.graph_id = $2` join keeps anchoring inside the target ocean — a
        // tenant boundary, so foreign atom ids can never resolve another
        // account's reefs.
        let ids: Vec<Uuid> = sqlx::query_scalar(
            "SELECT DISTINCT na.node_id \
             FROM   node_atoms na \
             JOIN   nodes n ON n.node_id = na.node_id \
             WHERE  na.atom_id = ANY($1) AND n.graph_id = $2",
        )
        .bind(atom_ids)
        .bind(graph_id)
        .fetch_all(&mut **tx)
        .await?;

        Ok(ids)
    }

    async fn list_meeting_merges_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        graph_id: Uuid,
        source_id: &str,
    ) -> Result<Vec<MeetingMerge>, StoreError> {
        // Link merges to this meeting via the kept reef: keep_id must be linked to
        // an atom whose source_id is one of this meeting's chunk atoms (prefix).
        type Row = (Uuid, Uuid, String, String, DateTime<Utc>);
        let rows: Vec<Row> = sqlx::query_as(&format!(
            "SELECT m.merge_id, m.keep_id, n.title, \
                    COALESCE(m.dup_snapshot->>'title', ''), m.created_at \
             FROM node_merges m \
             JOIN nodes n ON n.node_id = m.keep_id \
             WHERE m.graph_id = $1 \
               AND m.undone_at IS NULL \
               AND EXISTS ( \
                   SELECT 1 FROM node_atoms na \
                   JOIN atoms a ON a.atom_id = na.atom_id \
                   WHERE na.node_id = m.keep_id \
                     AND a.graph_id = $1 \
                     AND a.source_id LIKE $2 \
                     AND {floor} \
               ) \
             ORDER BY m.created_at ASC \
             LIMIT {cap}",
            cap = MEETING_DETAIL_CAP + 1,
            floor = crate::history_floor::admits_atom("a")
        ))
        .bind(graph_id)
        .bind(like_prefix(source_id))
        .fetch_all(&mut **tx)
        .await?;
        Ok(rows
            .into_iter()
            .map(
                |(merge_id, kept_node_id, kept_title, merged_title, created_at)| MeetingMerge {
                    merge_id,
                    kept_node_id,
                    kept_title,
                    merged_title,
                    created_at,
                },
            )
            .collect())
    }

