    async fn keyword_search_node_atoms_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        graph_id: Uuid,
        query: &str,
        k: usize,
        filter: &RetrievalFilter,
    ) -> Result<Vec<(Uuid, f64)>, StoreError> {
        use sqlx::Row;

        // See the unscoped `keyword_search_node_atoms` / `qualified_reef_ids_pg`
        // for the full rationale (§5.6, D8, and the full-title-match escape
        // hatch's own extensive rationale comment there) — identical query,
        // run against the caller's transaction.
        let selected = qualified_reef_ids_pg(&mut **tx, graph_id, query, k, filter).await?;
        if selected.is_empty() {
            return Ok(vec![]);
        }

        // `JOIN atoms`, not a bare `node_atoms` read (m365 enterprise train
        // PR 4.1). This is a LIVE retrieval candidate source
        // (`routes::queries::scoped_keyword_search_node_atoms`, merged
        // straight into `keyword_hits`), so a matched node's atom_ids
        // leaking here would both (a) surface pre-window content once
        // downstream content-fetch closed the actual leak, contributing
        // nothing but noise, and (b) worse, crowd out real in-window
        // candidates against `RETRIEVAL_CANDIDATE_K`/`NODE_CANDIDATE_K` —
        // exactly the silent-under-return failure class contract test #6
        // exists to catch, just for the node-search entry point instead of
        // the vector/keyword ANN one. The inner join restricts to atoms the
        // caller can actually see (RLS-enforced by migration
        // `0064_team_seat_grants_history_from`'s windowed `atoms` SELECT
        // policy) — a node whose ENTIRE atom set is pre-window now correctly
        // contributes zero atoms here, same as if it were never matched.
        let ids: Vec<Uuid> = selected.iter().map(|(id, _)| *id).collect();
        let atom_rows = sqlx::query(reef_lexical::PERMITTED_MEMBERS_SQL)
            .bind(&ids).bind(graph_id)
            .bind(crate::retrieval::node_query_tokens(query).join(" | ")).fetch_all(&mut **tx).await?;

        let mut atoms_by_node: std::collections::HashMap<Uuid, Vec<Uuid>> =
            std::collections::HashMap::new();
        for row in atom_rows {
            let node_id: Uuid = row.get("node_id");
            let atom_id: Uuid = row.get("atom_id");
            atoms_by_node.entry(node_id).or_default().push(atom_id);
        }

        Ok(flatten_reef_atoms(selected, atoms_by_node))
    }

