    async fn list_supersession_edges_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        node_id: Uuid,
        graph_id: Uuid,
    ) -> Result<Vec<SupersessionEdgeRow>, StoreError> {
        let rows: Vec<SupersessionEdgeRow> = sqlx::query_as(
            r#"
            SELECT se.superseder_id,
                   se.superseded_id,
                   n1.title AS superseder_title,
                   n2.title AS superseded_title
            FROM supersession_edge se
            JOIN nodes n1 ON n1.node_id = se.superseder_id
            JOIN nodes n2 ON n2.node_id = se.superseded_id
            WHERE se.graph_id = $2
              AND n1.graph_id = $2
              AND n2.graph_id = $2
              AND (se.superseder_id = $1 OR se.superseded_id = $1)
            "#,
        )
        .bind(node_id)
        .bind(graph_id)
        .fetch_all(&mut **tx)
        .await?;

        Ok(rows)
    }

    async fn list_supersession_targets_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        node_ids: &[Uuid],
    ) -> Result<Vec<SupersessionTarget>, StoreError> {
        if node_ids.is_empty() {
            return Ok(Vec::new());
        }
        // §3.6 widening — see the unscoped sibling's comment for the rationale.
        let rows: Vec<(Uuid, Uuid, String, DateTime<Utc>)> = sqlx::query_as(
            r#"
            SELECT se.superseded_id, se.superseder_id, se.kind, n.created_at
            FROM supersession_edge se
            JOIN nodes n ON n.node_id = se.superseder_id
            WHERE se.superseded_id = ANY($1)
            "#,
        )
        .bind(node_ids)
        .fetch_all(&mut **tx)
        .await?;

        Ok(rows
            .into_iter()
            .map(|(superseded_id, superseder_id, kind, superseded_on)| SupersessionTarget {
                superseded_id,
                superseder_id,
                kind: SupersessionKind::parse(&kind).unwrap_or_default(),
                superseded_on: Some(superseded_on),
            })
            .collect())
    }

    async fn is_non_supersession_pair_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        node_a: Uuid,
        node_b: Uuid,
    ) -> Result<bool, StoreError> {
        let exists: Option<bool> = sqlx::query_scalar(
            r#"
            SELECT true
            FROM non_supersession_pair
            WHERE node_a_id = LEAST($1, $2)
              AND node_b_id = GREATEST($1, $2)
            "#,
        )
        .bind(node_a)
        .bind(node_b)
        .fetch_optional(&mut **tx)
        .await?;

        Ok(exists.is_some())
    }

    async fn mark_non_supersession_pair_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        node_a: Uuid,
        node_b: Uuid,
        marked_by: Option<Uuid>,
    ) -> Result<(), StoreError> {
        let (a, b, marked_at): (Uuid, Uuid, DateTime<Utc>) = sqlx::query_as(
            r#"
            INSERT INTO non_supersession_pair (node_a_id, node_b_id, marked_by)
            VALUES (LEAST($1, $2), GREATEST($1, $2), $3)
            ON CONFLICT (node_a_id, node_b_id) DO UPDATE
                SET node_a_id = non_supersession_pair.node_a_id
            RETURNING node_a_id, node_b_id, marked_at
            "#,
        )
        .bind(node_a)
        .bind(node_b)
        .bind(marked_by)
        .fetch_one(&mut **tx)
        .await?;

        let graph_id: Option<Uuid> =
            sqlx::query_scalar("SELECT graph_id FROM nodes WHERE node_id = $1")
                .bind(a)
                .fetch_optional(&mut **tx)
                .await?;

        if let Some(gid) = graph_id {
            let op = sync::non_supersession_pair_op(
                Uuid::new_v4(),
                a,
                b,
                gid,
                marked_by,
                marked_at,
                self.device_id(),
            );
            append_op_tx(&mut *tx, &op).await?;
        }

        Ok(())
    }

    async fn is_conflict_dismissed_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        node_a: Uuid,
        node_b: Uuid,
        prompt_version: &str,
    ) -> Result<bool, StoreError> {
        let exists: Option<bool> = sqlx::query_scalar(
            r#"
            SELECT true
            FROM conflict_dismissal
            WHERE node_a_id = LEAST($1, $2)
              AND node_b_id = GREATEST($1, $2)
              AND prompt_version = $3
              AND (expires_at IS NULL OR expires_at > now())
            "#,
        )
        .bind(node_a)
        .bind(node_b)
        .bind(prompt_version)
        .fetch_optional(&mut **tx)
        .await?;

        Ok(exists.is_some())
    }

    async fn mark_conflict_dismissal_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        node_a: Uuid,
        node_b: Uuid,
        verdict: ConflictDismissalVerdict,
        model: &str,
        prompt_version: &str,
        confidence: f64,
    ) -> Result<(), StoreError> {
        let now = Utc::now();
        let expires_at = conflict_dismissal_expires_at(verdict, now);
        sqlx::query(
            r#"
            INSERT INTO conflict_dismissal
                (node_a_id, node_b_id, verdict, model, prompt_version, confidence, dismissed_at, expires_at)
            VALUES (LEAST($1, $2), GREATEST($1, $2), $3, $4, $5, $6, $7, $8)
            ON CONFLICT (node_a_id, node_b_id) DO UPDATE SET
                verdict = EXCLUDED.verdict,
                model = EXCLUDED.model,
                prompt_version = EXCLUDED.prompt_version,
                confidence = EXCLUDED.confidence,
                dismissed_at = EXCLUDED.dismissed_at,
                expires_at = EXCLUDED.expires_at
            "#,
        )
        .bind(node_a)
        .bind(node_b)
        .bind(verdict.as_str())
        .bind(model)
        .bind(prompt_version)
        .bind(confidence)
        .bind(now)
        .bind(expires_at)
        .execute(&mut **tx)
        .await?;

        Ok(())
    }

    async fn upsert_relationship_edge_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        graph_id: Uuid,
        src_node_id: Uuid,
        predicate: &str,
        dst_node_id: Uuid,
        origin: EdgeOrigin,
        status: EdgeStatus,
        confidence: f32,
        provenance: Value,
    ) -> Result<RelationshipEdge, StoreError> {
        let edge = relationship_provenance::upsert_pg(
            tx,
            graph_id,
            src_node_id,
            predicate,
            dst_node_id,
            origin,
            status,
            confidence,
            provenance,
        )
        .await?;

        let op = sync::relationship_edge_op(
            Uuid::new_v4(),
            edge.edge_id,
            edge.graph_id,
            edge.src_node_id,
            &edge.predicate,
            edge.dst_node_id,
            edge.origin.as_str(),
            edge.status.as_str(),
            edge.confidence,
            &edge.provenance,
            edge.created_at,
            edge.updated_at,
            edge.version,
            self.device_id(),
        );
        append_op_tx(&mut *tx, &op).await?;

        Ok(edge)
    }

    async fn list_relationship_edges_for_nodes_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        graph_id: Uuid,
        node_ids: &[Uuid],
    ) -> Result<Vec<RelationshipEdge>, StoreError> {
        if node_ids.is_empty() {
            return Ok(Vec::new());
        }
        // `LIMIT` (dogfooding gap-sweep #2, item 8, 2026-07-18): `get_reef`
        // calls this with a single node's id as the frontier, and a hub node
        // (one with an unusually large fan-out of edges) could otherwise
        // force fetching every one of its edges before the caller's own
        // downstream cap (`REEF_RELATIONSHIP_CAP` = 40) truncates the
        // response. Pushing a generous cap into the SQL bounds that
        // worst case without changing behavior for any normal node.
        let rows: Vec<RelationshipEdgeRow> = sqlx::query_as(
            r#"
            SELECT edge_id, graph_id, src_node_id, predicate, dst_node_id,
                   origin, status, confidence, provenance,
                   created_at, updated_at, version
            FROM relationship_edge
            WHERE graph_id = $1
              AND (src_node_id = ANY($2) OR dst_node_id = ANY($2))
              AND predicate <> 'co_occurs_with'
            LIMIT 500
            "#,
        )
        .bind(graph_id)
        .bind(node_ids)
        .fetch_all(&mut **tx)
        .await?;

        Ok(rows.into_iter().map(relationship_edge_from_row).collect())
    }

