    async fn set_relationship_edge_status_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        edge_id: Uuid,
        status: EdgeStatus,
        reviewed_by: Option<Uuid>,
        via: &str,
    ) -> Result<(), StoreError> {
        let row: Option<RelationshipEdgeRow> = sqlx::query_as(
            r#"
            UPDATE relationship_edge
               SET status     = $2,
                   -- Human decision: strip machine auto_* flags (upgrading a
                   -- machine-confirmed edge to durable, per the upsert's
                   -- sticky CASE) and stamp who resolved it, when, and via
                   -- which surface — the review-conversion metric's raw data.
                   provenance = (provenance - 'auto_confirmed' - 'auto_resolved'
                                            - 'auto_resolution' - 'auto_resolved_at' - 'lifecycle' - 'human_review_status')
                                || jsonb_build_object(
                                       'reviewed_by', $3::uuid,
                                       'reviewed_at', now(),
                                       'via', $4::text),
                   updated_at = now(),
                   version    = version + 1
             WHERE edge_id = $1
            RETURNING edge_id, graph_id, src_node_id, predicate, dst_node_id,
                      origin, status, confidence, provenance,
                      created_at, updated_at, version
            "#,
        )
        .bind(edge_id)
        .bind(status.as_str())
        .bind(reviewed_by)
        .bind(via)
        .fetch_optional(&mut **tx)
        .await?;

        if let Some(row) = row {
            let edge = relationship_edge_from_row(row);
            let op = sync::relationship_edge_op(
                Uuid::new_v4(),
                edge.edge_id,
                edge.graph_id,
                edge.src_node_id,
                &edge.predicate,
                edge.dst_node_id,
                edge.origin.as_str(),
                edge.status.as_str(),
                edge.confidence,
                &edge.provenance,
                edge.created_at,
                edge.updated_at,
                edge.version,
                self.device_id(),
            );
            append_op_tx(&mut *tx, &op).await?;

            // Apply the SAME review decision to the materialized inverse edge so
            // a confirm/reject covers the whole relationship — otherwise a
            // rejected claim would leak back through its reverse direction.
            // Predicates that no longer materialize new inverses may still
            // have legacy reverse rows. Review those too; absent inverses are
            // a no-op, and this never creates a new relationship.
            if let Some(inv) = predicates::inverse(&edge.predicate) {
                let inv_row: Option<RelationshipEdgeRow> = sqlx::query_as(
                    r#"
                    UPDATE relationship_edge
                       SET status     = $5,
                           provenance = (provenance - 'auto_confirmed' - 'auto_resolved'
                                                    - 'auto_resolution' - 'auto_resolved_at' - 'lifecycle' - 'human_review_status')
                                        || jsonb_build_object(
                                               'reviewed_by', $6::uuid,
                                               'reviewed_at', now(),
                                               'via', $7::text),
                           updated_at = now(),
                           version    = version + 1
                     WHERE graph_id = $1
                       AND src_node_id = $2
                       AND predicate   = $3
                       AND dst_node_id = $4
                    RETURNING edge_id, graph_id, src_node_id, predicate, dst_node_id,
                              origin, status, confidence, provenance,
                              created_at, updated_at, version
                    "#,
                )
                .bind(edge.graph_id)
                .bind(edge.dst_node_id) // inverse src = forward dst
                .bind(inv)
                .bind(edge.src_node_id) // inverse dst = forward src
                .bind(status.as_str())
                .bind(reviewed_by)
                .bind(via)
                .fetch_optional(&mut **tx)
                .await?;
                if let Some(inv_row) = inv_row {
                    let inv_edge = relationship_edge_from_row(inv_row);
                    let inv_op = sync::relationship_edge_op(
                        Uuid::new_v4(),
                        inv_edge.edge_id,
                        inv_edge.graph_id,
                        inv_edge.src_node_id,
                        &inv_edge.predicate,
                        inv_edge.dst_node_id,
                        inv_edge.origin.as_str(),
                        inv_edge.status.as_str(),
                        inv_edge.confidence,
                        &inv_edge.provenance,
                        inv_edge.created_at,
                        inv_edge.updated_at,
                        inv_edge.version,
                        self.device_id(),
                    );
                    append_op_tx(&mut *tx, &inv_op).await?;
                }
            }
        }

        Ok(())
    }

    async fn append_op_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        op: &NewOp,
    ) -> Result<i64, StoreError> {
        let seq: i64 = sqlx::query_scalar(
            "INSERT INTO op_log \
                 (op_id, entity, entity_id, op_type, payload, version, updated_at, device_id, graph_id) \
             VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9) \
             RETURNING seq",
        )
        .bind(op.op_id)
        .bind(&op.entity)
        .bind(&op.entity_id)
        .bind(op.op_type.as_str())
        .bind(&op.payload)
        .bind(op.version)
        .bind(op.updated_at)
        .bind(&op.device_id)
        .bind(op.graph_id)
        .fetch_one(&mut **tx)
        .await?;
        Ok(seq)
    }

    /// Consumer-plane (RLS-scoped) sibling of [`PostgresStore::
    /// purge_expired_tombstones`] above — same FM-1 fix, same
    /// current-op-only scoping (see that method's doc comment for the full
    /// "deterministic entity_id can be recycled by a relink/recreate"
    /// reasoning this predicate protects against): only purges an identity
    /// whose stale tombstone is ALSO its highest-`seq` (i.e. current) op.
    /// Same [`TOMBSTONE_PURGE_BATCH_LIMIT`] bound too (finding 11).
    async fn purge_expired_tombstones_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        cutoff: DateTime<Utc>,
    ) -> Result<u64, StoreError> {
        let result = sqlx::query(
            "DELETE FROM op_log \
             WHERE (entity, entity_id) IN ( \
                 SELECT st.entity, st.entity_id \
                 FROM op_log st \
                 WHERE st.op_type = 'delete' AND st.updated_at < $1 \
                   AND NOT EXISTS ( \
                       SELECT 1 FROM op_log newer \
                       WHERE newer.entity = st.entity \
                         AND newer.entity_id = st.entity_id \
                         AND newer.seq > st.seq \
                   ) \
                 LIMIT $2 \
             )",
        )
            .bind(cutoff)
            .bind(TOMBSTONE_PURGE_BATCH_LIMIT)
            .execute(&mut **tx)
            .await?;
        Ok(result.rows_affected())
    }

    async fn upsert_coding_session_scoped(
        &self,
        tx: &mut sqlx::Transaction<'_, sqlx::Postgres>,
        graph_id: Uuid,
        session_id: &str,
        session_kind: &str,
        project_key: Option<&str>,
        title: Option<&str>,
        repo_path: Option<&str>,
        remote_sanitized: Option<&str>,
        hostname: Option<&str>,
        harness_version: Option<&str>,
        model: Option<&str>,
        branch: Option<&str>,
        identity: &SessionIdentity,
    ) -> Result<String, StoreError> {
        // ── `projects` alias-table lazy upsert (audit P1-4) — must land
        // before/alongside the first time this key is ever stamped, in the
        // SAME transaction so a crash between the two never leaves a
        // `coding_sessions.project_key` with no matching `projects` row.
        // `ON CONFLICT DO NOTHING`: first-write-wins on `display_name` so a
        // later manual rename is never clobbered by a subsequent ingest.
        if let Some(key) = project_key {
            sqlx::query(
                "INSERT INTO projects (graph_id, project_key, display_name) \
                 VALUES ($1, $2, $2) \
                 ON CONFLICT (graph_id, project_key) DO NOTHING",
            )
            .bind(graph_id)
            .bind(key)
            .execute(&mut **tx)
            .await?;
        }

        // Single-statement atomic upsert, SQL shared with the unscoped
        // method: see `coding_session_upsert_pg`.
        coding_session_upsert_pg(
            &mut **tx,
            graph_id,
            session_id,
            session_kind,
            project_key,
            title,
            repo_path,
            remote_sanitized,
            hostname,
            harness_version,
            model,
            branch,
            identity,
        )
        .await
    }

