#[cfg(test)]
mod header_strip_tests {
    use super::strip_header_prefix;

    #[test]
    fn strips_header_and_separator() {
        let content = "Meeting: Standup, 2026-07-15.\n\nAlice: good morning";
        let header_len = "Meeting: Standup, 2026-07-15.".len() as i32 + 2;
        assert_eq!(strip_header_prefix(content, header_len), "Alice: good morning");
    }

    #[test]
    fn zero_header_len_is_a_no_op() {
        let content = "just plain content, no header";
        assert_eq!(strip_header_prefix(content, 0), content);
    }

    #[test]
    fn negative_header_len_is_a_no_op() {
        let content = "just plain content, no header";
        assert_eq!(strip_header_prefix(content, -1), content);
    }

    #[test]
    fn header_len_at_or_past_content_end_falls_back_to_full_string() {
        let content = "short";
        assert_eq!(strip_header_prefix(content, content.len() as i32), content);
        assert_eq!(strip_header_prefix(content, 999), content);
    }

    #[test]
    fn header_len_off_char_boundary_falls_back_to_full_string() {
        // "é" is 2 UTF-8 bytes; header_len=1 lands mid-character.
        let content = "éxyz";
        assert_eq!(strip_header_prefix(content, 1), content);
    }

    #[test]
    fn strips_multibyte_header_correctly() {
        let header = "Meeting: Café Sync, 2026-07-15.";
        let content = format!("{header}\n\nbody text");
        let header_len = header.len() as i32 + 2;
        assert_eq!(strip_header_prefix(&content, header_len), "body text");
    }
}

/// [`derive_journal_excerpt`] — the shared strip-then-truncate function gap
/// 9's fix factored out so the write path (`routes::ingest`, at insert time)
/// and the read path (`journal_hour_inputs`/`_scoped`, as the pre-migration
/// fallback) can never disagree on what an excerpt is.
#[cfg(test)]
mod derive_journal_excerpt_tests {
    use super::{derive_journal_excerpt, JOURNAL_EXCERPT_MAX_CHARS};

    #[test]
    fn none_content_yields_none() {
        assert_eq!(derive_journal_excerpt(None, None), None);
    }

    #[test]
    fn empty_content_yields_none() {
        assert_eq!(derive_journal_excerpt(Some("   \n  "), None), None);
    }

    #[test]
    fn strips_header_before_truncating() {
        let header = "Session: sess-1. Repo: coralswarm.";
        let content = format!("{header}\n\nActual body content here.");
        let header_len = header.len() as i32 + 2;
        assert_eq!(
            derive_journal_excerpt(Some(&content), Some(header_len)),
            Some("Actual body content here.".to_string())
        );
    }

    #[test]
    fn header_only_capture_yields_none() {
        // The header accounts for the entire string — nothing left to excerpt.
        let header = "Session: sess-1. Repo: coralswarm.";
        let header_len = header.len() as i32;
        assert_eq!(derive_journal_excerpt(Some(header), Some(header_len)), None);
    }

    #[test]
    fn no_header_len_uses_whole_string() {
        assert_eq!(
            derive_journal_excerpt(Some("plain body, no header"), None),
            Some("plain body, no header".to_string())
        );
    }

    #[test]
    fn truncates_long_bodies_with_an_ellipsis() {
        let long_body = "x".repeat(400);
        let excerpt = derive_journal_excerpt(Some(&long_body), None).expect("long body must produce an excerpt");
        assert_eq!(
            excerpt.chars().count(),
            JOURNAL_EXCERPT_MAX_CHARS + 1,
            "280 kept chars + one ellipsis char"
        );
        assert!(excerpt.ends_with('\u{2026}'));
    }

    #[test]
    fn short_body_is_returned_verbatim() {
        assert_eq!(derive_journal_excerpt(Some("short."), None), Some("short.".to_string()));
    }
}

#[cfg(test)]
mod relabel_summary_owner_tests {
    use super::RELABEL_SUMMARY_OWNER_SQL;

    /// Regression (CodeRabbit CRITICAL, #208×#214 interaction): `jsonb_agg` over
    /// zero rows returns SQL NULL, and `jsonb_set(target, path, NULL)` is STRICT
    /// and nulls the ENTIRE target. The `jsonb_typeof(...) = 'array'` guard admits
    /// an EMPTY `action_items` array, so without COALESCE a speaker relabel on a
    /// meeting with no action items would wipe the whole `summary` column. The
    /// COALESCE to `'[]'::jsonb` is what prevents that data loss.
    #[test]
    fn coalesces_empty_aggregate_to_preserve_summary() {
        assert!(
            RELABEL_SUMMARY_OWNER_SQL.contains("COALESCE(jsonb_agg("),
            "relabel_summary_owner must COALESCE the aggregate so an empty \
             action_items array can't null out the whole summary column: {RELABEL_SUMMARY_OWNER_SQL}"
        );
        // Bare `jsonb_agg(` without the COALESCE wrapper must NOT appear — that's
        // exactly the null-out bug. (The COALESCE form embeds `COALESCE(jsonb_agg`,
        // so assert there is no occurrence of `jsonb_agg(` NOT preceded by it.)
        assert!(
            !RELABEL_SUMMARY_OWNER_SQL.contains("SELECT jsonb_agg("),
            "the aggregate must be wrapped in COALESCE, never bare"
        );
    }

    /// The write must only ever touch the `{action_items}` path of `summary`, and
    /// only when an owner actually matches — never rewrite the whole column.
    #[test]
    fn targets_action_items_path_and_guards_on_a_real_match() {
        assert!(RELABEL_SUMMARY_OWNER_SQL.contains("jsonb_set(summary, '{action_items}'"));
        assert!(
            RELABEL_SUMMARY_OWNER_SQL.contains("jsonb_typeof(summary->'action_items') = 'array'"),
            "must keep the array-shape guard"
        );
        assert!(
            RELABEL_SUMMARY_OWNER_SQL.contains("AND EXISTS ("),
            "must skip the write when no owner matches, so rows_affected is honest"
        );
    }
}

/// Regression (CodeRabbit MINOR, PR #532): `membership_events` rows written
/// inside one transaction can share an identical `created_at` (Postgres
/// transaction-time default), so `ORDER BY created_at DESC` alone is not a
/// stable sort for LIMIT/OFFSET paging. This asserts the `id` tiebreak stays
/// in the shared query text used by both `list_membership_events` and
/// `list_membership_events_scoped`.
#[cfg(test)]
mod list_membership_events_sql_tests {
    use super::LIST_MEMBERSHIP_EVENTS_SQL;

    #[test]
    fn orders_by_created_at_then_id_both_descending() {
        assert!(
            LIST_MEMBERSHIP_EVENTS_SQL.contains("ORDER BY created_at DESC, id DESC"),
            "pagination needs a deterministic tiebreak on `id` for rows that \
             share a `created_at` timestamp: {LIST_MEMBERSHIP_EVENTS_SQL}"
        );
    }

    #[test]
    fn scopes_to_one_team_and_respects_the_page_window() {
        assert!(LIST_MEMBERSHIP_EVENTS_SQL.contains("WHERE team_id = $1"));
        assert!(LIST_MEMBERSHIP_EVENTS_SQL.contains("LIMIT $2 OFFSET $3"));
    }
}

#[cfg(test)]
mod conflict_dismissal_verdict_tests {
    use super::{conflict_dismissal_expires_at, ConflictDismissalVerdict};
    use chrono::{DateTime, Utc};

    #[test]
    fn as_str_and_parse_round_trip() {
        for v in [ConflictDismissalVerdict::Different, ConflictDismissalVerdict::Unsure] {
            assert_eq!(ConflictDismissalVerdict::parse(v.as_str()), Some(v));
        }
    }

    #[test]
    fn parse_rejects_conflicts_and_garbage() {
        // "conflicts" is deliberately not a valid `conflict_dismissal.verdict`
        // — a confirmed conflict writes a supersession_edge instead, it has
        // nothing to be "dismissed" from.
        assert_eq!(ConflictDismissalVerdict::parse("conflicts"), None);
        assert_eq!(ConflictDismissalVerdict::parse(""), None);
        assert_eq!(ConflictDismissalVerdict::parse("Different"), None);
    }

    /// The core of the expiry-policy decision (migration 0112's header):
    /// "different" is a judgement about the claims themselves and never
    /// expires by time.
    #[test]
    fn different_never_expires() {
        let now: DateTime<Utc> = "2026-06-01T00:00:00Z".parse().unwrap();
        assert_eq!(conflict_dismissal_expires_at(ConflictDismissalVerdict::Different, now), None);
    }

    /// "unsure" is a judgement about currently-available evidence and DOES
    /// expire, on the query-time-enforced TTL — never permanently suppressed,
    /// since the corpus may grow enough to make the pair answerable.
    #[test]
    fn unsure_expires_after_the_configured_ttl() {
        let now: DateTime<Utc> = "2026-06-01T00:00:00Z".parse().unwrap();
        let expires = conflict_dismissal_expires_at(ConflictDismissalVerdict::Unsure, now)
            .expect("an 'unsure' dismissal must carry an expiry");
        let ttl_days = crate::llm::model_config::unsure_dismissal_ttl_days();
        assert_eq!(expires, now + chrono::Duration::days(ttl_days));
        assert!(expires > now, "the expiry must be strictly in the future of dismissed_at");
    }
}

#[cfg(test)]
mod journal_input_fingerprint_tests {
    use super::journal_input_fingerprint;
    use chrono::{DateTime, Utc};
    use uuid::Uuid;

    fn ts(s: &str) -> DateTime<Utc> {
        s.parse().unwrap()
    }

    /// Same three inputs must always hash to the same fingerprint — the
    /// property `Store::journal_dirty_hours` relies on to compare "what's
    /// stored" against "what's current" across two separate calls (and,
    /// per the doc comment on `journal_input_fingerprint`, across whatever
    /// caller derives it — the whole point of having exactly one
    /// implementation).
    #[test]
    fn stable_for_the_same_inputs() {
        let max_created_at = ts("2026-07-15T09:30:00Z");
        let max_id = Uuid::parse_str("11111111-1111-1111-1111-111111111111").unwrap();
        let a = journal_input_fingerprint(3, max_created_at, max_id);
        let b = journal_input_fingerprint(3, max_created_at, max_id);
        assert_eq!(a, b);
        // 32 lowercase hex characters — an md5 digest.
        assert_eq!(a.len(), 32);
        assert!(a.chars().all(|c| c.is_ascii_hexdigit() && !c.is_ascii_uppercase()));
    }

    /// A deleted atom drops `input_count` without necessarily moving
    /// `max(created_at)`/`max(id)` — see migration 0113's header for why
    /// the count is folded into the hash at all, not just the two maxes.
    #[test]
    fn sensitive_to_input_count() {
        let max_created_at = ts("2026-07-15T09:30:00Z");
        let max_id = Uuid::parse_str("11111111-1111-1111-1111-111111111111").unwrap();
        let three = journal_input_fingerprint(3, max_created_at, max_id);
        let four = journal_input_fingerprint(4, max_created_at, max_id);
        assert_ne!(three, four);
    }

    #[test]
    fn sensitive_to_max_created_at() {
        let max_id = Uuid::parse_str("11111111-1111-1111-1111-111111111111").unwrap();
        let earlier = journal_input_fingerprint(3, ts("2026-07-15T09:30:00Z"), max_id);
        let later = journal_input_fingerprint(3, ts("2026-07-15T09:30:01Z"), max_id);
        assert_ne!(earlier, later);
    }

    #[test]
    fn sensitive_to_max_id() {
        let max_created_at = ts("2026-07-15T09:30:00Z");
        let a = journal_input_fingerprint(
            3,
            max_created_at,
            Uuid::parse_str("11111111-1111-1111-1111-111111111111").unwrap(),
        );
        let b = journal_input_fingerprint(
            3,
            max_created_at,
            Uuid::parse_str("22222222-2222-2222-2222-222222222222").unwrap(),
        );
        assert_ne!(a, b);
    }

    /// Sub-second precision must not be lost — two hours whose atoms differ
    /// only in microseconds are genuinely different inputs and must not
    /// collide on a fingerprint that silently truncated to whole seconds.
    #[test]
    fn microsecond_precision_is_not_lost() {
        let max_id = Uuid::parse_str("11111111-1111-1111-1111-111111111111").unwrap();
        let a = journal_input_fingerprint(1, ts("2026-07-15T09:30:00.000001Z"), max_id);
        let b = journal_input_fingerprint(1, ts("2026-07-15T09:30:00.000002Z"), max_id);
        assert_ne!(a, b);
    }
}

#[cfg(test)]
mod truncate_excerpt_tests {
    use super::truncate_excerpt;

    #[test]
    fn short_string_is_returned_unchanged() {
        assert_eq!(truncate_excerpt("hello", 280), "hello");
    }

    #[test]
    fn exact_length_is_not_truncated() {
        let s = "x".repeat(280);
        assert_eq!(truncate_excerpt(&s, 280), s);
    }

    #[test]
    fn over_length_is_cut_with_an_ellipsis() {
        let s = "x".repeat(281);
        let out = truncate_excerpt(&s, 280);
        assert_eq!(out.chars().count(), 281); // 280 kept chars + the ellipsis char
        assert!(out.ends_with('\u{2026}'));
        assert_eq!(&out[..280], &s[..280]);
    }

    /// Character-counted, not byte-counted: a multibyte character must count
    /// as ONE character toward the cap, and truncation must never land mid
    /// character (see the function's own doc comment).
    #[test]
    fn multibyte_characters_count_as_one_char_each() {
        let s = "café".repeat(100); // 400 chars, well over any small cap
        let out = truncate_excerpt(&s, 10);
        assert_eq!(out.chars().count(), 11); // 10 kept chars + ellipsis
        assert!(out.ends_with('\u{2026}'));
        // Every prefix character survived intact (no broken UTF-8 sequence).
        assert_eq!(out.chars().take(10).collect::<String>(), s.chars().take(10).collect::<String>());
    }
}

// ── Live-Postgres tests: `PostgresStore::account_is_real_org` ───────────────
//
// Gated on `RELINFER_TEST_DATABASE_URL`, same convention as every other
// `pg_tests` module in this crate (`routes::checkout::pg_tests`,
// `routes::usage::pg_tests`, `routes::admin::pg_tests`). `cargo test --lib`
// with no env var set SKIPS these with an `eprintln!` marker rather than
// failing. Every test mints FRESH `Uuid::new_v4()` accounts/users, so tests
// never collide with whatever else is in the shared test database.
//
// This is the ONE place `account_is_real_org`'s personal-org join is
// exercised directly — its route callers add nothing of their own beyond
// wiring, so proving the predicate itself covers their actual behavior.
#[cfg(test)]
mod personal_org_pg_tests {
    use super::{PostgresStore, Store};
    use uuid::Uuid;

    async fn pg_test_pool(test_name: &str) -> Option<sqlx::PgPool> {
        let url = match std::env::var("RELINFER_TEST_DATABASE_URL") {
            Ok(u) => u,
            Err(_) => {
                eprintln!("skipping {test_name}: set RELINFER_TEST_DATABASE_URL to run it");
                return None;
            }
        };
        Some(
            sqlx::postgres::PgPoolOptions::new()
                .max_connections(4)
                .connect(&url)
                .await
                .expect("connect to test Postgres"),
        )
    }

    /// `clerk_user_id` is `NULL` unless given — only rows this predicate's
    /// `personal_orgs` join needs to find carry one.
    async fn seed_user(pool: &sqlx::PgPool, clerk_user_id: Option<&str>) -> Uuid {
        sqlx::query_scalar("INSERT INTO users (email, clerk_user_id) VALUES ($1, $2) RETURNING id")
            .bind(format!("{}@account-is-real-org-prtest.test", Uuid::new_v4()))
            .bind(clerk_user_id)
            .fetch_one(pool)
            .await
            .expect("insert user")
    }

    async fn seed_account(pool: &sqlx::PgPool, owner_user_id: Uuid, clerk_org_id: Option<&str>) -> Uuid {
        sqlx::query_scalar(
            "INSERT INTO accounts (owner_user_id, clerk_org_id) VALUES ($1, $2) RETURNING id",
        )
        .bind(owner_user_id)
        .bind(clerk_org_id)
        .fetch_one(pool)
        .await
        .expect("insert account")
    }

    async fn seed_personal_org(pool: &sqlx::PgPool, clerk_org_id: &str, clerk_user_id: &str) {
        sqlx::query("INSERT INTO personal_orgs (clerk_org_id, clerk_user_id) VALUES ($1, $2)")
            .bind(clerk_org_id)
            .bind(clerk_user_id)
            .execute(pool)
            .await
            .expect("insert personal_orgs row");
    }

    /// `0176_seat_lifecycle.sql`'s `account_members_default_seat_tier` trigger
    /// hard-refuses (RAISE EXCEPTION, not a silent default) an org-account
    /// `account_members` INSERT with no `seat_tier_id` — every test below that
    /// inserts a member row on a `clerk_org_id`-carrying account must supply
    /// one explicitly.
    async fn standard_seat_tier_id(pool: &sqlx::PgPool) -> Uuid {
        sqlx::query_scalar("SELECT id FROM seat_tiers WHERE code = 'standard' AND is_active = true")
            .fetch_one(pool)
            .await
            .expect("standard seat tier must be seeded (0165)")
    }

    async fn cleanup(pool: &sqlx::PgPool, account_id: Uuid, user_ids: &[Uuid], org_id: Option<&str>) {
        sqlx::query("DELETE FROM accounts WHERE id = $1").bind(account_id).execute(pool).await.ok();
        for u in user_ids {
            sqlx::query("DELETE FROM users WHERE id = $1").bind(u).execute(pool).await.ok();
        }
        if let Some(org_id) = org_id {
            sqlx::query("DELETE FROM personal_orgs WHERE clerk_org_id = $1")
                .bind(org_id)
                .execute(pool)
                .await
                .ok();
        }
    }

    /// **Shape 1 — plain personal account** (`clerk_org_id IS NULL`). Never a
    /// real org, for anyone.
    #[tokio::test]
    async fn plain_personal_account_is_never_a_real_org() {
        let Some(pool) = pg_test_pool("plain_personal_account_is_never_a_real_org").await else {
            return;
        };
        let owner = seed_user(&pool, None).await;
        let account_id = seed_account(&pool, owner, None).await;
        let store = PostgresStore::new(pool.clone());

        let is_real = store.account_is_real_org(account_id, owner).await.expect("query must succeed");

        cleanup(&pool, account_id, &[owner], None).await;
        assert!(!is_real, "a plain clerk_org_id-IS-NULL account must never read as a real org");
    }

    /// **Shape 2 — personal org, the owner's own point of view.** This is
    /// the exact case `account_is_org` (the naive `clerk_org_id IS NOT NULL`
    /// read) gets wrong: it would read `true` here, exactly as if this were
    /// a real organization.
    #[tokio::test]
    async fn personal_org_owner_does_not_see_their_own_org_as_real() {
        let Some(pool) = pg_test_pool("personal_org_owner_does_not_see_their_own_org_as_real").await else {
            return;
        };
        let clerk_user_id = format!("user_{}", Uuid::new_v4().simple());
        let clerk_org_id = format!("org_{}", Uuid::new_v4().simple());
        let owner = seed_user(&pool, Some(&clerk_user_id)).await;
        let account_id = seed_account(&pool, owner, Some(&clerk_org_id)).await;
        seed_personal_org(&pool, &clerk_org_id, &clerk_user_id).await;
        let store = PostgresStore::new(pool.clone());

        let is_real = store.account_is_real_org(account_id, owner).await.expect("query must succeed");

        cleanup(&pool, account_id, &[owner], Some(&clerk_org_id)).await;
        assert!(
            !is_real,
            "a personal org's own account must read as NOT a real org from its owner's point of view"
        );
    }

    /// **Shape 3 — the same personal org, from a SECOND person's point of
    /// view.** This codebase does not control a personal org's Clerk-side
    /// membership, so a second real member can exist there; for THAT person
    /// the org is an ordinary one, not their own personal home. Proves the
    /// `u.id = $2` join (matched on the CALLER, not the org id alone) is
    /// load-bearing — the naive `EXISTS` version without it would say
    /// `false` here too, silently letting a second member treat someone
    /// else's personal org as their own.
    #[tokio::test]
    async fn a_second_members_view_of_someone_elses_personal_org_is_a_real_org() {
        let Some(pool) =
            pg_test_pool("a_second_members_view_of_someone_elses_personal_org_is_a_real_org").await
        else {
            return;
        };
        let owner_clerk_user_id = format!("user_{}", Uuid::new_v4().simple());
        let clerk_org_id = format!("org_{}", Uuid::new_v4().simple());
        let owner = seed_user(&pool, Some(&owner_clerk_user_id)).await;
        let account_id = seed_account(&pool, owner, Some(&clerk_org_id)).await;
        seed_personal_org(&pool, &clerk_org_id, &owner_clerk_user_id).await;
        // A second, unrelated user — never named in `personal_orgs` at all.
        let second_member = seed_user(&pool, Some(&format!("user_{}", Uuid::new_v4().simple()))).await;
        let store = PostgresStore::new(pool.clone());

        let is_real =
            store.account_is_real_org(account_id, second_member).await.expect("query must succeed");

        cleanup(&pool, account_id, &[owner, second_member], Some(&clerk_org_id)).await;
        assert!(
            is_real,
            "someone else's personal org must read as a real org from a second member's point of view"
        );
    }

    /// **Shape 4 — a real, multi-person organization** (`clerk_org_id` set,
    /// no `personal_orgs` row at all). Must read `true` regardless of which
    /// member is asking — the control this whole PR must not weaken.
    #[tokio::test]
    async fn a_real_org_reads_as_a_real_org() {
        let Some(pool) = pg_test_pool("a_real_org_reads_as_a_real_org").await else {
            return;
        };
        let clerk_org_id = format!("org_{}", Uuid::new_v4().simple());
        let owner = seed_user(&pool, Some(&format!("user_{}", Uuid::new_v4().simple()))).await;
        let account_id = seed_account(&pool, owner, Some(&clerk_org_id)).await;
        let store = PostgresStore::new(pool.clone());

        let is_real = store.account_is_real_org(account_id, owner).await.expect("query must succeed");

        cleanup(&pool, account_id, &[owner], None).await;
        assert!(is_real, "a real, un-adopted org account must still read as a real org");
    }

    /// **Fail-closed on a missing account row (finding 4, PR 829 review).**
    /// Before this fix `account_is_real_org` read `Ok(false)` for an
    /// `account_id` with no `accounts` row at all — fail-OPEN for its two
    /// route consumers (`create_graph`, `sync::push`), while
    /// `require_purchase_authority` (which now calls this method instead of
    /// duplicating its SQL) has always treated the same case as an error.
    #[tokio::test]
    async fn account_is_real_org_fails_closed_when_the_account_row_is_missing() {
        let Some(pool) =
            pg_test_pool("account_is_real_org_fails_closed_when_the_account_row_is_missing").await
        else {
            return;
        };
        let store = PostgresStore::new(pool.clone());

        let result = store.account_is_real_org(Uuid::new_v4(), Uuid::new_v4()).await;

        assert!(
            matches!(result, Err(crate::store::StoreError::NotFound)),
            "a missing accounts row must fail closed (StoreError::NotFound), not read as `Ok(false)`: {result:?}"
        );
    }

    // ── Live-Postgres tests: `PostgresStore::account_has_multiple_members` ──
    //
    // The ADR-0007 D2 gate `account_is_real_org` alone cannot express (finding
    // 1, PR 829 review): a personal org's account reads `false` from
    // `account_is_real_org` for EVERY one of its members, regardless of how
    // many `account_members` rows it actually holds.

    /// A single-member account — plain personal, personal org, or real org —
    /// must never read as "multiple members".
    #[tokio::test]
    async fn account_has_multiple_members_is_false_for_a_single_member_account() {
        let Some(pool) =
            pg_test_pool("account_has_multiple_members_is_false_for_a_single_member_account").await
        else {
            return;
        };
        let clerk_user_id = format!("user_{}", Uuid::new_v4().simple());
        let clerk_org_id = format!("org_{}", Uuid::new_v4().simple());
        let owner = seed_user(&pool, Some(&clerk_user_id)).await;
        let account_id = seed_account(&pool, owner, Some(&clerk_org_id)).await;
        seed_personal_org(&pool, &clerk_org_id, &clerk_user_id).await;
        let tier_id = standard_seat_tier_id(&pool).await;
        sqlx::query(
            "INSERT INTO account_members (account_id, user_id, role, seat_tier_id) VALUES ($1, $2, 'owner', $3)",
        )
        .bind(account_id)
        .bind(owner)
        .bind(tier_id)
        .execute(&pool)
        .await
        .expect("insert the owner's own account_members row");
        let store = PostgresStore::new(pool.clone());

        let multiple = store.account_has_multiple_members(account_id).await.expect("query must succeed");

        sqlx::query("DELETE FROM account_members WHERE account_id = $1").bind(account_id).execute(&pool).await.ok();
        cleanup(&pool, account_id, &[owner], Some(&clerk_org_id)).await;
        assert!(!multiple, "an account with exactly one member must not read as `multiple members`");
    }

    /// **The D2 case this method exists for.** A personal org that has
    /// (against its own one-member design, `personal_orgs.clerk_user_id
    /// UNIQUE`) gained a SECOND `account_members` row must read `true` —
    /// `resolve_reachable_graphs` (control migration
    /// `0132_reachable_graphs_team_id.sql`) would return every
    /// `kind='personal'` ocean in this account to BOTH rows, with no further
    /// filter.
    #[tokio::test]
    async fn account_has_multiple_members_is_true_when_a_personal_org_gains_a_second_member() {
        let Some(pool) = pg_test_pool(
            "account_has_multiple_members_is_true_when_a_personal_org_gains_a_second_member",
        )
        .await
        else {
            return;
        };
        let clerk_user_id = format!("user_{}", Uuid::new_v4().simple());
        let clerk_org_id = format!("org_{}", Uuid::new_v4().simple());
        let owner = seed_user(&pool, Some(&clerk_user_id)).await;
        let account_id = seed_account(&pool, owner, Some(&clerk_org_id)).await;
        seed_personal_org(&pool, &clerk_org_id, &clerk_user_id).await;
        let second_member = seed_user(&pool, Some(&format!("user_{}", Uuid::new_v4().simple()))).await;
        let tier_id = standard_seat_tier_id(&pool).await;
        sqlx::query(
            "INSERT INTO account_members (account_id, user_id, role, seat_tier_id) VALUES ($1, $2, 'owner', $3)",
        )
        .bind(account_id)
        .bind(owner)
        .bind(tier_id)
        .execute(&pool)
        .await
        .expect("insert the owner's own account_members row");
        sqlx::query(
            "INSERT INTO account_members (account_id, user_id, role, seat_tier_id) VALUES ($1, $2, 'member', $3)",
        )
        .bind(account_id)
        .bind(second_member)
        .bind(tier_id)
        .execute(&pool)
        .await
        .expect("insert the second member's account_members row");
        let store = PostgresStore::new(pool.clone());

        let multiple = store.account_has_multiple_members(account_id).await.expect("query must succeed");

        sqlx::query("DELETE FROM account_members WHERE account_id = $1").bind(account_id).execute(&pool).await.ok();
        cleanup(&pool, account_id, &[owner, second_member], Some(&clerk_org_id)).await;
        assert!(
            multiple,
            "a personal org's account with a second account_members row must read as `multiple members`"
        );
    }
}

#[cfg(test)]
mod alias_lookup_index_tests {
    /// Reef resolution looks nodes up by title or alias on the extraction
    /// publication path, one graph at a time. `idx_nodes_aliases_gin` serves
    /// only the `?` operator: the planner cannot use a GIN index for the
    /// `jsonb_exists()` function form, so `lower(title)=.. OR jsonb_exists(..)`
    /// filtered every node of the (graph, type). On prod (2026-10-22, 42k
    /// entity nodes) that was 75 ms per lookup with a warm cache, several
    /// seconds per publication, and publications of one graph are serialized.
    /// With `?` the plan is a BitmapOr of the title index and the GIN index
    /// (0.8 ms).
    #[test]
    fn alias_lookups_use_the_indexable_operator() {
        let source = include_str!("mod.rs");
        let function_form = ["jsonb_", "exists("].concat();
        let offenders: Vec<&str> = source
            .lines()
            .filter(|line| line.contains(&function_form) && line.contains("'aliases'"))
            .collect();
        assert!(offenders.is_empty(), "alias lookups must use `(body->'aliases') ? key`: {offenders:#?}");
    }
}
